#pragma once

#include <cstddef>
#include <cstdint>
#include <string_view>

namespace infer {

// 推理引擎里的张量在运行期才知道自己是什么数据类型（从模型文件读出来才知道），
// 所以类型用枚举在"运行期"记录，而不是做成 Tensor<float> 这种编译期模板。
// 这是 ggml / onnxruntime / PyTorch 的共同选择。
enum class DType : std::uint8_t {
  F32,  // 32 位浮点，第 1~5 阶段全程使用
  F16,  // 16 位浮点，第 7 阶段量化时登场
  I32,
  I8,   // 8 位整数，量化后的权重
};

// constexpr 函数：如果实参是编译期常量，整个调用会在编译期算完，运行期零开销。
[[nodiscard]] constexpr std::size_t dtype_size(DType t) noexcept {
  switch (t) {
    case DType::F32: return 4;
    case DType::F16: return 2;
    case DType::I32: return 4;
    case DType::I8:  return 1;
  }
  return 0;
}

[[nodiscard]] constexpr std::string_view dtype_name(DType t) noexcept {
  switch (t) {
    case DType::F32: return "f32";
    case DType::F16: return "f16";
    case DType::I32: return "i32";
    case DType::I8:  return "i8";
  }
  return "?";
}

}  // namespace infer

#pragma once

#include <concepts>
#include <cstddef>
#include <cstdint>
#include <initializer_list>
#include <memory>
#include <span>
#include <string>
#include <vector>

#include "infer/dtype.hpp"

namespace infer {

using i64 = std::int64_t;

// 形状：shape = {2, 3} 表示 2 行 3 列。标量的 shape 是空的 {}。
using Shape = std::vector<i64>;

// ---------------------------------------------------------------------------
// Tensor：多维数组
//
// 一个张量 = 一块连续内存(storage_) + 一副"怎么读这块内存"的说明书(shape_/strides_/offset_)。
// 多个张量可以共享同一块内存，各自拿着不同的说明书 —— 这就是 view(视图)，
// 转置、切片、reshape 都靠它做到零拷贝。
// ---------------------------------------------------------------------------
class Tensor {
 public:
  Tensor() = default;

  // --- 构造 ---------------------------------------------------------------
  static Tensor zeros(Shape shape, DType dtype = DType::F32);
  static Tensor full(Shape shape, float value);
  static Tensor arange(i64 n);                                  // 0,1,2,...,n-1
  static Tensor from(Shape shape, std::span<const float> data); // 拷贝一份数据
  static Tensor from(Shape shape, std::initializer_list<float> data);

  // --- 元信息 -------------------------------------------------------------
  [[nodiscard]] const Shape& shape() const noexcept { return shape_; }
  [[nodiscard]] const Shape& strides() const noexcept { return strides_; }
  [[nodiscard]] i64 dim(i64 i) const { return shape_.at(static_cast<std::size_t>(i)); }
  [[nodiscard]] i64 ndim() const noexcept { return static_cast<i64>(shape_.size()); }
  [[nodiscard]] i64 numel() const noexcept { return numel_; }
  [[nodiscard]] DType dtype() const noexcept { return dtype_; }
  [[nodiscard]] bool empty() const noexcept { return numel_ == 0; }

  // 内存是否"紧凑"：元素在内存里按行优先顺序一个挨一个排列，中间没有跳跃。
  // 转置后的张量就不再连续了，很多高性能 kernel 要求输入必须连续。
  [[nodiscard]] bool is_contiguous() const noexcept;

  // --- 数据访问 -----------------------------------------------------------
  // std::span 是 C++20 的"胖指针"：指针 + 长度，越界时在 Debug 构建能被查出来，
  // 而且传参不会像 vector 那样发生拷贝。以后所有 kernel 的入参都用它。
  [[nodiscard]] std::span<float> data();
  [[nodiscard]] std::span<const float> data() const;

  // 按下标取元素：t(1, 2) 取第 1 行第 2 列。
  // std::integral 是 C++20 concept，保证只有整数类型能传进来，
  // 写成 t(1.5) 会在编译期直接报错，而且报错信息可读。
  template <std::integral... Idx>
  [[nodiscard]] float& operator()(Idx... idx) {
    const i64 raw[] = {static_cast<i64>(idx)...};
    return raw_ptr()[offset_of(std::span<const i64>{raw, sizeof...(Idx)})];
  }

  template <std::integral... Idx>
  [[nodiscard]] const float& operator()(Idx... idx) const {
    const i64 raw[] = {static_cast<i64>(idx)...};
    return raw_ptr()[offset_of(std::span<const i64>{raw, sizeof...(Idx)})];
  }

  // --- 变换（以下全部零拷贝，返回共享同一块内存的 view） ---------------------
  [[nodiscard]] Tensor reshape(Shape new_shape) const;          // 要求当前是连续的
  [[nodiscard]] Tensor transpose(i64 a, i64 b) const;           // 交换两个轴
  [[nodiscard]] Tensor slice(i64 axis, i64 start, i64 end) const;  // 沿某轴切 [start,end)

  // 唯一会真正拷贝内存的操作：把 view 落实成一块紧凑内存。
  [[nodiscard]] Tensor contiguous() const;

  // --- 调试 ---------------------------------------------------------------
  [[nodiscard]] std::string to_string() const;    // 打印形状和全部数据
  [[nodiscard]] std::string meta_string() const;  // 只打印形状/步长等元信息

 private:
  // shared_ptr 让多个 view 安全地共享同一块内存：最后一个 view 析构时才释放。
  std::shared_ptr<std::byte[]> storage_;
  Shape shape_;
  Shape strides_;     // 单位是"元素个数"，不是字节
  i64 offset_ = 0;    // 本 view 的第一个元素在 storage_ 中的元素下标
  i64 numel_ = 0;
  DType dtype_ = DType::F32;

  [[nodiscard]] float* raw_ptr() {
    return reinterpret_cast<float*>(storage_.get());
  }
  [[nodiscard]] const float* raw_ptr() const {
    return reinterpret_cast<const float*>(storage_.get());
  }
  [[nodiscard]] i64 offset_of(std::span<const i64> idx) const;
};

// 由 shape 推出行优先(row-major)的默认步长。
[[nodiscard]] Shape contiguous_strides(const Shape& shape);

// shape 里所有维度相乘 = 元素总数。
[[nodiscard]] i64 numel_of(const Shape& shape);

}  // namespace infer

#include "infer/tensor.hpp"

#include <algorithm>
#include <format>
#include <numeric>
#include <ranges>
#include <stdexcept>

namespace infer {

namespace {

// 统一的错误抛出口。推理引擎里"形状对不上"是最高频的 bug，
// 报错信息里一定要带上真实形状，否则调试会非常痛苦。
[[noreturn]] void fail(const std::string& msg) {
  throw std::invalid_argument("[infer] " + msg);
}

std::string shape_str(const Shape& s) {
  std::string out = "(";
  for (std::size_t i = 0; i < s.size(); ++i) {
    out += std::format("{}{}", s[i], i + 1 < s.size() ? ", " : "");
  }
  return out + ")";
}

}  // namespace

i64 numel_of(const Shape& shape) {
  // C++20 ranges 的写法。空 shape {} 表示标量，累乘结果是 1，正好符合语义。
  return std::accumulate(shape.begin(), shape.end(), i64{1}, std::multiplies<>{});
}

Shape contiguous_strides(const Shape& shape) {
  // 行优先(row-major)：最后一个维度变化最快，它的步长永远是 1。
  // shape = (2, 3, 4)  ->  strides = (12, 4, 1)
  //   走一步最后一维，跳 1 个元素
  //   走一步中间维，  跳 4 个元素
  //   走一步第一维，  跳 3*4 = 12 个元素
  Shape strides(shape.size());
  i64 acc = 1;
  for (i64 i = static_cast<i64>(shape.size()) - 1; i >= 0; --i) {
    strides[static_cast<std::size_t>(i)] = acc;
    acc *= shape[static_cast<std::size_t>(i)];
  }
  return strides;
}

// ---------------------------------------------------------------------------
// 构造
// ---------------------------------------------------------------------------

Tensor Tensor::zeros(Shape shape, DType dtype) {
  if (std::ranges::any_of(shape, [](i64 d) { return d < 0; })) {
    fail("shape 里不允许出现负数维度：" + shape_str(shape));
  }
  Tensor t;
  t.numel_ = numel_of(shape);
  t.dtype_ = dtype;
  t.strides_ = contiguous_strides(shape);
  t.shape_ = std::move(shape);
  // make_shared<std::byte[]>(n) 是 C++20 新增的数组重载，并且会做值初始化(清零)。
  t.storage_ = std::make_shared<std::byte[]>(
      static_cast<std::size_t>(t.numel_) * dtype_size(dtype));
  return t;
}

Tensor Tensor::full(Shape shape, float value) {
  Tensor t = zeros(std::move(shape));
  std::ranges::fill(t.data(), value);
  return t;
}

Tensor Tensor::arange(i64 n) {
  Tensor t = zeros({n});
  std::span<float> d = t.data();
  for (i64 i = 0; i < n; ++i) {
    d[static_cast<std::size_t>(i)] = static_cast<float>(i);
  }
  return t;
}

Tensor Tensor::from(Shape shape, std::span<const float> src) {
  Tensor t = zeros(std::move(shape));
  if (static_cast<i64>(src.size()) != t.numel_) {
    fail(std::format("数据长度 {} 与形状 {} 所需的 {} 个元素不匹配",
                     src.size(), shape_str(t.shape_), t.numel_));
  }
  std::ranges::copy(src, t.data().begin());
  return t;
}

Tensor Tensor::from(Shape shape, std::initializer_list<float> src) {
  return from(std::move(shape), std::span<const float>{src.begin(), src.size()});
}

// ---------------------------------------------------------------------------
// 元信息 / 访问
// ---------------------------------------------------------------------------

bool Tensor::is_contiguous() const noexcept {
  return strides_ == contiguous_strides(shape_);
}

std::span<float> Tensor::data() {
  if (!is_contiguous()) {
    fail("非连续张量不能直接取 data()，请先调用 contiguous()");
  }
  return {raw_ptr() + offset_, static_cast<std::size_t>(numel_)};
}

std::span<const float> Tensor::data() const {
  if (!is_contiguous()) {
    fail("非连续张量不能直接取 data()，请先调用 contiguous()");
  }
  return {raw_ptr() + offset_, static_cast<std::size_t>(numel_)};
}

i64 Tensor::offset_of(std::span<const i64> idx) const {
  if (static_cast<i64>(idx.size()) != ndim()) {
    fail(std::format("给了 {} 个下标，但张量是 {} 维的 {}",
                     idx.size(), ndim(), shape_str(shape_)));
  }
  // 核心公式：线性偏移 = Σ 下标[i] * 步长[i]
  // 整个张量库的所有寻址都建立在这一行上。
  i64 off = offset_;
  for (std::size_t i = 0; i < idx.size(); ++i) {
    if (idx[i] < 0 || idx[i] >= shape_[i]) {
      fail(std::format("第 {} 维下标 {} 越界，该维大小为 {}", i, idx[i], shape_[i]));
    }
    off += idx[i] * strides_[i];
  }
  return off;
}

// ---------------------------------------------------------------------------
// 变换：只改"说明书"，不动内存
// ---------------------------------------------------------------------------

Tensor Tensor::reshape(Shape new_shape) const {
  if (!is_contiguous()) {
    fail("非连续张量不能 reshape，请先调用 contiguous()");
  }
  if (numel_of(new_shape) != numel_) {
    fail(std::format("reshape {} -> {} 元素个数不一致（{} vs {}）",
                     shape_str(shape_), shape_str(new_shape),
                     numel_, numel_of(new_shape)));
  }
  Tensor t = *this;  // 浅拷贝：storage_ 是 shared_ptr，这里只是引用计数 +1
  t.strides_ = contiguous_strides(new_shape);
  t.shape_ = std::move(new_shape);
  return t;
}

Tensor Tensor::transpose(i64 a, i64 b) const {
  if (a < 0 || b < 0 || a >= ndim() || b >= ndim()) {
    fail(std::format("transpose 轴 ({}, {}) 超出 {} 维张量的范围", a, b, ndim()));
  }
  // 转置只是把两个轴的 shape 和 stride 互换，一个字节都不用搬。
  // 代价是结果通常不再连续，用 data() 会报错，需要 contiguous() 落实。
  Tensor t = *this;
  std::swap(t.shape_[static_cast<std::size_t>(a)], t.shape_[static_cast<std::size_t>(b)]);
  std::swap(t.strides_[static_cast<std::size_t>(a)], t.strides_[static_cast<std::size_t>(b)]);
  return t;
}

Tensor Tensor::slice(i64 axis, i64 start, i64 end) const {
  if (axis < 0 || axis >= ndim()) {
    fail(std::format("slice 轴 {} 超出 {} 维张量的范围", axis, ndim()));
  }
  const auto ax = static_cast<std::size_t>(axis);
  if (start < 0 || end > shape_[ax] || start > end) {
    fail(std::format("slice 区间 [{}, {}) 超出该维大小 {}", start, end, shape_[ax]));
  }
  // 切片 = 起点往后挪 start*stride，再把这一维的长度改小。
  Tensor t = *this;
  t.offset_ += start * strides_[ax];
  t.shape_[ax] = end - start;
  t.numel_ = numel_of(t.shape_);
  return t;
}

Tensor Tensor::contiguous() const {
  if (is_contiguous()) {
    return *this;  // 已经紧凑，不用白拷一遍
  }
  Tensor out = zeros(shape_, dtype_);
  std::span<float> dst = out.data();

  // 按行优先顺序遍历所有逻辑位置，用多维计数器手动进位。
  // 这个"计数器 + 进位"的套路在 broadcast、permute 里会反复出现。
  Shape idx(static_cast<std::size_t>(ndim()), 0);
  for (i64 linear = 0; linear < numel_; ++linear) {
    dst[static_cast<std::size_t>(linear)] = raw_ptr()[offset_of(idx)];
    for (i64 d = ndim() - 1; d >= 0; --d) {
      const auto ud = static_cast<std::size_t>(d);
      if (++idx[ud] < shape_[ud]) break;
      idx[ud] = 0;
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// 打印
// ---------------------------------------------------------------------------

std::string Tensor::meta_string() const {
  return std::format("Tensor(shape={}, strides={}, offset={}, numel={}, dtype={}, contiguous={})",
                     shape_str(shape_), shape_str(strides_), offset_, numel_,
                     dtype_name(dtype_), is_contiguous());
}

std::string Tensor::to_string() const {
  std::string out = meta_string() + "\n";
  if (numel_ == 0) return out + "[]";

  // 逐元素遍历（用 offset_of 所以非连续张量也能正确打印），
  // 每换一行插一个换行符，方便肉眼核对矩阵。
  const i64 last = ndim() > 0 ? shape_.back() : 1;
  Shape idx(static_cast<std::size_t>(ndim()), 0);
  for (i64 linear = 0; linear < numel_; ++linear) {
    if (linear % last == 0) out += "  [ ";
    out += std::format("{:8.4f} ", raw_ptr()[offset_of(idx)]);
    if ((linear + 1) % last == 0) out += "]\n";

    for (i64 d = ndim() - 1; d >= 0; --d) {
      const auto ud = static_cast<std::size_t>(d);
      if (++idx[ud] < shape_[ud]) break;
      idx[ud] = 0;
    }
  }
  return out;
}

}  // namespace infer

#pragma once

// ---------------------------------------------------------------------------
// 一个 60 行的极简测试框架。
//
// 原理：TEST(name) 宏会定义一个函数，并借助一个"全局对象的构造函数"
// 在 main() 开始之前就把这个函数注册进全局列表。main() 只要遍历列表逐个调用即可。
// Catch2 / GoogleTest 的自动注册机制本质上就是这一招。
// ---------------------------------------------------------------------------

#include <cmath>
#include <cstdio>
#include <exception>
#include <functional>
#include <string>
#include <vector>

namespace minitest {

struct Case {
  std::string name;
  std::function<void()> fn;
};

inline std::vector<Case>& registry() {
  static std::vector<Case> cases;  // 函数内 static：保证首次使用时才初始化，避开静态初始化顺序问题
  return cases;
}

struct Registrar {
  Registrar(std::string name, std::function<void()> fn) {
    registry().push_back({std::move(name), std::move(fn)});
  }
};

struct Failure : std::exception {
  std::string msg;
  explicit Failure(std::string m) : msg(std::move(m)) {}
  [[nodiscard]] const char* what() const noexcept override { return msg.c_str(); }
};

inline int run_all() {
  int failed = 0;
  for (const auto& c : registry()) {
    try {
      c.fn();
      std::printf("  \033[32mPASS\033[0m  %s\n", c.name.c_str());
    } catch (const std::exception& e) {
      std::printf("  \033[31mFAIL\033[0m  %s\n        %s\n", c.name.c_str(), e.what());
      ++failed;
    }
  }
  std::printf("\n%zu 个用例，\033[31m%d 个失败\033[0m\n", registry().size(), failed);
  return failed == 0 ? 0 : 1;
}

}  // namespace minitest

#define TEST(name)                                                       \
  static void test_##name();                                             \
  static ::minitest::Registrar reg_##name{#name, test_##name};           \
  static void test_##name()

#define CHECK(cond)                                                      \
  do {                                                                   \
    if (!(cond)) {                                                       \
      throw ::minitest::Failure(std::string("CHECK 失败: " #cond " @ ")  \
                                + __FILE__ + ":" + std::to_string(__LINE__)); \
    }                                                                    \
  } while (0)

#define CHECK_NEAR(a, b, eps)                                            \
  do {                                                                   \
    const double va = (a), vb = (b);                                     \
    if (std::fabs(va - vb) > (eps)) {                                    \
      throw ::minitest::Failure("CHECK_NEAR 失败: " #a "=" + std::to_string(va) \
                                + " vs " #b "=" + std::to_string(vb)     \
                                + " @ " + __FILE__ + ":" + std::to_string(__LINE__)); \
    }                                                                    \
  } while (0)

// 断言某段代码一定会抛异常（用来测试错误处理路径）
#define CHECK_THROWS(expr)                                               \
  do {                                                                   \
    bool thrown = false;                                                 \
    try { (void)(expr); } catch (...) { thrown = true; }                 \
    if (!thrown) {                                                       \
      throw ::minitest::Failure("期望 " #expr " 抛异常，但它没有 @ "      \
                                + std::string(__FILE__) + ":" + std::to_string(__LINE__)); \
    }                                                                    \
  } while (0)

#include "infer/tensor.hpp"
#include "minitest.hpp"

using infer::Tensor;

TEST(shape_and_strides) {
  Tensor t = Tensor::zeros({2, 3, 4});
  CHECK(t.ndim() == 3);
  CHECK(t.numel() == 24);
  // 行优先：最后一维步长为 1，往前依次累乘
  CHECK((t.strides() == infer::Shape{12, 4, 1}));
  CHECK(t.is_contiguous());
}

TEST(scalar_is_zero_dim) {
  Tensor s = Tensor::zeros({});
  CHECK(s.ndim() == 0);
  CHECK(s.numel() == 1);  // 标量含 1 个元素
}

TEST(indexing) {
  Tensor t = Tensor::from({2, 3}, {1, 2, 3,
                                   4, 5, 6});
  CHECK_NEAR(t(0, 0), 1.0, 1e-6);
  CHECK_NEAR(t(1, 2), 6.0, 1e-6);
  t(1, 0) = 42.0F;
  CHECK_NEAR(t(1, 0), 42.0, 1e-6);
}

TEST(index_out_of_range_throws) {
  Tensor t = Tensor::zeros({2, 3});
  CHECK_THROWS(t(2, 0));   // 第 0 维只有 2 行，下标 2 越界
  CHECK_THROWS(t(0));      // 维数给少了
}

TEST(reshape_shares_memory) {
  Tensor a = Tensor::arange(6);
  Tensor b = a.reshape({2, 3});
  CHECK(b.numel() == 6);
  CHECK_NEAR(b(1, 2), 5.0, 1e-6);

  b(0, 0) = 99.0F;          // 改 b
  CHECK_NEAR(a(0), 99.0, 1e-6);  // a 跟着变，证明是同一块内存
}

TEST(transpose_is_a_view) {
  Tensor a = Tensor::from({2, 3}, {1, 2, 3,
                                   4, 5, 6});
  Tensor at = a.transpose(0, 1);

  CHECK((at.shape() == infer::Shape{3, 2}));
  CHECK((at.strides() == infer::Shape{1, 3}));  // 步长也跟着换了位置
  CHECK(!at.is_contiguous());                   // 转置后不再紧凑

  CHECK_NEAR(at(0, 1), 4.0, 1e-6);  // at[0][1] == a[1][0]
  CHECK_NEAR(at(2, 0), 3.0, 1e-6);  // at[2][0] == a[0][2]

  CHECK_THROWS(at.data());      // 非连续，禁止直接取裸内存
  CHECK_THROWS(at.reshape({6}));
}

TEST(contiguous_materializes) {
  Tensor a = Tensor::from({2, 3}, {1, 2, 3,
                                   4, 5, 6});
  Tensor c = a.transpose(0, 1).contiguous();

  CHECK(c.is_contiguous());
  // 转置后按行优先重新排布应为 1 4 2 5 3 6
  const infer::Shape expect_shape{3, 2};
  CHECK(c.shape() == expect_shape);
  const float want[] = {1, 4, 2, 5, 3, 6};
  auto got = c.data();
  for (std::size_t i = 0; i < 6; ++i) {
    CHECK_NEAR(got[i], want[i], 1e-6);
  }
}

TEST(slice_moves_offset) {
  Tensor a = Tensor::arange(12).reshape({3, 4});
  Tensor row = a.slice(0, 1, 2);  // 取第 1 行，形状 (1, 4)

  CHECK((row.shape() == infer::Shape{1, 4}));
  CHECK_NEAR(row(0, 0), 4.0, 1e-6);
  CHECK_NEAR(row(0, 3), 7.0, 1e-6);

  Tensor col = a.slice(1, 2, 4);  // 取第 2~3 列，形状 (3, 2)
  CHECK((col.shape() == infer::Shape{3, 2}));
  CHECK_NEAR(col(0, 0), 2.0, 1e-6);
  CHECK_NEAR(col(2, 1), 11.0, 1e-6);
  CHECK(!col.is_contiguous());  // 列切片跳着取，不连续
}

TEST(bad_construction_throws) {
  CHECK_THROWS(Tensor::from({2, 3}, {1, 2, 3}));  // 数据只有 3 个，形状要 6 个
  CHECK_THROWS(Tensor::zeros({2, 3}).reshape({5}));
}

#include <cstdio>

#include "minitest.hpp"

int main() {
  std::printf("\n运行测试用例：\n");
