using infer::Tensor;

void section(const char* title) {
  std::println("\n\033[36m===== {} =====\033[0m", title);
}

int main() {
  section("1. 造一个 2x3 的张量");
  Tensor a = Tensor::from({2, 3}, {1, 2, 3,
                                   4, 5, 6});
  std::print("{}", a.to_string());
  std::println("内存里实际的排列顺序（行优先）：");
  for (float v : a.data()) std::print("{} ", v);
  std::println("");

  section("2. reshape：说明书变了，内存没动");
  Tensor b = a.reshape({3, 2});
  std::print("{}", b.to_string());
  std::println("改 b(0,0)=99 之后，a 也会变 —— 它们共享同一块内存：");
  b(0, 0) = 99.0F;
  std::println("a(0,0) = {}", a(0, 0));
  a(0, 0) = 1.0F;  // 改回去

  section("3. transpose：只交换 shape 和 stride");
  Tensor at = a.transpose(0, 1);
  std::println("原张量 : {}", a.meta_string());
  std::println("转置后 : {}", at.meta_string());
  std::print("{}", at.to_string());
  std::println("注意 contiguous=false：逻辑上是 3x2，但内存顺序还是原来的 1 2 3 4 5 6。");

  section("4. contiguous：把 view 落实成真实内存（唯一发生拷贝的地方）");
  Tensor atc = at.contiguous();
  std::println("{}", atc.meta_string());
  std::print("内存顺序现在真的变了：");
  for (float v : atc.data()) std::print("{} ", v);
  std::println("");

  section("5. slice：把起点往后挪，再改一下这一维的长度");
  Tensor m = Tensor::arange(12).reshape({3, 4});
  std::print("{}", m.to_string());
  Tensor col = m.slice(1, 1, 3);  // 取第 1~2 列
  std::println("取第 1~2 列 -> {}", col.meta_string());
  std::print("{}", col.to_string());

  section("6. 越界和形状错误会立刻抛异常，而不是悄悄读脏数据");
  try {
    (void)m(5, 0);
  } catch (const std::exception& e) {
    std::println("捕获到：{}", e.what());
  }

  std::println("");
  return 0;
}

