#pragma once

#include <cstdint>
#include <span>

namespace infer::kernel {

using i64 = std::int64_t;

// ---------------------------------------------------------------------------
// Kernel 层：纯计算，不认识 Tensor，只认「一段连续内存 + 几个维度」。
//
// 为什么要把这层单独拆出来？
//   1. 阶段 5 做性能优化时，只改这一层，上层代码一行都不用动
//   2. 便于写 benchmark：直接喂裸数组，不受张量抽象的开销干扰
//   3. 这层的函数全都假设输入连续、形状已校验 —— 检查是上层 ops 的活儿
//
// 命名后缀 _f32 表示数据类型，阶段 7 量化后会出现 _q8 等版本。
// ---------------------------------------------------------------------------

// --- 逐元素（elementwise）-------------------------------------------------
void add_f32(std::span<const float> a, std::span<const float> b, std::span<float> out);
void mul_f32(std::span<const float> a, std::span<const float> b, std::span<float> out);
void add_scalar_f32(std::span<const float> a, float s, std::span<float> out);
void relu_f32(std::span<const float> x, std::span<float> out);
void gelu_f32(std::span<const float> x, std::span<float> out);       // tanh 近似版，GPT-2 用的就是这个
void gelu_exact_f32(std::span<const float> x, std::span<float> out); // erf 精确版，用来验证近似版误差

// --- 归约类（reduction）：都只处理「一行」，多行由上层循环 -------------------

// softmax：把一行数字变成和为 1 的概率分布
void softmax_f32(std::span<const float> x, std::span<float> out);

// layernorm：对一行做标准化后再缩放平移。w/b 长度必须等于 x
void layernorm_f32(std::span<const float> x, std::span<const float> w,
                   std::span<const float> b, std::span<float> out, float eps);

// rmsnorm：LLaMA 系模型用的简化版归一化，阶段 6 会用到
void rmsnorm_f32(std::span<const float> x, std::span<const float> w,
                 std::span<float> out, float eps);

// --- 矩阵乘法 -------------------------------------------------------------
// C[M,N] = A[M,K] × B[K,N]，全部行优先连续存储。
//
// 提供两个循环顺序不同、结果完全相同的版本。
// 它们的性能差距是阶段 5 的第一课 —— 跑 examples/02_ops 亲眼看看差多少。
void matmul_f32_ijk(std::span<const float> a, std::span<const float> b,
                    std::span<float> c, i64 M, i64 N, i64 K);
void matmul_f32_ikj(std::span<const float> a, std::span<const float> b,
                    std::span<float> c, i64 M, i64 N, i64 K);

// 默认实现，目前指向较快的那个。阶段 5 会把它换成优化版。
void matmul_f32(std::span<const float> a, std::span<const float> b,
                std::span<float> c, i64 M, i64 N, i64 K);

// C[M,N] = A[M,K] × Wᵀ，其中 W 的形状是 [N,K]。
// 为什么要单独写一个转置版？因为 PyTorch 的 Linear 层权重就存成 [out, in]，
// 而这个布局对 cache 反而更友好：A 和 W 都是按行连续读取的。
void matmul_nt_f32(std::span<const float> a, std::span<const float> w,
                   std::span<float> c, i64 M, i64 N, i64 K);

}  // namespace infer::kernel

#include "infer/kernel.hpp"

#include <algorithm>
#include <cmath>
#include <numbers>

namespace infer::kernel {

// ---------------------------------------------------------------------------
// 逐元素运算
// ---------------------------------------------------------------------------

void add_f32(std::span<const float> a, std::span<const float> b, std::span<float> out) {
  for (std::size_t i = 0; i < out.size(); ++i) out[i] = a[i] + b[i];
}

void mul_f32(std::span<const float> a, std::span<const float> b, std::span<float> out) {
  for (std::size_t i = 0; i < out.size(); ++i) out[i] = a[i] * b[i];
}

void add_scalar_f32(std::span<const float> a, float s, std::span<float> out) {
  for (std::size_t i = 0; i < out.size(); ++i) out[i] = a[i] + s;
}

void relu_f32(std::span<const float> x, std::span<float> out) {
  // 写成 max(0, x) 而不是 if/else，是因为编译器能把它变成一条无分支的
  // SIMD 指令（vmaxps）。分支预测失败的代价比计算本身大得多。
  for (std::size_t i = 0; i < out.size(); ++i) out[i] = std::max(0.0F, x[i]);
}

void gelu_f32(std::span<const float> x, std::span<float> out) {
  // GELU 的 tanh 近似式（GPT-2 / BERT 的官方实现用的就是这个）：
  //   gelu(x) ≈ 0.5x * (1 + tanh(√(2/π) * (x + 0.044715x³)))
  // 直觉：ReLU 在 0 处硬拐弯，GELU 是它的平滑版本，负值不会被一刀切掉。
  constexpr float kSqrt2OverPi = 0.7978845608028654F;  // √(2/π)
  constexpr float kCoeff = 0.044715F;
  for (std::size_t i = 0; i < out.size(); ++i) {
    const float v = x[i];
    const float inner = kSqrt2OverPi * (v + kCoeff * v * v * v);
    out[i] = 0.5F * v * (1.0F + std::tanh(inner));
  }
}

void gelu_exact_f32(std::span<const float> x, std::span<float> out) {
  // 精确定义：gelu(x) = x * Φ(x) = 0.5x * (1 + erf(x/√2))
  // 比 tanh 版慢，但可以用来衡量近似版的误差（约 1e-3 量级）。
  const float inv_sqrt2 = 1.0F / std::numbers::sqrt2_v<float>;
  for (std::size_t i = 0; i < out.size(); ++i) {
    out[i] = 0.5F * x[i] * (1.0F + std::erf(x[i] * inv_sqrt2));
  }
}

// ---------------------------------------------------------------------------
// 归约运算
// ---------------------------------------------------------------------------

void softmax_f32(std::span<const float> x, std::span<float> out) {
  if (x.empty()) return;

  // 【数值稳定性：本阶段最重要的一课】
  //
  // softmax 的数学定义是 exp(xᵢ) / Σexp(xⱼ)。直接照抄会炸：
  // float 最大约 3.4e38，而 exp(89) 就已经溢出成 inf 了。
  // 大模型 logits 上百是家常便饭，一炸就得到 inf/inf = nan，
  // 而 nan 会像病毒一样污染后面所有计算，且不会报错。
  //
  // 解决办法：分子分母同时除以 exp(max)，等价于每个 x 先减去最大值。
  //   exp(xᵢ - max) / Σexp(xⱼ - max)
  // 数学上完全等价，但现在指数最大是 exp(0)=1，永远不会溢出。
  const float max_v = *std::max_element(x.begin(), x.end());

  float sum = 0.0F;
  for (std::size_t i = 0; i < x.size(); ++i) {
    out[i] = std::exp(x[i] - max_v);
    sum += out[i];
  }
  // 乘以倒数比每次做除法快：除法在 CPU 上要十几个周期，乘法只要几个。
  const float inv = 1.0F / sum;
  for (float& v : out) v *= inv;
}

void layernorm_f32(std::span<const float> x, std::span<const float> w,
                   std::span<const float> b, std::span<float> out, float eps) {
  const auto n = static_cast<float>(x.size());

  float mean = 0.0F;
  for (float v : x) mean += v;
  mean /= n;

  // 这里用「先减均值再平方」而不是 E[x²]-E[x]² 的快捷公式。
  // 后者只需遍历一次，但当均值远大于方差时会发生灾难性抵消，精度全丢。
  // 推理引擎里正确性优先于这点速度。
  float var = 0.0F;
  for (float v : x) {
    const float d = v - mean;
    var += d * d;
  }
  var /= n;

  // eps 防止方差为 0 时除零（一整行数字全一样的时候真的会发生）
  const float inv_std = 1.0F / std::sqrt(var + eps);
  for (std::size_t i = 0; i < x.size(); ++i) {
    out[i] = (x[i] - mean) * inv_std * w[i] + b[i];
  }
}

void rmsnorm_f32(std::span<const float> x, std::span<const float> w,
                 std::span<float> out, float eps) {
  // LayerNorm 的简化版：不减均值，只按均方根缩放。
  // 少算一遍均值，效果几乎一样，所以 LLaMA 之后的模型基本都换成了它。
  const auto n = static_cast<float>(x.size());
  float sum_sq = 0.0F;
  for (float v : x) sum_sq += v * v;

  const float scale = 1.0F / std::sqrt(sum_sq / n + eps);
  for (std::size_t i = 0; i < x.size(); ++i) {
    out[i] = x[i] * scale * w[i];
  }
}

// ---------------------------------------------------------------------------
// 矩阵乘法
// ---------------------------------------------------------------------------

void matmul_f32_ijk(std::span<const float> a, std::span<const float> b,
                    std::span<float> c, i64 M, i64 N, i64 K) {
  // 教科书写法，和数学定义一一对应：C[i][j] = Σₖ A[i][k]·B[k][j]
  //
  // 它慢在哪？看最内层的 b[k*N + j]：k 每加 1，内存地址就跳 N 个 float。
  // N=1024 时每次跳 4KB，等于每读一个数就 miss 一次 cache，
  // CPU 绝大部分时间都在等内存，算力完全闲置。
  for (i64 i = 0; i < M; ++i) {
    for (i64 j = 0; j < N; ++j) {
      float sum = 0.0F;
      for (i64 k = 0; k < K; ++k) {
        sum += a[static_cast<std::size_t>(i * K + k)] *
               b[static_cast<std::size_t>(k * N + j)];
      }
      c[static_cast<std::size_t>(i * N + j)] = sum;
    }
  }
}

void matmul_f32_ikj(std::span<const float> a, std::span<const float> b,
                    std::span<float> c, i64 M, i64 N, i64 K) {
  // 只是把 j 和 k 两层循环换了个顺序，数学结果完全一样，但快好几倍。
  //
  // 现在最内层是 j：b[k*N + j] 和 c[i*N + j] 都是「相邻地址连续读写」。
  // 一次 cache line（64 字节）拉进来能用满 16 个 float，
  // 而且这种模式编译器能自动向量化成 AVX 指令。
  //
  // 代价是不能再用局部变量累加 sum，必须先把 C 清零再累加。
  std::ranges::fill(c, 0.0F);
  for (i64 i = 0; i < M; ++i) {
    for (i64 k = 0; k < K; ++k) {
      const float aik = a[static_cast<std::size_t>(i * K + k)];  // 提到循环外，只读一次
      for (i64 j = 0; j < N; ++j) {
        c[static_cast<std::size_t>(i * N + j)] +=
            aik * b[static_cast<std::size_t>(k * N + j)];
      }
    }
  }
}

void matmul_f32(std::span<const float> a, std::span<const float> b,
                std::span<float> c, i64 M, i64 N, i64 K) {
  matmul_f32_ikj(a, b, c, M, N, K);
}

void matmul_nt_f32(std::span<const float> a, std::span<const float> w,
                   std::span<float> c, i64 M, i64 N, i64 K) {
  // C[i][j] = Σₖ A[i][k] · W[j][k]   注意 W 的下标是 [j][k] 不是 [k][j]
  //
  // 这个布局下 a 和 w 都沿着 k 连续读，是两个向量的点积。
  // 既 cache 友好，又能直接用 SIMD 做（阶段 5 会改成 FMA 版本）。
  for (i64 i = 0; i < M; ++i) {
    for (i64 j = 0; j < N; ++j) {
      float sum = 0.0F;
      for (i64 k = 0; k < K; ++k) {
        sum += a[static_cast<std::size_t>(i * K + k)] *
               w[static_cast<std::size_t>(j * K + k)];
      }
      c[static_cast<std::size_t>(i * N + j)] = sum;
    }
  }
}

}  // namespace infer::kernel

#pragma once

#include "infer/tensor.hpp"

namespace infer::ops {

// ---------------------------------------------------------------------------
// Ops 层：认识 Tensor，负责
//   1. 校验形状，形状不对就抛带详细信息的异常
//   2. 把非连续输入自动 contiguous 一下
//   3. 分配输出张量
//   4. 调用 kernel 层干实际的计算
//
// 换句话说，ops 层管「对不对」，kernel 层管「快不快」。
// ---------------------------------------------------------------------------

// --- 逐元素：要求两个输入形状完全一致（广播留作练习）-------------------------
[[nodiscard]] Tensor add(const Tensor& a, const Tensor& b);
[[nodiscard]] Tensor mul(const Tensor& a, const Tensor& b);
[[nodiscard]] Tensor add_scalar(const Tensor& a, float s);
[[nodiscard]] Tensor relu(const Tensor& x);
[[nodiscard]] Tensor gelu(const Tensor& x);

// --- 归约：沿最后一维处理，前面的维度全当成「行」------------------------------
// 例如 x 的形状是 (2, 3, 4)，就当作 6 行、每行 4 个元素来做。
[[nodiscard]] Tensor softmax(const Tensor& x);
[[nodiscard]] Tensor layernorm(const Tensor& x, const Tensor& w, const Tensor& b,
                               float eps = 1e-5F);
[[nodiscard]] Tensor rmsnorm(const Tensor& x, const Tensor& w, float eps = 1e-5F);

// --- 矩阵乘法 -------------------------------------------------------------
// a: (M, K), b: (K, N)  ->  (M, N)
[[nodiscard]] Tensor matmul(const Tensor& a, const Tensor& b);

// 全连接层：y = x @ Wᵀ + bias
//   x:    (M, in)
//   w:    (out, in)   ← 注意是 PyTorch 的 nn.Linear 布局，权重按输出通道存一行
//   bias: (out,)
// 阶段 3 加载 PyTorch 权重时直接就能对上，不用转置。
[[nodiscard]] Tensor linear(const Tensor& x, const Tensor& w);
[[nodiscard]] Tensor linear(const Tensor& x, const Tensor& w, const Tensor& bias);

// --- 杂项 -----------------------------------------------------------------
// 返回最大值所在的下标。分类模型最后一步就靠它把概率变成类别。
[[nodiscard]] i64 argmax(const Tensor& x);

// 逐元素比较，调试和对拍时用
[[nodiscard]] bool allclose(const Tensor& a, const Tensor& b, float atol = 1e-5F);

// 返回两个张量间的最大绝对误差，对拍失败时用来看差多少
[[nodiscard]] float max_abs_diff(const Tensor& a, const Tensor& b);

}  // namespace infer::ops

#include "infer/ops.hpp"

#include <algorithm>
