#pragma once

// 读取 tools/gen_golden.py 生成的标准答案文件。
//
// 这段代码是阶段 3「模型加载器」的预演 —— 模型文件的读法和这里完全一样，
// 只是字段更多一些。二进制格式的读写是推理引擎的基本功。

#include <cstdint>
#include <cstring>
#include <fstream>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>

#include "infer/tensor.hpp"

namespace golden {

class Bundle {
 public:
  explicit Bundle(const std::string& path) {
    // std::ios::binary 不能忘，否则 Windows 下 0x0A 字节会被改写
    std::ifstream f(path, std::ios::binary);
    if (!f) {
      throw std::runtime_error("打不开标准答案文件: " + path +
                               "\n  请先运行: python3 tools/gen_golden.py");
    }

    char magic[4];
    f.read(magic, 4);
    if (std::memcmp(magic, "IGLD", 4) != 0) {
      throw std::runtime_error("文件头不对，这不是一个 golden 文件: " + path);
    }

    const auto count = read<std::uint32_t>(f);
    for (std::uint32_t i = 0; i < count; ++i) {
      const auto name_len = read<std::uint32_t>(f);
      std::string name(name_len, '\0');
      f.read(name.data(), name_len);

      const auto ndim = read<std::uint32_t>(f);
      infer::Shape shape(ndim);
      for (std::uint32_t d = 0; d < ndim; ++d) {
        shape[d] = read<std::int64_t>(f);
      }

      infer::Tensor t = infer::Tensor::zeros(shape);
      auto span = t.data();
      // 一次性读进来，而不是逐个元素读 —— 后者在大模型上会慢几十倍
      f.read(reinterpret_cast<char*>(span.data()),
             static_cast<std::streamsize>(span.size() * sizeof(float)));
      if (!f) {
        throw std::runtime_error("读取张量 '" + name + "' 时文件提前结束");
      }
      tensors_.emplace(std::move(name), std::move(t));
    }
  }

  [[nodiscard]] const infer::Tensor& get(const std::string& name) const {
    auto it = tensors_.find(name);
    if (it == tensors_.end()) {
      throw std::runtime_error("标准答案里没有名为 '" + name + "' 的张量");
    }
    return it->second;
  }

  [[nodiscard]] std::size_t size() const noexcept { return tensors_.size(); }

 private:
  template <class T>
  static T read(std::ifstream& f) {
    T v{};
    f.read(reinterpret_cast<char*>(&v), sizeof(T));
    return v;
  }

  std::unordered_map<std::string, infer::Tensor> tensors_;
};

}  // namespace golden

// 与 Python 参考实现对拍。
//
// 标准答案由 tools/gen_golden.py 生成。如果文件不存在，这些测试会跳过而不是失败，
// 这样刚 clone 下来的人不跑 Python 也能编译通过。

#include <cstdio>
#include <string>

#include "golden.hpp"
#include "infer/ops.hpp"
#include "minitest.hpp"

namespace ops = infer::ops;

namespace {

const std::string kPath = std::string(INFER_TEST_DATA_DIR) + "/golden.bin";

// 加载一次，所有对拍测试共用。返回 nullptr 表示文件不存在。
const golden::Bundle* bundle() {
  static const golden::Bundle* cached = [] () -> const golden::Bundle* {
    try {
      return new golden::Bundle(kPath);
    } catch (const std::exception&) {
      std::printf("  \033[33mSKIP\033[0m  对拍测试（未找到 %s，"
                  "先运行 python3 tools/gen_golden.py）\n", kPath.c_str());
      return nullptr;
    }
  }();
  return cached;
}

// f32 单精度大约有 7 位有效数字，累加 K 次后误差会放大，
// 所以容差要按运算规模来定，不能一律 1e-7。
constexpr float kTolElementwise = 1e-6F;
constexpr float kTolReduction = 1e-5F;
constexpr float kTolMatmul = 1e-4F;

}  // namespace

TEST(golden_matmul) {
  const auto* g = bundle();
  if (!g) return;

  const auto& a = g->get("matmul.a");
  const auto& b = g->get("matmul.b");
  const auto& want = g->get("matmul.out");

  const auto got = ops::matmul(a, b);
  const float diff = ops::max_abs_diff(got, want);
  if (diff > kTolMatmul) {
    throw minitest::Failure("matmul 与参考实现最大误差 " + std::to_string(diff));
  }
}

TEST(golden_softmax_all_ranges) {
  const auto* g = bundle();
  if (!g) return;

  // small: 普通范围   huge: 会让朴素实现溢出成 inf   tiny: 会让朴素实现全部下溢成 0
  for (const char* tag : {"small", "huge", "tiny"}) {
    const auto& x = g->get(std::string("softmax.") + tag + ".x");
    const auto& want = g->get(std::string("softmax.") + tag + ".out");
    const auto got = ops::softmax(x);
    const float diff = ops::max_abs_diff(got, want);
    if (diff > kTolReduction) {
      throw minitest::Failure(std::string("softmax[") + tag +
                              "] 与参考实现最大误差 " + std::to_string(diff));
    }
  }
}

TEST(golden_layernorm) {
  const auto* g = bundle();
  if (!g) return;

  const auto got = ops::layernorm(g->get("layernorm.x"), g->get("layernorm.w"),
                                  g->get("layernorm.b"));
  const float diff = ops::max_abs_diff(got, g->get("layernorm.out"));
  if (diff > kTolReduction) {
    throw minitest::Failure("layernorm 与参考实现最大误差 " + std::to_string(diff));
  }
}

TEST(golden_activations) {
  const auto* g = bundle();
  if (!g) return;

  const auto& x = g->get("act.x");

  const float d_relu = ops::max_abs_diff(ops::relu(x), g->get("relu.out"));
  if (d_relu > kTolElementwise) {
    throw minitest::Failure("relu 与参考实现最大误差 " + std::to_string(d_relu));
  }

  // gelu 里有 tanh 和三次方，f32 下误差会比 relu 大一个量级
  const float d_gelu = ops::max_abs_diff(ops::gelu(x), g->get("gelu.out"));
  if (d_gelu > kTolReduction) {
    throw minitest::Failure("gelu 与参考实现最大误差 " + std::to_string(d_gelu));
  }
}

