#pragma once

#include <cstdint>
#include <string>
#include <unordered_map>
#include <vector>

#include "infer/tensor.hpp"

namespace infer {

// ---------------------------------------------------------------------------
// .infer 模型文件
//
//   ┌───────────────────────────────────────┐
//   │ magic "INFR"          4 字节           │  认文件用，读错文件立刻报错
//   │ version               uint32          │  以后改格式靠它兼容老文件
//   │ num_tensors           uint32          │
//   ├───────────────────────────────────────┤
//   │ 张量 0 元信息:                          │
//   │   name_len uint32 | name | dtype u32  │
//   │   ndim u32 | dims i64[] |             │
//   │   offset u64 | nbytes u64             │  offset 是在「数据区」内的字节偏移
//   │ 张量 1 元信息: ...                      │
//   ├───────────────────────────────────────┤
//   │ data_start            uint64          │
//   ├───────────────────────────────────────┤
//   │ 数据区：所有张量的原始字节紧密排列        │
//   └───────────────────────────────────────┘
//
// 为什么元信息和数据要分开放？
//   1. 加载时可以先只读元信息（几 KB），看看模型长什么样，再决定读哪些张量
//   2. 数据区整段对齐、连续，阶段 7 可以直接 mmap 上去实现零拷贝加载：
//      几百 MB 的模型「瞬间」就绪，多个进程还能共享同一份物理内存
//
// 真实世界的 safetensors、GGUF 格式都是这个思路，只是元信息用了 JSON 或
// 更复杂的 KV 结构。
// ---------------------------------------------------------------------------

struct TensorInfo {
  std::string name;
  Shape shape;
  DType dtype = DType::F32;
  std::uint64_t offset = 0;  // 相对于数据区起点
  std::uint64_t nbytes = 0;
};

class ModelFile {
 public:
  // 一次性把整个文件读进内存。阶段 7 会加一个 mmap 版本做对比。
  static ModelFile load(const std::string& path);

  [[nodiscard]] bool has(const std::string& name) const;

  // 取一个张量。返回的是拷贝（这个阶段先图简单，阶段 7 改成零拷贝视图）。
  // 名字不存在时抛异常，并把文件里所有可用的名字列出来 ——
  // 「权重名字拼错」是加载模型时最高频的错误，报错信息必须帮你定位。
  [[nodiscard]] Tensor get(const std::string& name) const;

  [[nodiscard]] const std::vector<TensorInfo>& tensors() const noexcept { return infos_; }
  [[nodiscard]] std::uint32_t version() const noexcept { return version_; }
  [[nodiscard]] std::string summary() const;

 private:
  std::uint32_t version_ = 0;
  std::vector<TensorInfo> infos_;
  std::unordered_map<std::string, std::size_t> index_;  // 名字 -> infos_ 下标
  std::vector<std::byte> data_;                         // 数据区
};

}  // namespace infer

#include "infer/model_file.hpp"

#include <bit>
#include <cstring>
#include <format>
#include <fstream>
#include <stdexcept>

namespace infer {

namespace {

[[noreturn]] void fail(const std::string& msg) {
  throw std::runtime_error("[infer::ModelFile] " + msg);
}

// 从字节流里按小端序读一个定长整数。
//
// 为什么不直接 memcpy 一个结构体进来？因为那样依赖三件事：
// 主机字节序、结构体内存对齐、编译器 padding —— 任何一个和写文件那边不一致，
// 读出来就是垃圾数据，而且往往在换台机器后才暴露。
// 显式逐字节读虽然啰嗦，但行为完全确定。
template <class T>
T read_le(const std::vector<std::byte>& buf, std::size_t& pos) {
  if (pos + sizeof(T) > buf.size()) {
    fail(std::format("文件在偏移 {} 处提前结束（还想读 {} 字节）", pos, sizeof(T)));
  }
  T v{};
  std::memcpy(&v, buf.data() + pos, sizeof(T));
  pos += sizeof(T);
  if constexpr (std::endian::native == std::endian::big) {
    // x86 和 arm 都是小端，这段几乎不会执行到，但写上才算正确
    auto* p = reinterpret_cast<std::byte*>(&v);
    std::reverse(p, p + sizeof(T));
  }
  return v;
}

std::string read_string(const std::vector<std::byte>& buf, std::size_t& pos, std::size_t n) {
  if (pos + n > buf.size()) fail("读字符串时文件提前结束");
  std::string s(reinterpret_cast<const char*>(buf.data() + pos), n);
  pos += n;
  return s;
}

}  // namespace

ModelFile ModelFile::load(const std::string& path) {
  std::ifstream f(path, std::ios::binary | std::ios::ate);
  if (!f) {
    fail("打不开模型文件: " + path +
         "\n  先运行: .venv/bin/python tools/train_mnist.py");
  }
  const auto size = static_cast<std::size_t>(f.tellg());
  f.seekg(0);

  std::vector<std::byte> buf(size);
  f.read(reinterpret_cast<char*>(buf.data()), static_cast<std::streamsize>(size));
  if (!f) fail("读取文件失败: " + path);

  std::size_t pos = 0;
  if (size < 12 || std::memcmp(buf.data(), "INFR", 4) != 0) {
    fail("文件头不是 INFR，这不是一个 .infer 模型文件: " + path);
  }
  pos = 4;

  ModelFile m;
  m.version_ = read_le<std::uint32_t>(buf, pos);
  if (m.version_ != 1) {
    fail(std::format("不支持的版本 {}（本程序只认版本 1）", m.version_));
  }
  const auto count = read_le<std::uint32_t>(buf, pos);

  m.infos_.reserve(count);
  for (std::uint32_t i = 0; i < count; ++i) {
    TensorInfo info;
    const auto name_len = read_le<std::uint32_t>(buf, pos);
    info.name = read_string(buf, pos, name_len);

    const auto dtype_code = read_le<std::uint32_t>(buf, pos);
    if (dtype_code != 0) {
      fail(std::format("张量 '{}' 的 dtype 编码 {} 暂不支持（目前只有 f32）",
                       info.name, dtype_code));
    }
    info.dtype = DType::F32;

    const auto ndim = read_le<std::uint32_t>(buf, pos);
    info.shape.resize(ndim);
    for (std::uint32_t d = 0; d < ndim; ++d) {
      info.shape[d] = read_le<std::int64_t>(buf, pos);
    }
    info.offset = read_le<std::uint64_t>(buf, pos);
    info.nbytes = read_le<std::uint64_t>(buf, pos);

    // 元信息自洽性检查：声明的字节数必须和 shape 对得上。
    // 模型文件损坏或格式写错时，在这里报错远好过后面读出一堆 nan。
    const auto expect = static_cast<std::uint64_t>(numel_of(info.shape)) *
                        dtype_size(info.dtype);
    if (info.nbytes != expect) {
      fail(std::format("张量 '{}' 元信息不一致：声明 {} 字节，但形状需要 {} 字节",
                       info.name, info.nbytes, expect));
    }

    m.index_.emplace(info.name, m.infos_.size());
    m.infos_.push_back(std::move(info));
  }

  const auto data_start = read_le<std::uint64_t>(buf, pos);
  if (data_start > size) {
    fail(std::format("data_start={} 超出文件大小 {}", data_start, size));
  }
  m.data_.assign(buf.begin() + static_cast<std::ptrdiff_t>(data_start), buf.end());

  // 再检查一遍每个张量的数据都在数据区范围内
  for (const auto& info : m.infos_) {
    if (info.offset + info.nbytes > m.data_.size()) {
      fail(std::format("张量 '{}' 的数据超出文件末尾", info.name));
    }
  }
  return m;
}

bool ModelFile::has(const std::string& name) const {
  return index_.contains(name);  // C++20 的 contains，比 find() != end() 清爽
}

Tensor ModelFile::get(const std::string& name) const {
  auto it = index_.find(name);
  if (it == index_.end()) {
    std::string available;
    for (const auto& info : infos_) available += "\n    " + info.name;
    fail("模型里没有名为 '" + name + "' 的张量。文件里有这些：" + available);
  }
  const TensorInfo& info = infos_[it->second];

  Tensor t = Tensor::zeros(info.shape, info.dtype);
  std::memcpy(t.data().data(), data_.data() + info.offset, info.nbytes);
  return t;
}

std::string ModelFile::summary() const {
  std::string s = std::format("ModelFile(version={}, {} 个张量)\n", version_, infos_.size());
  std::uint64_t total = 0;
  for (const auto& info : infos_) {
    s += std::format("  {:<14} shape=(", info.name);
    for (std::size_t i = 0; i < info.shape.size(); ++i) {
      s += std::format("{}{}", info.shape[i], i + 1 < info.shape.size() ? ", " : "");
    }
    s += std::format(")  {:>8.1f} KB\n", static_cast<double>(info.nbytes) / 1024.0);
    total += info.nbytes;
  }
  s += std::format("  合计 {:.1f} KB\n", static_cast<double>(total) / 1024.0);
  return s;
}

}  // namespace infer

