#pragma once

#include <string>

#include "infer/model_file.hpp"
#include "infer/tensor.hpp"

namespace infer {

// ---------------------------------------------------------------------------
// 一个两层 MLP，用来认手写数字。
//
//   输入 [B, 784]
//        │
//   Linear(784 → 128)   w1: [128, 784]   b1: [128]
//        │
//       ReLU
//        │
//   Linear(128 → 10)    w2: [10, 128]    b2: [10]
//        │
//   logits [B, 10]  ──Softmax──→ 概率  ──argmax──→ 预测的数字
//
// 这是本项目第一个「真正的模型」。它的结构是硬编码的 ——
// 阶段 4 才会把它重构成通用的计算图。现在这样反而清晰：
// 你能一眼看出推理的全部步骤就是四次函数调用。
// ---------------------------------------------------------------------------
class MLP {
 public:
  static MLP from_file(const std::string& path);

  // 前向传播，返回 logits [B, 10]（还没过 softmax）。
  //
  // 为什么不直接返回概率？因为 argmax(logits) == argmax(softmax(logits))
  // —— softmax 是单调递增的，不改变大小顺序。只要分类，就没必要算那个 exp。
  // 需要概率值时再单独调 softmax。
  [[nodiscard]] Tensor forward(const Tensor& x) const;

  // 带中间结果的版本，用来和 Python 逐层对齐。
  //
  // 模型输出不对时，逐层比对能立刻告诉你是哪一层写错了。
  // 没有这个工具，你只能对着一堆数字干瞪眼 —— 这是阶段 3 最值钱的调试手段。
  struct Trace {
    Tensor z1;    // Linear1 的输出
    Tensor h;     // ReLU 之后
    Tensor z2;    // Linear2 的输出（logits）
    Tensor prob;  // Softmax 之后
  };
  [[nodiscard]] Trace forward_trace(const Tensor& x) const;

  // 单张图片 [784] 或 [1,784] -> 预测的数字 0~9
  [[nodiscard]] i64 predict(const Tensor& image) const;

  [[nodiscard]] const Tensor& w1() const noexcept { return w1_; }
  [[nodiscard]] const Tensor& w2() const noexcept { return w2_; }

 private:
  Tensor w1_, b1_, w2_, b2_;
};

}  // namespace infer

#include "infer/mlp.hpp"

#include <format>
#include <stdexcept>

#include "infer/ops.hpp"

namespace infer {

MLP MLP::from_file(const std::string& path) {
  const ModelFile f = ModelFile::load(path);

  MLP m;
  // 名字要和 tools/train_mnist.py 里导出时用的一致。
  // 这套命名沿用 PyTorch 的 state_dict 惯例（层名.参数名）。
  m.w1_ = f.get("fc1.weight");
  m.b1_ = f.get("fc1.bias");
  m.w2_ = f.get("fc2.weight");
  m.b2_ = f.get("fc2.bias");

  // 结构校验：与其在推理时得到一堆 nan，不如在加载时就报错。
  // 真实引擎加载模型时都会做这类检查。
  if (m.w1_.ndim() != 2 || m.w2_.ndim() != 2) {
    throw std::runtime_error("[MLP] 权重必须是二维的");
  }
  if (m.w1_.dim(0) != m.w2_.dim(1)) {
    throw std::runtime_error(
        std::format("[MLP] 两层接不上：fc1 输出 {} 维，fc2 期望输入 {} 维",
                    m.w1_.dim(0), m.w2_.dim(1)));
  }
  return m;
}

Tensor MLP::forward(const Tensor& x) const {
  // 整个「推理」就是这三行。
  // 对比一下 tools/train_mnist.py 里的反向传播那一大坨 —— 推理引擎不需要它们。
  Tensor h = ops::linear(x, w1_, b1_);  // [B,784] × [128,784]ᵀ + b -> [B,128]
  h = ops::relu(h);
  return ops::linear(h, w2_, b2_);      // [B,128] × [10,128]ᵀ + b -> [B,10]
}

MLP::Trace MLP::forward_trace(const Tensor& x) const {
  Trace t;
  t.z1 = ops::linear(x, w1_, b1_);
  t.h = ops::relu(t.z1);
  t.z2 = ops::linear(t.h, w2_, b2_);
  t.prob = ops::softmax(t.z2);
  return t;
}

i64 MLP::predict(const Tensor& image) const {
  // 接受 [784] 或 [1,784] 两种形状，调用方不用操心
  const Tensor x = image.ndim() == 1 ? image.reshape({1, image.numel()}) : image;
  if (x.dim(0) != 1) {
    throw std::runtime_error(
        std::format("[MLP] predict 一次只处理一张图，但拿到 {} 张", x.dim(0)));
  }
  return ops::argmax(forward(x));
}

}  // namespace infer

// 第 3 阶段：第一个端到端可运行的模型。
//
// 加载 Python 训练好的权重，在 C++ 里跑前向，认出手写数字。
//
//   .venv/bin/python tools/train_mnist.py   # 先训练并导出权重
//   ./build/examples/03_mnist

#include <chrono>
#include <cmath>
#include <format>
#include <iostream>
#include <string>
#include <vector>

#include "infer/mlp.hpp"
#include "infer/model_file.hpp"
#include "infer/ops.hpp"
#include "infer/tensor.hpp"

using infer::Tensor;
namespace ops = infer::ops;

template <class... Args>
void println(std::format_string<Args...> fmt, Args&&... args) {
  std::cout << std::format(fmt, std::forward<Args>(args)...) << '\n';
}

void section(const char* title) {
  std::cout << std::format("\n\033[36m===== {} =====\033[0m\n", title);
}

// 把 28×28 的灰度图用字符画出来，这样预测结果可以肉眼验证
void draw(const Tensor& image) {
  static const char* kRamp = " .:-=+*#%@";  // 由浅到深
  auto px = image.data();
  for (int r = 0; r < 28; ++r) {
    std::string line = "    ";
    for (int c = 0; c < 28; ++c) {
      const float v = px[static_cast<std::size_t>(r * 28 + c)];
      const int level = static_cast<int>(v * 9.99F);
      line += kRamp[level < 0 ? 0 : (level > 9 ? 9 : level)];
      line += kRamp[level < 0 ? 0 : (level > 9 ? 9 : level)];  // 横向拉宽，字符才不会太扁
    }
    std::cout << line << '\n';
  }
}

// 概率分布画成横向条形图
void draw_probs(const Tensor& prob, infer::i64 truth) {
  auto p = prob.data();
  for (int d = 0; d < 10; ++d) {
    const float v = p[static_cast<std::size_t>(d)];
    const int bars = static_cast<int>(v * 40.0F + 0.5F);
    const bool is_truth = (d == truth);
    std::cout << std::format("    {}{} │{}{:<40}\033[0m {:6.2f}%{}\n",
                             is_truth ? "\033[32m" : "", d,
                             v > 0.01F ? "\033[1m" : "", std::string(bars, '#'),
                             v * 100.0F, is_truth ? "  \033[32m← 正确答案\033[0m" : "");
  }
}

int main() {
  const std::string model_dir = std::string(INFER_MODEL_DIR) + "/";

  // -------------------------------------------------------------------------
  section("1. 加载模型");
  infer::ModelFile mf = infer::ModelFile::load(model_dir + "mnist_mlp.infer");
  std::cout << mf.summary();

  infer::MLP model = infer::MLP::from_file(model_dir + "mnist_mlp.infer");
  println("结构: 784 → Linear → {} → ReLU → Linear → {}",
          model.w1().dim(0), model.w2().dim(0));

  // -------------------------------------------------------------------------
  section("2. 逐层对齐 Python：确认 C++ 每一层都算对了");
  println("这是阶段 3 最重要的调试手段。输出不对时，逐层比对能直接定位到哪层写错。");
  println("");

  const infer::ModelFile act = infer::ModelFile::load(model_dir + "mnist_activations.infer");
  const Tensor x0 = act.get("input");
  const auto trace = model.forward_trace(x0);

  struct Layer {
    const char* name;
    const Tensor* got;
    const char* key;
  };
  const Layer layers[] = {
      {"Linear1 输出 (z1)", &trace.z1, "z1"},
      {"ReLU 输出   (h) ", &trace.h, "h"},
      {"Linear2 输出 (z2)", &trace.z2, "z2"},
      {"Softmax     (p) ", &trace.prob, "prob"},
  };
  bool all_ok = true;
  for (const auto& L : layers) {
    const Tensor want = act.get(L.key);
    const float diff = ops::max_abs_diff(*L.got, want);
    const bool ok = diff < 1e-4F;
    all_ok = all_ok && ok;
    println("    {}   最大误差 {:.3e}   {}", L.name, static_cast<double>(diff),
            ok ? "\033[32m对齐\033[0m" : "\033[31m不一致！\033[0m");
  }
  println("");
  println("{}", all_ok ? "    \033[32m每一层都和 Python 对上了，实现是正确的。\033[0m"
                       : "    \033[31m有层对不上，去查那一层的实现。\033[0m");

  // -------------------------------------------------------------------------
  section("3. 认几张图片");
  const infer::ModelFile samples = infer::ModelFile::load(model_dir + "mnist_samples.infer");
  const Tensor images = samples.get("images");
  const Tensor labels = samples.get("labels");
  const infer::i64 n = images.dim(0);

  for (infer::i64 i = 0; i < 3; ++i) {
    const Tensor img = images.slice(0, i, i + 1).contiguous();
    const auto t = model.forward_trace(img);
    const infer::i64 pred = ops::argmax(t.prob);
    const auto truth = static_cast<infer::i64>(labels.data()[static_cast<std::size_t>(i)]);

    println("");
    draw(img);
    println("");
    draw_probs(t.prob, truth);
    println("    模型认为这是 \033[1m{}\033[0m，{}", pred,
            pred == truth ? "\033[32m答对了\033[0m" : "\033[31m答错了\033[0m");
  }

  // -------------------------------------------------------------------------
  section("4. 在 200 张测试图片上跑准确率");
  infer::i64 correct = 0;
  const auto t0 = std::chrono::steady_clock::now();
  for (infer::i64 i = 0; i < n; ++i) {
    const Tensor img = images.slice(0, i, i + 1).contiguous();
    if (model.predict(img) ==
        static_cast<infer::i64>(labels.data()[static_cast<std::size_t>(i)])) {
      ++correct;
    }
  }
  const auto t1 = std::chrono::steady_clock::now();
  const double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();

  println("    准确率  {}/{} = \033[1m{:.1f}%\033[0m", correct, n,
          100.0 * static_cast<double>(correct) / static_cast<double>(n));
  println("    用时    {:.2f} ms，平均每张 {:.1f} 微秒", ms, ms * 1000.0 / static_cast<double>(n));
  println("    （Python 训练时报告的测试集准确率是 97.03%，这 200 张是它的子集）");

  // -------------------------------------------------------------------------
  section("5. 逐张推理 vs 批量推理");
  println("上面是一张一张地推理。如果一次喂 {} 张呢？", n);

  const auto t2 = std::chrono::steady_clock::now();
  const Tensor batch_logits = model.forward(images);
  const auto t3 = std::chrono::steady_clock::now();
  const double batch_ms = std::chrono::duration<double, std::milli>(t3 - t2).count();

  println("    逐张 {} 次: {:8.2f} ms", n, ms);
  println("    批量  1 次: {:8.2f} ms   \033[33m快 {:.1f}×\033[0m", batch_ms, ms / batch_ms);
  println("");
  println("    为什么批量更快？权重只需要从内存加载一次，就能服务所有样本。");
  println("    矩阵乘法从「向量×矩阵」变成「矩阵×矩阵」，计算密度高得多。");
  println("    这就是推理服务里 batching 的意义 —— 阶段 6 的 LLM 推理也靠它提吞吐。");

  // 顺带验证批量和逐张结果一致
  infer::i64 batch_correct = 0;
  for (infer::i64 i = 0; i < n; ++i) {
    const Tensor row = batch_logits.slice(0, i, i + 1).contiguous();
    if (ops::argmax(row) ==
        static_cast<infer::i64>(labels.data()[static_cast<std::size_t>(i)])) {
      ++batch_correct;
    }
  }
  println("    批量推理准确率 {}/{}，与逐张{}", batch_correct, n,
          batch_correct == correct ? "一致 \033[32m✓\033[0m" : " \033[31m不一致！\033[0m");

  std::cout << '\n';
  return 0;
}

