// 阶段 3 的端到端测试。
// 模型文件不存在时跳过，这样没跑过训练脚本的人也能编译通过。

#include <cstdio>
#include <string>

#include "infer/mlp.hpp"
#include "infer/model_file.hpp"
#include "infer/ops.hpp"
#include "minitest.hpp"

using infer::Tensor;
namespace ops = infer::ops;

namespace {

const std::string kDir = std::string(INFER_MODEL_DIR) + "/";

bool models_ready() {
  static const bool ready = [] {
    try {
      (void)infer::ModelFile::load(kDir + "mnist_mlp.infer");
      return true;
    } catch (const std::exception&) {
      std::printf("  \033[33mSKIP\033[0m  MNIST 测试（未找到模型，"
                  "先运行 .venv/bin/python tools/train_mnist.py）\n");
      return false;
    }
  }();
  return ready;
}

}  // namespace

TEST(model_file_metadata) {
  if (!models_ready()) return;
  const auto mf = infer::ModelFile::load(kDir + "mnist_mlp.infer");

  CHECK(mf.version() == 1);
  CHECK(mf.tensors().size() == 4);
  CHECK(mf.has("fc1.weight"));
  CHECK(mf.has("fc2.bias"));
  CHECK(!mf.has("fc3.weight"));

  // 权重是 PyTorch 的 (out, in) 布局
  CHECK((mf.get("fc1.weight").shape() == infer::Shape{128, 784}));
  CHECK((mf.get("fc1.bias").shape() == infer::Shape{128}));
  CHECK((mf.get("fc2.weight").shape() == infer::Shape{10, 128}));
}

TEST(model_file_missing_tensor_throws) {
  if (!models_ready()) return;
  const auto mf = infer::ModelFile::load(kDir + "mnist_mlp.infer");
  CHECK_THROWS(mf.get("does.not.exist"));
}

TEST(model_file_bad_path_throws) {
  CHECK_THROWS(infer::ModelFile::load(kDir + "no_such_file.infer"));
}

TEST(mlp_matches_python_layer_by_layer) {
  if (!models_ready()) return;

  const auto model = infer::MLP::from_file(kDir + "mnist_mlp.infer");
  const auto act = infer::ModelFile::load(kDir + "mnist_activations.infer");
  const auto trace = model.forward_trace(act.get("input"));

  // f32 下逐层累积误差应保持在 1e-4 以内。
  // 如果某一层突然跳到 1e-1 量级，那一层的实现就有问题。
  CHECK(ops::max_abs_diff(trace.z1, act.get("z1")) < 1e-4F);
  CHECK(ops::max_abs_diff(trace.h, act.get("h")) < 1e-4F);
  CHECK(ops::max_abs_diff(trace.z2, act.get("z2")) < 1e-4F);
  CHECK(ops::max_abs_diff(trace.prob, act.get("prob")) < 1e-5F);
}

TEST(mlp_accuracy_on_test_samples) {
  if (!models_ready()) return;

  const auto model = infer::MLP::from_file(kDir + "mnist_mlp.infer");
  const auto samples = infer::ModelFile::load(kDir + "mnist_samples.infer");
  const Tensor images = samples.get("images");
  const Tensor labels = samples.get("labels");

  infer::i64 correct = 0;
  for (infer::i64 i = 0; i < images.dim(0); ++i) {
    const Tensor img = images.slice(0, i, i + 1).contiguous();
    if (model.predict(img) ==
        static_cast<infer::i64>(labels.data()[static_cast<std::size_t>(i)])) {
      ++correct;
    }
  }
  const double acc = static_cast<double>(correct) / static_cast<double>(images.dim(0));
  if (acc < 0.95) {
    throw minitest::Failure("准确率只有 " + std::to_string(acc * 100) + "%，低于 95%");
  }
}

TEST(mlp_batch_equals_one_by_one) {
  if (!models_ready()) return;

  // 批量推理和逐张推理必须给出完全相同的预测。
  // 这条测试能抓住「batch 维度处理错了」这类 bug ——
  // 它们在 batch=1 时完全看不出来，上了 batch 才暴露。
  const auto model = infer::MLP::from_file(kDir + "mnist_mlp.infer");
  const auto samples = infer::ModelFile::load(kDir + "mnist_samples.infer");
  const Tensor images = samples.get("images");

  const Tensor batch = model.forward(images);
  for (infer::i64 i = 0; i < images.dim(0); ++i) {
    const Tensor img = images.slice(0, i, i + 1).contiguous();
    const Tensor one = model.forward(img);
    const Tensor row = batch.slice(0, i, i + 1).contiguous();
    CHECK(ops::max_abs_diff(one, row) < 1e-5F);
  }
}

TEST(mlp_rejects_wrong_input_shape) {
  if (!models_ready()) return;
  const auto model = infer::MLP::from_file(kDir + "mnist_mlp.infer");
  CHECK_THROWS(model.forward(Tensor::zeros({1, 100})));   // 特征数不对
  CHECK_THROWS(model.predict(Tensor::zeros({5, 784})));   // predict 一次只收一张
}

#pragma once

#include <memory>
#include <span>
#include <string>
#include <unordered_map>
#include <variant>
#include <vector>

#include "infer/tensor.hpp"

namespace infer {

// ---------------------------------------------------------------------------
// 属性：算子的「配置参数」，和输入张量不同，它在建图时就定死了。
//
// 例如 layernorm 的 eps、softmax 的 axis、conv 的 stride。
// 类型不固定，所以用 std::variant 装 —— 这是 C++17 起的类型安全联合体，
// 比 void* 或者「每种类型存一个 map」都干净。
// ---------------------------------------------------------------------------
using Attribute = std::variant<std::int64_t, float, std::string>;

class Attributes {
 public:
  Attributes& set(std::string key, Attribute v) {
    kv_.insert_or_assign(std::move(key), std::move(v));
    return *this;  // 返回自身，支持链式调用 .set("a",1).set("b",2)
  }

  [[nodiscard]] bool has(const std::string& key) const { return kv_.contains(key); }

  // 取属性，类型不对或不存在时抛异常并说明原因。
  // 建图阶段的错误必须在这里就报出来，不能等到推理时。
  template <class T>
  [[nodiscard]] T get(const std::string& key) const;

  template <class T>
  [[nodiscard]] T get_or(const std::string& key, T fallback) const {
    return has(key) ? get<T>(key) : fallback;
  }

  [[nodiscard]] std::string to_string() const;

 private:
  std::unordered_map<std::string, Attribute> kv_;
};

// ---------------------------------------------------------------------------
// 算子接口
//
// 这里用的是「运行期多态」（虚函数）。为什么不用 CRTP / concepts 做编译期多态？
//
//   编译期多态                          运行期多态（我们的选择）
//   ──────────                          ──────────────────────
//   零虚函数开销，可内联                  每次调用多一次间接跳转
//   类型在编译期定死                      算子类型从模型文件里读，运行期才知道
//   加算子要改模板实例化                   加算子只要注册一下
//   编译慢，报错信息长                     编译快
//
// 关键在于：**模型结构是运行期数据**。你不可能为每种模型结构写一份模板实例化。
// 而虚函数那点开销（几纳秒）相对于算子内部动辄几百万次浮点运算，完全可以忽略。
//
// 所以 PyTorch、ONNX Runtime、TensorRT 全都在这一层用运行期多态，
// 把编译期优化的力气花在 kernel 内部。
// ---------------------------------------------------------------------------
struct OpContext {
  std::vector<const Tensor*> inputs;
  const Attributes* attrs = nullptr;
};

class Op {
 public:
  virtual ~Op() = default;

  [[nodiscard]] virtual std::string type() const = 0;

  // 输入个数约束，建图时校验用。返回 -1 表示不限
  [[nodiscard]] virtual int num_inputs() const = 0;

  // 只根据输入形状推出输出形状，不做任何实际计算。
  //
  // 这是真实引擎里很重要的一环：建图后先跑一遍形状推断，
  // 就能在「一次计算都还没做」的时候知道每个中间结果多大，
  // 从而提前规划好内存、发现形状错误。阶段 7 的内存池全靠它。
  [[nodiscard]] virtual Shape infer_shape(std::span<const Shape> inputs,
                                          const Attributes& attrs) const = 0;

  [[nodiscard]] virtual Tensor compute(const OpContext& ctx) const = 0;
};

// ---------------------------------------------------------------------------
// 算子注册表
//
// 用法：REGISTER_OP(ReluOp) 就能让 "relu" 这个名字可用，
// 不需要在任何地方维护一张「所有算子」的列表。
//
// 原理和 tests/minitest.hpp 的测试注册完全一样：
// 定义一个全局对象，利用它的构造函数在 main() 之前完成注册。
// ---------------------------------------------------------------------------
class OpRegistry {
 public:
  static OpRegistry& instance();

  void add(std::unique_ptr<Op> op);

  // 找不到时抛异常，并列出所有已注册的算子名 ——
  // 「算子名拼错」和「模型用了引擎不支持的算子」是同一个报错点。
  [[nodiscard]] const Op& get(const std::string& type) const;
  [[nodiscard]] bool has(const std::string& type) const;
  [[nodiscard]] std::vector<std::string> list() const;

 private:
  std::unordered_map<std::string, std::unique_ptr<Op>> ops_;
};

namespace detail {
struct OpRegistrar {
  explicit OpRegistrar(std::unique_ptr<Op> op) {
    OpRegistry::instance().add(std::move(op));
  }
};
}  // namespace detail

#define REGISTER_OP(cls)                                    \
  namespace {                                               \
  const ::infer::detail::OpRegistrar registrar_##cls{       \
      std::make_unique<cls>()};                             \
  }

// 把内置算子链接进来。
//
// 为什么需要这个函数？因为静态库（.a）在链接时会丢掉「没有任何符号被引用」的
// 目标文件，连带丢掉里面的全局注册对象 —— 算子就凭空消失了。
// 这是 C++ 静态注册惯用法的经典陷阱，叫「静态初始化被优化掉」。
// 在 main 里调一次这个函数，就能强制链接器保留那个目标文件。
void register_builtin_ops();

}  // namespace infer

#include "infer/op.hpp"

#include <format>
#include <stdexcept>

namespace infer {

namespace {
[[noreturn]] void fail(const std::string& msg) {
  throw std::invalid_argument("[infer::op] " + msg);
}

std::string type_name_of(const Attribute& a) {
  // C++20 没有 std::visit 的简写，还是得写个 overload 集合
  return std::visit([](auto&& v) -> std::string {
    using T = std::decay_t<decltype(v)>;
    if constexpr (std::is_same_v<T, std::int64_t>) return "int";
    else if constexpr (std::is_same_v<T, float>) return "float";
    else return "string";
  }, a);
}
}  // namespace

template <class T>
T Attributes::get(const std::string& key) const {
  auto it = kv_.find(key);
  if (it == kv_.end()) {
    std::string keys;
    for (const auto& [k, v] : kv_) keys += " " + k;
    fail(std::format("没有属性 '{}'，现有属性:{}", key, keys.empty() ? " (无)" : keys));
  }
  if (!std::holds_alternative<T>(it->second)) {
    fail(std::format("属性 '{}' 的类型是 {}，取的时候用错了类型",
                     key, type_name_of(it->second)));
  }
  return std::get<T>(it->second);
}

// 显式实例化：只允许这三种类型，别的类型在链接期就会报错
template std::int64_t Attributes::get<std::int64_t>(const std::string&) const;
template float Attributes::get<float>(const std::string&) const;
template std::string Attributes::get<std::string>(const std::string&) const;

std::string Attributes::to_string() const {
  if (kv_.empty()) return "";
  std::string s = "{";
  bool first = true;
  for (const auto& [k, v] : kv_) {
    if (!first) s += ", ";
    first = false;
    s += k + "=";
    std::visit([&s](auto&& x) {
      using T = std::decay_t<decltype(x)>;
      if constexpr (std::is_same_v<T, std::string>) s += x;
      else s += std::format("{}", x);
    }, v);
  }
  return s + "}";
}

OpRegistry& OpRegistry::instance() {
  // 函数内 static：保证第一次用到时才构造，避开「静态初始化顺序不确定」的坑。
  // 如果写成全局变量，某个算子的注册对象可能在 registry 构造之前就跑了。
  static OpRegistry reg;
  return reg;
}

void OpRegistry::add(std::unique_ptr<Op> op) {
  const std::string type = op->type();
  if (ops_.contains(type)) {
    fail("算子 '" + type + "' 被重复注册了");
  }
  ops_.emplace(type, std::move(op));
}

bool OpRegistry::has(const std::string& type) const { return ops_.contains(type); }

const Op& OpRegistry::get(const std::string& type) const {
  auto it = ops_.find(type);
  if (it == ops_.end()) {
    std::string names;
    for (const auto& [k, v] : ops_) names += "\n    " + k;
    fail("不认识的算子 '" + type + "'。已注册的算子有：" +
         (names.empty() ? "\n    (一个都没有，是不是忘了调 register_builtin_ops()？)"
                        : names));
  }
  return *it->second;
}

std::vector<std::string> OpRegistry::list() const {
  std::vector<std::string> names;
  names.reserve(ops_.size());
  for (const auto& [k, v] : ops_) names.push_back(k);
  return names;
}

}  // namespace infer

// 把阶段 2 写的算子包装成可注册的 Op。
//
// 注意这里没有一行真正的计算 —— 全部转交给 ops:: 层。
// 这说明抽象加得很干净：计算逻辑和图执行框架是解耦的。

#include <format>
#include <stdexcept>

#include "infer/op.hpp"
#include "infer/ops.hpp"

namespace infer {

namespace {

[[noreturn]] void fail(const std::string& msg) {
  throw std::invalid_argument("[infer::builtin_ops] " + msg);
}

std::string shape_str(const Shape& s) {
  std::string out = "(";
  for (std::size_t i = 0; i < s.size(); ++i) {
    out += std::format("{}{}", s[i], i + 1 < s.size() ? ", " : "");
  }
  return out + ")";
}

// 逐元素算子的形状推断都一样：输出形状 = 输入形状。
// 用个基类省掉重复代码。
class UnaryElementwiseOp : public Op {
 public:
  [[nodiscard]] int num_inputs() const override { return 1; }
  [[nodiscard]] Shape infer_shape(std::span<const Shape> in,
                                  const Attributes&) const override {
    return Shape(in[0]);
  }
};

class ReluOp final : public UnaryElementwiseOp {
 public:
  [[nodiscard]] std::string type() const override { return "relu"; }
  [[nodiscard]] Tensor compute(const OpContext& ctx) const override {
    return ops::relu(*ctx.inputs[0]);
  }
};

class GeluOp final : public UnaryElementwiseOp {
 public:
  [[nodiscard]] std::string type() const override { return "gelu"; }
  [[nodiscard]] Tensor compute(const OpContext& ctx) const override {
    return ops::gelu(*ctx.inputs[0]);
  }
};

class SoftmaxOp final : public UnaryElementwiseOp {
 public:
  [[nodiscard]] std::string type() const override { return "softmax"; }
  [[nodiscard]] Tensor compute(const OpContext& ctx) const override {
    return ops::softmax(*ctx.inputs[0]);
  }
};

class AddOp final : public Op {
 public:
  [[nodiscard]] std::string type() const override { return "add"; }
  [[nodiscard]] int num_inputs() const override { return 2; }
  [[nodiscard]] Shape infer_shape(std::span<const Shape> in,
                                  const Attributes&) const override {
    if (in[0] != in[1]) {
      fail(std::format("add: 形状必须一致，但拿到 {} 和 {}",
                       shape_str(in[0]), shape_str(in[1])));
    }
    return Shape(in[0]);
  }
  [[nodiscard]] Tensor compute(const OpContext& ctx) const override {
    return ops::add(*ctx.inputs[0], *ctx.inputs[1]);
  }
};

class MulOp final : public Op {
 public:
  [[nodiscard]] std::string type() const override { return "mul"; }
  [[nodiscard]] int num_inputs() const override { return 2; }
  [[nodiscard]] Shape infer_shape(std::span<const Shape> in,
                                  const Attributes&) const override {
    if (in[0] != in[1]) {
      fail(std::format("mul: 形状必须一致，但拿到 {} 和 {}",
                       shape_str(in[0]), shape_str(in[1])));
    }
    return Shape(in[0]);
  }
  [[nodiscard]] Tensor compute(const OpContext& ctx) const override {
    return ops::mul(*ctx.inputs[0], *ctx.inputs[1]);
  }
};

class MatmulOp final : public Op {
 public:
  [[nodiscard]] std::string type() const override { return "matmul"; }
  [[nodiscard]] int num_inputs() const override { return 2; }
  [[nodiscard]] Shape infer_shape(std::span<const Shape> in,
                                  const Attributes&) const override {
    if (in[0].size() != 2 || in[1].size() != 2) {
      fail("matmul: 目前只支持二维");
    }
    if (in[0][1] != in[1][0]) {
      fail(std::format("matmul: 形状对不上，{} × {}",
                       shape_str(in[0]), shape_str(in[1])));
    }
    return Shape{in[0][0], in[1][1]};
  }
  [[nodiscard]] Tensor compute(const OpContext& ctx) const override {
    return ops::matmul(*ctx.inputs[0], *ctx.inputs[1]);
  }
};

// linear 有两种用法：带 bias（3 个输入）和不带（2 个输入）。
// num_inputs() 返回 -1 表示个数不固定，由算子自己检查。
class LinearOp final : public Op {
 public:
  [[nodiscard]] std::string type() const override { return "linear"; }
  [[nodiscard]] int num_inputs() const override { return -1; }
  [[nodiscard]] Shape infer_shape(std::span<const Shape> in,
                                  const Attributes&) const override {
    if (in.size() != 2 && in.size() != 3) {
      fail(std::format("linear: 需要 2 或 3 个输入（x, w[, bias]），拿到 {} 个",
                       in.size()));
    }
    const Shape& x = in[0];
    const Shape& w = in[1];
    if (x.size() != 2 || w.size() != 2) fail("linear: x 和 w 都必须是二维");
    if (x[1] != w[1]) {
      fail(std::format("linear: x 的特征数是 {}，但权重 {} 期望 {}",
                       x[1], shape_str(w), w[1]));
    }
    if (in.size() == 3 && (in[2].size() != 1 || in[2][0] != w[0])) {
      fail(std::format("linear: bias 形状应为 ({},)，拿到 {}", w[0], shape_str(in[2])));
    }
    return Shape{x[0], w[0]};
  }
  [[nodiscard]] Tensor compute(const OpContext& ctx) const override {
    if (ctx.inputs.size() == 3) {
      return ops::linear(*ctx.inputs[0], *ctx.inputs[1], *ctx.inputs[2]);
    }
    return ops::linear(*ctx.inputs[0], *ctx.inputs[1]);
  }
};

class LayerNormOp final : public Op {
 public:
  [[nodiscard]] std::string type() const override { return "layernorm"; }
  [[nodiscard]] int num_inputs() const override { return 3; }
  [[nodiscard]] Shape infer_shape(std::span<const Shape> in,
                                  const Attributes&) const override {
    if (in[0].empty()) fail("layernorm: 输入不能是标量");
    const auto d = in[0].back();
    if (in[1] != Shape{d} || in[2] != Shape{d}) {
      fail(std::format("layernorm: w/b 形状应为 ({},)", d));
    }
    return Shape(in[0]);
  }
  [[nodiscard]] Tensor compute(const OpContext& ctx) const override {
    // eps 是属性而不是输入 —— 它是配置，不是数据。
    // 这个区分在设计算子接口时很重要。
    const float eps = ctx.attrs ? ctx.attrs->get_or<float>("eps", 1e-5F) : 1e-5F;
    return ops::layernorm(*ctx.inputs[0], *ctx.inputs[1], *ctx.inputs[2], eps);
  }
};

REGISTER_OP(ReluOp)
REGISTER_OP(GeluOp)
REGISTER_OP(SoftmaxOp)
REGISTER_OP(AddOp)
REGISTER_OP(MulOp)
REGISTER_OP(MatmulOp)
REGISTER_OP(LinearOp)
REGISTER_OP(LayerNormOp)

