namespace infer {

// ---------------------------------------------------------------------------
// 计算图
//
// 阶段 3 的 MLP 是这样写的：
//     x = linear(x, w1, b1);  x = relu(x);  x = linear(x, w2, b2);
// 模型结构写死在代码里，换个模型就得重写、重新编译。
//
// 计算图把结构变成**数据**：
//     图 = 一组 Value（数据）+ 一组 Node（运算），Node 靠 Value 的 id 连起来
//
//     ┌──────┐  ┌──────┐        ┌──────┐
//     │input │  │  w1  │        │  b1  │        Value：图里流动的张量
//     └───┬──┘  └───┬──┘        └───┬──┘
//         └─────────┼───────────────┘
//                   ▼
//              ┌─────────┐
//              │ linear  │                      Node：一次运算
//              └────┬────┘
//                   ▼ v3
//              ┌─────────┐
//              │  relu   │
//              └────┬────┘
//                   ▼ v4  ...
//
// 好处：结构可以从文件读、可以打印、可以分析、可以变换（融合/重排）、可以复用内存。
// 这是「一段代码」和「一个引擎」的分界线。
// ---------------------------------------------------------------------------

using ValueId = int;

struct Value {
  ValueId id = -1;
  std::string name;
  Shape shape;  // 由形状推断填充

  enum class Kind {
    Input,         // 运行时喂进来的数据
    Weight,        // 从模型文件加载的常量
    Intermediate,  // 某个节点算出来的中间结果
  };
  Kind kind = Kind::Intermediate;
};

struct Node {
  int id = -1;
  std::string op_type;  // 到 OpRegistry 里查
  std::string name;     // 给人看的，调试用
  std::vector<ValueId> inputs;
  ValueId output = -1;
  Attributes attrs;
};

class Graph {
 public:
  // --- 建图 ---------------------------------------------------------------
  ValueId add_input(std::string name, Shape shape);
  ValueId add_weight(std::string name, Tensor value);

  // 加一个运算节点，返回它输出的 ValueId。
  // 输入必须是已经存在的 ValueId —— 这条约束让图天然无环。
  ValueId add_node(std::string op_type, std::string name,
                   std::vector<ValueId> inputs, Attributes attrs = {});

  void mark_output(ValueId id);

  // 建完图后必须调一次：
  //   1. 拓扑排序，定下执行顺序（顺便检测环和不可达节点）
  //   2. 形状推断，一次计算都不做就把所有中间结果的形状算出来
  //   3. 统计每个 Value 被几个节点消费，供执行时做内存复用
  // 任何结构性错误都在这一步暴露，而不是等到跑起来。
  void finalize();

  // --- 查询 ---------------------------------------------------------------
  [[nodiscard]] bool finalized() const noexcept { return finalized_; }
  [[nodiscard]] const Value& value(ValueId id) const;
  [[nodiscard]] const std::vector<Node>& nodes() const noexcept { return nodes_; }
  [[nodiscard]] const std::vector<Value>& values() const noexcept { return values_; }
  [[nodiscard]] const std::vector<int>& exec_order() const noexcept { return order_; }
  [[nodiscard]] const std::vector<ValueId>& outputs() const noexcept { return outputs_; }
  [[nodiscard]] const std::unordered_map<ValueId, Tensor>& weights() const noexcept {
    return weights_;
  }
  // 某个 Value 被多少个节点当作输入（含图输出，算一次）
  [[nodiscard]] int consumer_count(ValueId id) const;

  // 画成文本形式，方便肉眼检查图对不对
  [[nodiscard]] std::string to_string() const;

 private:
  std::vector<Value> values_;
  std::vector<Node> nodes_;
  std::unordered_map<ValueId, Tensor> weights_;
  std::vector<ValueId> outputs_;
  std::vector<int> order_;                  // 节点执行顺序
  std::unordered_map<ValueId, int> uses_;   // Value -> 消费者个数
  bool finalized_ = false;

  ValueId new_value(std::string name, Shape shape, Value::Kind kind);
  [[nodiscard]] std::vector<int> topological_order() const;
};

// ---------------------------------------------------------------------------
// 执行器：按拓扑序逐个节点算，并在中间结果用完后立刻释放它。
// ---------------------------------------------------------------------------
class Executor {
 public:
  explicit Executor(const Graph& g) : g_(&g) {}

  // feeds: 输入名 -> 张量。返回值按 mark_output 的顺序排列。
  [[nodiscard]] std::vector<Tensor> run(
      const std::unordered_map<std::string, Tensor>& feeds);

  // 内存复用开关。关掉之后所有中间结果都留到最后，
  // 用来对比「有没有做内存复用」的峰值差距。
  void set_reuse_memory(bool on) noexcept { reuse_ = on; }

  struct Stats {
    std::size_t peak_bytes = 0;   // 中间结果占用的峰值字节数
    std::size_t total_bytes = 0;  // 累计分配过的字节数
    int nodes_run = 0;
  };
  [[nodiscard]] const Stats& stats() const noexcept { return stats_; }

 private:
  const Graph* g_;
  bool reuse_ = true;
  Stats stats_;
};

}  // namespace infer

#include "infer/graph.hpp"

#include <algorithm>
#include <deque>
#include <format>
#include <stdexcept>
#include <unordered_set>

namespace infer {

namespace {

[[noreturn]] void fail(const std::string& msg) {
  throw std::invalid_argument("[infer::Graph] " + msg);
}

std::string shape_str(const Shape& s) {
  std::string out = "(";
  for (std::size_t i = 0; i < s.size(); ++i) {
    out += std::format("{}{}", s[i], i + 1 < s.size() ? ", " : "");
  }
  return out + ")";
}

}  // namespace

// ---------------------------------------------------------------------------
// 建图
// ---------------------------------------------------------------------------

ValueId Graph::new_value(std::string name, Shape shape, Value::Kind kind) {
  const auto id = static_cast<ValueId>(values_.size());
  values_.push_back(Value{.id = id,
                          .name = std::move(name),
                          .shape = std::move(shape),
                          .kind = kind});
  return id;
}

ValueId Graph::add_input(std::string name, Shape shape) {
  if (finalized_) fail("图已经 finalize 了，不能再改");
  return new_value(std::move(name), std::move(shape), Value::Kind::Input);
}

ValueId Graph::add_weight(std::string name, Tensor value) {
  if (finalized_) fail("图已经 finalize 了，不能再改");
  Shape shape = value.shape();
  const ValueId id = new_value(std::move(name), std::move(shape), Value::Kind::Weight);
  weights_.emplace(id, std::move(value));
  return id;
}

ValueId Graph::add_node(std::string op_type, std::string name,
                        std::vector<ValueId> inputs, Attributes attrs) {
  if (finalized_) fail("图已经 finalize 了，不能再改");

  // 建图时就检查算子存不存在，别等到执行时
  if (!OpRegistry::instance().has(op_type)) {
    (void)OpRegistry::instance().get(op_type);  // 借它的详细报错信息
  }
  for (ValueId in : inputs) {
    if (in < 0 || in >= static_cast<ValueId>(values_.size())) {
      fail(std::format("节点 '{}' 引用了不存在的 ValueId {}", name, in));
    }
  }

  const auto node_id = static_cast<int>(nodes_.size());
  // 输出 Value 先占位，形状留到 finalize 时推断
  const ValueId out = new_value(name + ".out", Shape{}, Value::Kind::Intermediate);

  nodes_.push_back(Node{.id = node_id,
                        .op_type = std::move(op_type),
                        .name = std::move(name),
                        .inputs = std::move(inputs),
                        .output = out,
                        .attrs = std::move(attrs)});
  return out;
}

void Graph::mark_output(ValueId id) {
  if (id < 0 || id >= static_cast<ValueId>(values_.size())) {
    fail(std::format("mark_output: 不存在的 ValueId {}", id));
  }
  outputs_.push_back(id);
}

// ---------------------------------------------------------------------------
// 拓扑排序（Kahn 算法）
//
//   1. 统计每个节点还有几个输入没就绪（入度）
//   2. 把入度为 0 的节点放进队列
//   3. 取出一个节点，标记它的输出已就绪，更新后继节点的入度
//   4. 重复，直到队列空
//   5. 如果还有节点没排进去，说明图里有环
//
//        ┌───┐     ┌───┐
//        │ A │────→│ C │        入度: A=0, B=0, C=2, D=1
//        └───┘  ┌─→└─┬─┘
//        ┌───┐  │    │          第 1 轮: 取出 A, B  →  C 入度归 0
//        │ B │──┘    ▼          第 2 轮: 取出 C     →  D 入度归 0
//        └───┘     ┌───┐        第 3 轮: 取出 D
//                  │ D │        执行顺序: A B C D
//                  └───┘
//
// 我们的 add_node 要求输入必须已存在，所以插入顺序天然就是一个合法拓扑序，
// 这个函数在当前 API 下总是返回 0,1,2,...。
//
// 那为什么还要写它？因为真实引擎从 ONNX / GGUF 文件加载的节点**可能是乱序的**，
// 文件格式并不保证节点按依赖顺序排列。到那时这个函数就是必需的。
// 顺便它还能免费帮我们检测环和不可达节点。
// ---------------------------------------------------------------------------
std::vector<int> Graph::topological_order() const {
  std::unordered_set<ValueId> ready;
  for (const Value& v : values_) {
    if (v.kind != Value::Kind::Intermediate) ready.insert(v.id);
  }

  std::vector<int> indeg(nodes_.size(), 0);
  // value -> 等着它的节点列表
  std::unordered_map<ValueId, std::vector<int>> waiters;
  for (const Node& n : nodes_) {
    for (ValueId in : n.inputs) {
      if (!ready.contains(in)) {
        ++indeg[static_cast<std::size_t>(n.id)];
        waiters[in].push_back(n.id);
      }
    }
  }

  std::deque<int> q;
  for (const Node& n : nodes_) {
    if (indeg[static_cast<std::size_t>(n.id)] == 0) q.push_back(n.id);
  }

  std::vector<int> order;
  order.reserve(nodes_.size());
  while (!q.empty()) {
    const int id = q.front();
    q.pop_front();
    order.push_back(id);

    const ValueId produced = nodes_[static_cast<std::size_t>(id)].output;
    if (auto it = waiters.find(produced); it != waiters.end()) {
      for (int w : it->second) {
        if (--indeg[static_cast<std::size_t>(w)] == 0) q.push_back(w);
      }
    }
  }

  if (order.size() != nodes_.size()) {
    fail(std::format("图里有环或有节点依赖了永远不会产生的值"
                     "（{} 个节点里只有 {} 个能排上）",
                     nodes_.size(), order.size()));
  }
  return order;
}

// ---------------------------------------------------------------------------
// finalize：形状推断 + 使用计数
// ---------------------------------------------------------------------------

void Graph::finalize() {
  if (finalized_) return;
  if (outputs_.empty()) fail("图没有标记任何输出，调 mark_output()");

  order_ = topological_order();

  // --- 形状推断 ---
  // 一次实际计算都不做，纯靠形状规则推。
  // 这让我们在推理开始前就知道每个中间结果多大 —— 阶段 7 的内存池全靠它。
  const OpRegistry& reg = OpRegistry::instance();
  for (int nid : order_) {
    Node& n = nodes_[static_cast<std::size_t>(nid)];
    const Op& op = reg.get(n.op_type);

    if (const int want = op.num_inputs();
        want >= 0 && static_cast<int>(n.inputs.size()) != want) {
      fail(std::format("节点 '{}' ({}) 需要 {} 个输入，但给了 {} 个",
                       n.name, n.op_type, want, n.inputs.size()));
    }

    std::vector<Shape> in_shapes;
    in_shapes.reserve(n.inputs.size());
    for (ValueId in : n.inputs) {
      in_shapes.push_back(values_[static_cast<std::size_t>(in)].shape);
    }

    try {
      values_[static_cast<std::size_t>(n.output)].shape =
          op.infer_shape(in_shapes, n.attrs);
    } catch (const std::exception& e) {
      // 把节点名字补进报错信息。模型有几百个节点时，
      // 「哪个节点出错」比「什么错」还重要。
      fail(std::format("节点 '{}' ({}) 形状推断失败: {}", n.name, n.op_type, e.what()));
    }
  }

  // --- 使用计数：每个 Value 被几个节点消费 ---
  for (const Node& n : nodes_) {
    for (ValueId in : n.inputs) ++uses_[in];
  }
  for (ValueId out : outputs_) ++uses_[out];  // 图输出也算一个消费者，不能被提前释放

  finalized_ = true;
}

const Value& Graph::value(ValueId id) const {
  if (id < 0 || id >= static_cast<ValueId>(values_.size())) {
    fail(std::format("不存在的 ValueId {}", id));
  }
  return values_[static_cast<std::size_t>(id)];
}

int Graph::consumer_count(ValueId id) const {
  auto it = uses_.find(id);
  return it == uses_.end() ? 0 : it->second;
}

std::string Graph::to_string() const {
  std::string s = std::format("Graph({} 个节点, {} 个 Value)\n",
                              nodes_.size(), values_.size());

  s += "  输入:\n";
  for (const Value& v : values_) {
    if (v.kind == Value::Kind::Input) {
      s += std::format("    v{:<3} {:<16} {}\n", v.id, v.name, shape_str(v.shape));
    }
  }
  s += "  权重:\n";
  for (const Value& v : values_) {
    if (v.kind == Value::Kind::Weight) {
      s += std::format("    v{:<3} {:<16} {}\n", v.id, v.name, shape_str(v.shape));
    }
  }
  s += "  计算:\n";
  const auto& order = finalized_ ? order_ : std::vector<int>{};
  auto emit = [&](const Node& n) {
    std::string ins;
    for (std::size_t i = 0; i < n.inputs.size(); ++i) {
      ins += std::format("v{}{}", n.inputs[i], i + 1 < n.inputs.size() ? ", " : "");
    }
    s += std::format("    v{:<3} = {:<10}({:<22}) {:<14} {}\n", n.output, n.op_type,
                     ins, shape_str(values_[static_cast<std::size_t>(n.output)].shape),
                     n.attrs.to_string());
  };
  if (order.empty()) {
    for (const Node& n : nodes_) emit(n);
  } else {
    for (int id : order) emit(nodes_[static_cast<std::size_t>(id)]);
  }
  s += "  输出:";
  for (ValueId id : outputs_) s += std::format(" v{}", id);
  return s + "\n";
}

// ---------------------------------------------------------------------------
// 执行
// ---------------------------------------------------------------------------

std::vector<Tensor> Executor::run(
    const std::unordered_map<std::string, Tensor>& feeds) {
  const Graph& g = *g_;
  if (!g.finalized()) fail("执行前必须先调 Graph::finalize()");

  stats_ = Stats{};

  // 活着的张量：ValueId -> Tensor
  std::unordered_map<ValueId, Tensor> live;
  // 每个中间 Value 还剩几个消费者没用过它
  std::unordered_map<ValueId, int> remaining;

  for (const Value& v : g.values()) {
    if (v.kind == Value::Kind::Input) {
      auto it = feeds.find(v.name);
      if (it == feeds.end()) {
        std::string names;
        for (const auto& [k, t] : feeds) names += " " + k;
        fail(std::format("缺少输入 '{}'，run() 收到的输入有:{}", v.name,
                         names.empty() ? " (无)" : names));
      }
      if (it->second.shape() != v.shape) {
        fail(std::format("输入 '{}' 形状应为 {}，实际是 {}", v.name,
                         shape_str(v.shape), shape_str(it->second.shape())));
      }
      live.emplace(v.id, it->second);
    }
  }
  for (const auto& [id, t] : g.weights()) live.emplace(id, t);
  for (const Value& v : g.values()) {
    if (v.kind == Value::Kind::Intermediate) remaining[v.id] = g.consumer_count(v.id);
  }

  const OpRegistry& reg = OpRegistry::instance();
  std::size_t alive_bytes = 0;

  for (int nid : g.exec_order()) {
    const Node& n = g.nodes()[static_cast<std::size_t>(nid)];

    OpContext ctx;
    ctx.inputs.reserve(n.inputs.size());
    for (ValueId in : n.inputs) {
      auto it = live.find(in);
      if (it == live.end()) {
        fail(std::format("节点 '{}' 的输入 v{} 已经被释放了 —— 使用计数算错了",
                         n.name, in));
      }
      ctx.inputs.push_back(&it->second);
    }
    ctx.attrs = &n.attrs;

    Tensor out = reg.get(n.op_type).compute(ctx);

    // 实际形状必须和推断的一致。不一致说明 infer_shape 写错了，
    // 这种 bug 在有内存池的引擎里会直接导致越界写，必须早发现。
    if (out.shape() != g.value(n.output).shape) {
      fail(std::format("节点 '{}' 实际输出形状 {} 与推断的 {} 不符",
                       n.name, shape_str(out.shape()),
                       shape_str(g.value(n.output).shape)));
    }

    const auto nbytes = static_cast<std::size_t>(out.numel()) * sizeof(float);
    stats_.total_bytes += nbytes;
    alive_bytes += nbytes;
    live.emplace(n.output, std::move(out));
    ++stats_.nodes_run;

    // --- 内存复用：输入用完就扔 ---
    //
    //   不复用：所有中间结果一直留到最后
    //     v3 v4 v5 v6 v7 ... 全都在内存里
    //
    //   复用：某个中间结果的消费者全部执行完，立刻释放
    //     算 v5 时 v3 已经没人要了 → 释放
    //
    // 对深网络这个差距非常大：10 层的网络能省掉 80% 的中间内存。
    // 真实引擎更进一步，会预先规划好内存并让不同张量复用同一块 buffer，
    // 那是阶段 7 的内容。
    if (reuse_) {
      for (ValueId in : n.inputs) {
        auto it = remaining.find(in);
        if (it == remaining.end()) continue;  // 输入或权重，不回收
        if (--it->second == 0) {
          auto lit = live.find(in);
          if (lit != live.end()) {
            alive_bytes -= static_cast<std::size_t>(lit->second.numel()) * sizeof(float);
            live.erase(lit);
          }
        }
      }
    }

    stats_.peak_bytes = std::max(stats_.peak_bytes, alive_bytes);
  }

  std::vector<Tensor> result;
  result.reserve(g.outputs().size());
  for (ValueId id : g.outputs()) {
    auto it = live.find(id);
    if (it == live.end()) fail(std::format("输出 v{} 不见了", id));
    result.push_back(it->second);
  }
  return result;
}

}  // namespace infer

