// 第 4 阶段：把模型结构从代码里抽出来，变成数据。
//
//   ./build/examples/04_graph

#include <format>
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

#include "infer/graph.hpp"
#include "infer/mlp.hpp"
#include "infer/model_file.hpp"
#include "infer/op.hpp"
#include "infer/ops.hpp"

using infer::Graph;
using infer::Tensor;
using infer::ValueId;
namespace ops = infer::ops;

template <class... Args>
void println(std::format_string<Args...> fmt, Args&&... args) {
  std::cout << std::format(fmt, std::forward<Args>(args)...) << '\n';
}

void section(const char* title) {
  std::cout << std::format("\n\033[36m===== {} =====\033[0m\n", title);
}

int main() {
  infer::register_builtin_ops();
  const std::string model_dir = std::string(INFER_MODEL_DIR) + "/";

  // -------------------------------------------------------------------------
  section("1. 已注册的算子");
  auto names = infer::OpRegistry::instance().list();
  std::sort(names.begin(), names.end());
  std::string line = "   ";
  for (const auto& n : names) line += " " + n;
  println("{}", line);
  println("");
  println("这些算子谁都没在「某个列表」里登记过。每个算子的 .cpp 里写一句");
  println("REGISTER_OP(XxxOp)，靠全局对象的构造函数在 main() 之前自动注册。");

  // -------------------------------------------------------------------------
  section("2. 用图重建阶段 3 的 MLP");

  const infer::ModelFile mf = infer::ModelFile::load(model_dir + "mnist_mlp.infer");

  Graph g;
  const ValueId x = g.add_input("x", {1, 784});
  const ValueId w1 = g.add_weight("fc1.w", mf.get("fc1.weight"));
  const ValueId b1 = g.add_weight("fc1.b", mf.get("fc1.bias"));
  const ValueId w2 = g.add_weight("fc2.w", mf.get("fc2.weight"));
  const ValueId b2 = g.add_weight("fc2.b", mf.get("fc2.bias"));

  const ValueId h1 = g.add_node("linear", "fc1", {x, w1, b1});
  const ValueId a1 = g.add_node("relu", "act1", {h1});
  const ValueId h2 = g.add_node("linear", "fc2", {a1, w2, b2});
  const ValueId p = g.add_node("softmax", "prob", {h2});
  g.mark_output(p);

  g.finalize();  // 拓扑排序 + 形状推断 + 使用计数
  std::cout << g.to_string();
  println("");
  println("注意所有中间结果的形状都填好了 —— finalize() 做了形状推断，");
  println("一次实际计算都没跑，就知道每步输出多大。这是内存规划的前提。");

  // -------------------------------------------------------------------------
  section("3. 和阶段 3 的硬编码版对比，结果必须一致");

  const infer::ModelFile act = infer::ModelFile::load(model_dir + "mnist_activations.infer");
  const Tensor input = act.get("input");

  infer::Executor exec(g);
  const std::vector<Tensor> out = exec.run({{"x", input}});

  const infer::MLP hardcoded = infer::MLP::from_file(model_dir + "mnist_mlp.infer");
  const Tensor want = hardcoded.forward_trace(input).prob;

  println("    图执行结果   vs  硬编码版:  最大误差 {:.3e}",
          static_cast<double>(ops::max_abs_diff(out[0], want)));
  println("    图执行结果   vs  Python  :  最大误差 {:.3e}",
          static_cast<double>(ops::max_abs_diff(out[0], act.get("prob"))));
  println("    预测数字: {}", ops::argmax(out[0]));
  println("");
  println("    执行了 {} 个节点，中间结果峰值内存 {} 字节",
          exec.stats().nodes_run, exec.stats().peak_bytes);

  // -------------------------------------------------------------------------
  section("4. 加一层有多容易");
  println("阶段 3 想加一层要改 C++ 代码然后重新编译。现在只要多写一行建图语句。");
  println("下面临时造一个 6 层的深网络（权重随便填），看看图能不能自动处理：");

  Graph deep;
  const ValueId dx = deep.add_input("x", {8, 256});
  ValueId cur = dx;
  for (int i = 0; i < 6; ++i) {
    const ValueId w = deep.add_weight(std::format("layer{}.w", i),
                                      Tensor::full({256, 256}, 0.01F));
    cur = deep.add_node("linear", std::format("fc{}", i), {cur, w});
    cur = deep.add_node("relu", std::format("act{}", i), {cur});
  }
  deep.mark_output(cur);
  deep.finalize();
  println("");
  println("    建好了 {} 个节点的图，形状推断全部自动完成。", deep.nodes().size());

  // -------------------------------------------------------------------------
  section("5. 内存复用：中间结果用完就扔");

  infer::Executor e_reuse(deep);
  infer::Executor e_keep(deep);
  e_keep.set_reuse_memory(false);

  const Tensor deep_in = Tensor::full({8, 256}, 0.1F);
  const auto r1 = e_reuse.run({{"x", deep_in}});
  const auto r2 = e_keep.run({{"x", deep_in}});

  const auto kb = [](std::size_t b) { return static_cast<double>(b) / 1024.0; };
  println("    不复用（全部留到最后）: 峰值 {:8.1f} KB", kb(e_keep.stats().peak_bytes));
  println("    复用（用完就释放）    : 峰值 {:8.1f} KB   \033[33m省 {:.0f}%\033[0m",
          kb(e_reuse.stats().peak_bytes),
          100.0 * (1.0 - static_cast<double>(e_reuse.stats().peak_bytes) /
                             static_cast<double>(e_keep.stats().peak_bytes)));
  println("    累计分配量两者相同    : {:8.1f} KB", kb(e_reuse.stats().total_bytes));
  println("    两种方式结果一致      : {}",
          ops::max_abs_diff(r1[0], r2[0]) == 0.0F ? "\033[32m是\033[0m" : "\033[31m否\033[0m");
  println("");
  println("    原理：每个 Value 记录「还有几个节点要用我」，归零就释放。");
  println("    网络越深省得越多 —— 真实的 GPT-2 有 148 个节点，这个优化是刚需。");

  // -------------------------------------------------------------------------
  section("6. 建图阶段就能抓到的错误");

  try {
    Graph bad;
    const ValueId in = bad.add_input("x", {2, 3});
    const ValueId w = bad.add_weight("w", Tensor::zeros({5, 7}));  // 形状对不上
    bad.mark_output(bad.add_node("linear", "fc", {in, w}));
    bad.finalize();
  } catch (const std::exception& e) {
    println("    形状不匹配 -> {}", e.what());
  }

  try {
    Graph bad;
    const ValueId in = bad.add_input("x", {2, 3});
    bad.mark_output(bad.add_node("conv2d", "c", {in}));
  } catch (const std::exception& e) {
    std::string msg = e.what();
    println("    未知算子   -> {}", msg.substr(0, msg.find('\n')));
  }

  try {
    Graph ok;
    const ValueId in = ok.add_input("x", {2, 3});
    ok.mark_output(ok.add_node("relu", "r", {in}));
    ok.finalize();
    infer::Executor ex(ok);
    (void)ex.run({{"wrong_name", Tensor::zeros({2, 3})}});
  } catch (const std::exception& e) {
    println("    输入名写错 -> {}", e.what());
  }

  println("");
  println("    全部在「一次浮点运算都还没做」的时候就被抓住了。");
  println("    这就是把结构变成数据的好处：可以在执行前检查它。");

  std::cout << '\n';
  return 0;
}

#include <string>
#include <unordered_map>

#include "infer/graph.hpp"
#include "infer/mlp.hpp"
#include "infer/model_file.hpp"
#include "infer/op.hpp"
#include "infer/ops.hpp"
#include "minitest.hpp"

using infer::Graph;
using infer::Tensor;
using infer::ValueId;
namespace ops = infer::ops;

namespace {

// 注册是全局一次性的，放在函数内 static 里保证只跑一次
bool ensure_ops() {
  static const bool once = [] {
    infer::register_builtin_ops();
    return true;
  }();
  return once;
}

const std::string kDir = std::string(INFER_MODEL_DIR) + "/";

bool models_ready() {
  static const bool ready = [] {
    try {
      (void)infer::ModelFile::load(kDir + "mnist_mlp.infer");
      return true;
    } catch (const std::exception&) {
      return false;
    }
  }();
  return ready;
}

}  // namespace

// ---------------------------------------------------------------------------
// 注册表
// ---------------------------------------------------------------------------

TEST(op_registry_has_builtins) {
  ensure_ops();
  const auto& reg = infer::OpRegistry::instance();
  for (const char* name : {"relu", "gelu", "softmax", "add", "mul",
                           "matmul", "linear", "layernorm"}) {
    CHECK(reg.has(name));
  }
  CHECK(!reg.has("conv2d"));
  CHECK_THROWS(reg.get("conv2d"));
}

// ---------------------------------------------------------------------------
// 属性
// ---------------------------------------------------------------------------

TEST(attributes_typed_access) {
  infer::Attributes a;
  a.set("eps", 1e-5F).set("axis", std::int64_t{-1}).set("mode", std::string("fast"));

  CHECK_NEAR(a.get<float>("eps"), 1e-5, 1e-12);
  CHECK(a.get<std::int64_t>("axis") == -1);
  CHECK(a.get<std::string>("mode") == "fast");

  CHECK(a.get_or<float>("missing", 2.5F) == 2.5F);
  CHECK_THROWS(a.get<float>("missing"));       // 不存在
  CHECK_THROWS(a.get<float>("axis"));          // 类型不对
}

// ---------------------------------------------------------------------------
// 建图与形状推断
// ---------------------------------------------------------------------------

TEST(graph_shape_inference) {
  ensure_ops();
  Graph g;
  const ValueId x = g.add_input("x", {4, 16});
  const ValueId w = g.add_weight("w", Tensor::zeros({32, 16}));
  const ValueId b = g.add_weight("b", Tensor::zeros({32}));
  const ValueId y = g.add_node("linear", "fc", {x, w, b});
  const ValueId r = g.add_node("relu", "act", {y});
  g.mark_output(r);
  g.finalize();

  // 一次计算都没做，形状已经全部推出来了
  CHECK((g.value(y).shape == infer::Shape{4, 32}));
  CHECK((g.value(r).shape == infer::Shape{4, 32}));
  CHECK(g.exec_order().size() == 2);
}

TEST(graph_rejects_shape_mismatch_at_build_time) {
  ensure_ops();
  Graph g;
  const ValueId x = g.add_input("x", {2, 3});
  const ValueId w = g.add_weight("w", Tensor::zeros({5, 7}));  // 期望输入 7 维
  g.mark_output(g.add_node("linear", "fc", {x, w}));
  CHECK_THROWS(g.finalize());
}

