  g.finalize();

  infer::Executor e(g);
  const auto out = e.run({{"x", Tensor::from({1, 4}, {-1, 2, -3, 4})}});

  CHECK(out.size() == 1);
  CHECK_NEAR(out[0](0, 0), 0.0, 1e-6);
  CHECK_NEAR(out[0](0, 1), 2.0, 1e-6);
