  CHECK(out.size() == 2);
  CHECK_NEAR(out[0](0, 2), 3.0, 1e-6);                        // relu 输出
  CHECK_NEAR(out[1](0, 0) + out[1](0, 1) + out[1](0, 2), 1.0, 1e-6);  // softmax 输出
