TEST(executor_memory_reuse_saves_peak) {
  ensure_ops();
  // 一条链：每个中间结果只被下一个节点用一次，用完就能扔
  Graph g;
  const ValueId x = g.add_input("x", {4, 64});
  ValueId cur = x;
  for (int i = 0; i < 8; ++i) {
    const ValueId w = g.add_weight("w" + std::to_string(i), Tensor::full({64, 64}, 0.01F));
    cur = g.add_node("linear", "fc" + std::to_string(i), {cur, w});
  }
  g.mark_output(cur);
  g.finalize();

  const Tensor in = Tensor::full({4, 64}, 0.5F);

  infer::Executor reuse(g);
  const auto r1 = reuse.run({{"x", in}});

  infer::Executor keep(g);
  keep.set_reuse_memory(false);
  const auto r2 = keep.run({{"x", in}});

  // 结果必须完全一致 —— 内存复用不能影响数值
  CHECK(ops::max_abs_diff(r1[0], r2[0]) == 0.0F);
  // 累计分配量相同，但峰值应大幅下降
  CHECK(reuse.stats().total_bytes == keep.stats().total_bytes);
  CHECK(reuse.stats().peak_bytes < keep.stats().peak_bytes / 3);
}

TEST(executor_keeps_value_with_multiple_consumers) {
  ensure_ops();
  // 菱形结构：v 被两个节点消费，第一个节点用完后不能释放它
  //      x
  //      │
  //      v ──┬──→ relu ──┐
  //          └──→ gelu ──┴──→ add
  Graph g;
  const ValueId x = g.add_input("x", {1, 4});
  const ValueId v = g.add_node("relu", "shared", {x});
  const ValueId a = g.add_node("relu", "branch_a", {v});
  const ValueId b = g.add_node("gelu", "branch_b", {v});
  const ValueId s = g.add_node("add", "merge", {a, b});
  g.mark_output(s);
  g.finalize();

  CHECK(g.consumer_count(v) == 2);

  infer::Executor e(g);
  const auto out = e.run({{"x", Tensor::from({1, 4}, {1, 2, 3, 4})}});
  // relu(1)=1, gelu(1)≈0.8412 -> 1.8412
  CHECK_NEAR(out[0](0, 0), 1.84119, 1e-4);
}

