TEST(graph_mlp_matches_hardcoded) {
  ensure_ops();
  if (!models_ready()) return;

  const auto mf = infer::ModelFile::load(kDir + "mnist_mlp.infer");
  const auto act = infer::ModelFile::load(kDir + "mnist_activations.infer");
  const Tensor input = act.get("input");

