input.contents:
// 阶段 5：矩阵乘法的优化版本。
//
// 这个文件是整个项目里唯一「为了快而牺牲可读性」的地方。
// 参考实现（kernel.cpp 里的 ijk 版本）永远保留着，每个优化版都要和它对拍。
//
// 四个优化手段，逐层叠加：
//   v3 tiled     分块，让数据待在 L1 cache 里
//   v4 avx2      一条指令算 8 个 float，累加器常驻寄存器
//   v5 parallel  多线程，把行分给不同的核

#include <algorithm>
#include <thread>
#include <vector>

#include "infer/kernel.hpp"

#if defined(__AVX2__) && defined(__FMA__)
#include <immintrin.h>
#define INFER_HAS_AVX2 1
#else
#define INFER_HAS_AVX2 0
#endif

namespace infer::kernel {

namespace {

// --- 分块尺寸 ---------------------------------------------------------------
// 本机 L1d = 48 KB/核 = 12288 个 float。
// 一个 64×64 的 float 块占 16 KB，A/B/C 三块加起来 48 KB，刚好卡在 L1 上限。
// 这些数字要按自己的 CPU 调，没有万能值 —— 所以工业库（OpenBLAS）会针对
// 每种微架构手工标定一套参数。
constexpr i64 kTileM = 64;
constexpr i64 kTileN = 64;
constexpr i64 kTileK = 64;

// --- AVX2 微内核尺寸 --------------------------------------------------------
// 一次算 C 的 4 行 × 16 列。为什么是这个形状？
//   16 列 = 2 个 __m256（每个装 8 个 float）
//   4 行 × 2 = 8 个累加器寄存器，再加 2 个 B 向量、1 个 A 广播 = 11 个
//   YMM 寄存器总共 16 个，留了余量给编译器周转。
//   再大就会「寄存器溢出」（spill）到栈上，反而变慢。
constexpr i64 kMR = 4;
constexpr i64 kNR = 16;

int g_num_threads = 0;  // 0 表示还没初始化，取硬件并发数

// 小问题不值得开线程：创建一个线程要几十微秒，
// 如果计算本身才几十微秒，那纯粹是赔本。真实引擎都有这个阈值判断。
constexpr i64 kParallelMinWork = 1 << 20;  // M*N*K 低于 100 万就串行

#if INFER_HAS_AVX2

// C 的 4×16 小块全程待在寄存器里，K 循环结束才写回内存一次。
// 对比标量版每次内积都要读写一遍 C，这是最大的性能来源。
void micro_kernel_4x16(const float* a, const float* b, float* c,
                       i64 K, i64 lda, i64 ldb, i64 ldc) {
  __m256 c00 = _mm256_setzero_ps(), c01 = _mm256_setzero_ps();
  __m256 c10 = _mm256_setzero_ps(), c11 = _mm256_setzero_ps();
  __m256 c20 = _mm256_setzero_ps(), c21 = _mm256_setzero_ps();
  __m256 c30 = _mm256_setzero_ps(), c31 = _mm256_setzero_ps();

  for (i64 k = 0; k < K; ++k) {
    // B 的一行 16 个数，两次 256 位加载
    const __m256 b0 = _mm256_loadu_ps(b + k * ldb);
    const __m256 b1 = _mm256_loadu_ps(b + k * ldb + 8);

    // broadcast：把 A 的一个标量复制到 8 个通道
    // fmadd(x, y, z) = x*y + z，乘加一条指令完成，还少一次舍入
    __m256 av = _mm256_set1_ps(a[0 * lda + k]);
    c00 = _mm256_fmadd_ps(av, b0, c00);
    c01 = _mm256_fmadd_ps(av, b1, c01);

    av = _mm256_set1_ps(a[1 * lda + k]);
    c10 = _mm256_fmadd_ps(av, b0, c10);
    c11 = _mm256_fmadd_ps(av, b1, c11);

    av = _mm256_set1_ps(a[2 * lda + k]);
    c20 = _mm256_fmadd_ps(av, b0, c20);
    c21 = _mm256_fmadd_ps(av, b1, c21);

    av = _mm256_set1_ps(a[3 * lda + k]);
    c30 = _mm256_fmadd_ps(av, b0, c30);
    c31 = _mm256_fmadd_ps(av, b1, c31);
  }

  _mm256_storeu_ps(c + 0 * ldc, c00);
  _mm256_storeu_ps(c + 0 * ldc + 8, c01);
  _mm256_storeu_ps(c + 1 * ldc, c10);
  _mm256_storeu_ps(c + 1 * ldc + 8, c11);
  _mm256_storeu_ps(c + 2 * ldc, c20);
  _mm256_storeu_ps(c + 2 * ldc + 8, c21);
  _mm256_storeu_ps(c + 3 * ldc, c30);
  _mm256_storeu_ps(c + 3 * ldc + 8, c31);
}

// 把 __m256 里的 8 个 float 加成一个标量。
// 做法是「折半相加」：8→4→2→1，共 3 轮，比逐个取出来加快得多。
inline float hsum256(__m256 v) {
  __m128 lo = _mm256_castps256_ps128(v);
  const __m128 hi = _mm256_extractf128_ps(v, 1);
  lo = _mm_add_ps(lo, hi);                       // 8 -> 4
  __m128 shuf = _mm_movehdup_ps(lo);
  __m128 sums = _mm_add_ps(lo, shuf);            // 4 -> 2
  shuf = _mm_movehl_ps(shuf, sums);
  sums = _mm_add_ss(sums, shuf);                 // 2 -> 1
  return _mm_cvtss_f32(sums);
}

#endif  // INFER_HAS_AVX2

// 标量兜底的小块计算，处理边角料（M/N 不是微内核尺寸整数倍的部分）
void scalar_block(const float* a, const float* b, float* c,
                  i64 m, i64 n, i64 K, i64 lda, i64 ldb, i64 ldc) {
  for (i64 i = 0; i < m; ++i) {
    for (i64 j = 0; j < n; ++j) {
      float sum = 0.0F;
      for (i64 k = 0; k < K; ++k) sum += a[i * lda + k] * b[k * ldb + j];
      c[i * ldc + j] = sum;
    }
  }
}

// 把一段行区间 [row_begin, row_end) 分给若干线程并行处理
template <class F>
void parallel_rows(i64 total_rows, i64 work, F&& fn) {
  const int nt = get_num_threads();
  if (nt <= 1 || work < kParallelMinWork || total_rows < 2) {
    fn(i64{0}, total_rows);
    return;
  }
  const auto chunks = std::min<i64>(nt, total_rows);
  const i64 per = (total_rows + chunks - 1) / chunks;

  // std::jthread 是 C++20 的新线程类型，比 std::thread 好在两点：
  //   1. 析构时自动 join，不会因为忘记 join 而 std::terminate
  //   2. 自带 stop_token，可以协作式取消（这里用不到）
  std::vector<std::jthread> workers;
  workers.reserve(static_cast<std::size_t>(chunks - 1));
  for (i64 t = 1; t < chunks; ++t) {
    const i64 lo = t * per;
    const i64 hi = std::min(lo + per, total_rows);
    if (lo >= hi) break;
    workers.emplace_back([&fn, lo, hi] { fn(lo, hi); });
  }
  fn(i64{0}, std::min(per, total_rows));  // 主线程也干一份活，别闲着
  // workers 析构时自动 join
}

}  // namespace

bool has_avx2_support() noexcept { return INFER_HAS_AVX2 != 0; }

void set_num_threads(int n) noexcept { g_num_threads = n < 1 ? 1 : n; }

int get_num_threads() noexcept {
  if (g_num_threads == 0) {
    const auto hw = static_cast<int>(std::thread::hardware_concurrency());
    g_num_threads = hw > 0 ? hw : 1;
  }
  return g_num_threads;
}

// ---------------------------------------------------------------------------
// v3：循环分块
// ---------------------------------------------------------------------------
void matmul_f32_tiled(std::span<const float> a, std::span<const float> b,
                      std::span<float> c, i64 M, i64 N, i64 K) {
  std::ranges::fill(c, 0.0F);

  // 三层分块循环在外，原来的 i-k-j 在内。
  // 效果是：一个 64×64 的 B 块被加载进 L1 后，会被 64 行 A 反复使用，
  // 而不是像 ikj 那样每行都重新从内存流一遍。
  for (i64 i0 = 0; i0 < M; i0 += kTileM) {
    const i64 i1 = std::min(i0 + kTileM, M);
    for (i64 k0 = 0; k0 < K; k0 += kTileK) {
      const i64 k1 = std::min(k0 + kTileK, K);
      for (i64 j0 = 0; j0 < N; j0 += kTileN) {
        const i64 j1 = std::min(j0 + kTileN, N);

        for (i64 i = i0; i < i1; ++i) {
          for (i64 k = k0; k < k1; ++k) {
            const float aik = a[static_cast<std::size_t>(i * K + k)];
            for (i64 j = j0; j < j1; ++j) {
              c[static_cast<std::size_t>(i * N + j)] +=
                  aik * b[static_cast<std::size_t>(k * N + j)];
            }
          }
        }
      }
    }
  }
}

// ---------------------------------------------------------------------------
// v4：AVX2 + FMA 微内核
// ---------------------------------------------------------------------------
void matmul_f32_avx2(std::span<const float> a, std::span<const float> b,
                     std::span<float> c, i64 M, i64 N, i64 K) {
#if INFER_HAS_AVX2
  const float* pa = a.data();
  const float* pb = b.data();
  float* pc = c.data();

  const i64 m_main = M / kMR * kMR;  // 能被微内核整除的部分
  const i64 n_main = N / kNR * kNR;

  for (i64 i = 0; i < m_main; i += kMR) {
    for (i64 j = 0; j < n_main; j += kNR) {
      micro_kernel_4x16(pa + i * K, pb + j, pc + i * N + j, K, K, N, N);
    }
    // 右边剩下不足 16 列的边角
    if (n_main < N) {
      scalar_block(pa + i * K, pb + n_main, pc + i * N + n_main,
                   kMR, N - n_main, K, K, N, N);
    }
  }
  // 下面剩下不足 4 行的边角
  if (m_main < M) {
    scalar_block(pa + m_main * K, pb, pc + m_main * N, M - m_main, N, K, K, N, N);
  }
#else
  matmul_f32_tiled(a, b, c, M, N, K);  // 没有 AVX2 就退回分块版
#endif
}

// ---------------------------------------------------------------------------
// v5：多线程
// ---------------------------------------------------------------------------
void matmul_f32_parallel(std::span<const float> a, std::span<const float> b,
                         std::span<float> c, i64 M, i64 N, i64 K) {
  // 按行切分。为什么切行不切列？因为 C 是行优先存储，
  // 不同线程写的是**不同的行**，落在不同的 cache line 上，
  // 不会发生 false sharing（两个核抢同一条 cache line 的所有权，性能暴跌）。
  parallel_rows(M, M * N * K, [&](i64 lo, i64 hi) {
    const i64 rows = hi - lo;
    if (rows <= 0) return;
    matmul_f32_avx2(a.subspan(static_cast<std::size_t>(lo * K)),
                    b,
                    c.subspan(static_cast<std::size_t>(lo * N)),
                    rows, N, K);
  });
}

void matmul_f32(std::span<const float> a, std::span<const float> b,
                std::span<float> c, i64 M, i64 N, i64 K) {
  matmul_f32_parallel(a, b, c, M, N, K);
}

// ---------------------------------------------------------------------------
// NT 版本（C = A × Wᵀ，linear 层用的就是它）
// ---------------------------------------------------------------------------
void matmul_nt_f32_avx2(std::span<const float> a, std::span<const float> w,
                        std::span<float> c, i64 M, i64 N, i64 K) {
#if INFER_HAS_AVX2
  const float* pa = a.data();
  const float* pw = w.data();
  float* pc = c.data();

  // NT 布局下 A 和 W 都沿 k 连续，所以直接沿 k 向量化，最后水平求和。
  // 这里做 4 行 A × 2 行 W 的寄存器分块：
  //   A 的每一行读进来能服务 2 个输出列，W 的每一行能服务 4 个输出行，
  //   内存流量降到朴素版的约 1/3。
  //   寄存器用量: 8 个累加器 + 4 个 a + 2 个 w = 14 个，YMM 共 16 个，刚好。
  constexpr i64 MR = 4, NR = 2;
  const i64 m_main = M / MR * MR;
  const i64 n_main = N / NR * NR;
  const i64 k_main = K / 8 * 8;

  for (i64 i = 0; i < m_main; i += MR) {
    for (i64 j = 0; j < n_main; j += NR) {
      __m256 acc[MR][NR];
      for (auto& row : acc) for (auto& v : row) v = _mm256_setzero_ps();

      for (i64 k = 0; k < k_main; k += 8) {
        const __m256 a0 = _mm256_loadu_ps(pa + (i + 0) * K + k);
        const __m256 a1 = _mm256_loadu_ps(pa + (i + 1) * K + k);
        const __m256 a2 = _mm256_loadu_ps(pa + (i + 2) * K + k);
        const __m256 a3 = _mm256_loadu_ps(pa + (i + 3) * K + k);
        const __m256 w0 = _mm256_loadu_ps(pw + (j + 0) * K + k);
        const __m256 w1 = _mm256_loadu_ps(pw + (j + 1) * K + k);

        acc[0][0] = _mm256_fmadd_ps(a0, w0, acc[0][0]);
        acc[0][1] = _mm256_fmadd_ps(a0, w1, acc[0][1]);
        acc[1][0] = _mm256_fmadd_ps(a1, w0, acc[1][0]);
        acc[1][1] = _mm256_fmadd_ps(a1, w1, acc[1][1]);
        acc[2][0] = _mm256_fmadd_ps(a2, w0, acc[2][0]);
        acc[2][1] = _mm256_fmadd_ps(a2, w1, acc[2][1]);
        acc[3][0] = _mm256_fmadd_ps(a3, w0, acc[3][0]);
        acc[3][1] = _mm256_fmadd_ps(a3, w1, acc[3][1]);
      }

      for (i64 r = 0; r < MR; ++r) {
        for (i64 t = 0; t < NR; ++t) {
          float sum = hsum256(acc[r][t]);
          // K 不是 8 的倍数时，剩下的几个标量补上
          for (i64 k = k_main; k < K; ++k) {
            sum += pa[(i + r) * K + k] * pw[(j + t) * K + k];
          }
          pc[(i + r) * N + (j + t)] = sum;
        }
      }
    }
    // 右边不足 2 列的边角
    for (i64 j = n_main; j < N; ++j) {
      for (i64 r = 0; r < MR; ++r) {
        float sum = 0.0F;
        for (i64 k = 0; k < K; ++k) sum += pa[(i + r) * K + k] * pw[j * K + k];
        pc[(i + r) * N + j] = sum;
      }
    }
  }
  // 下面不足 4 行的边角
  for (i64 i = m_main; i < M; ++i) {
    for (i64 j = 0; j < N; ++j) {
      float sum = 0.0F;
      for (i64 k = 0; k < K; ++k) sum += pa[i * K + k] * pw[j * K + k];
      pc[i * N + j] = sum;
    }
  }
#else
  matmul_nt_f32_naive(a, w, c, M, N, K);
#endif
}

void matmul_nt_f32_parallel(std::span<const float> a, std::span<const float> w,
                            std::span<float> c, i64 M, i64 N, i64 K) {
  parallel_rows(M, M * N * K, [&](i64 lo, i64 hi) {
    const i64 rows = hi - lo;
    if (rows <= 0) return;
    matmul_nt_f32_avx2(a.subspan(static_cast<std::size_t>(lo * K)),
                       w,
                       c.subspan(static_cast<std::size_t>(lo * N)),
                       rows, N, K);
  });
}

void matmul_nt_f32(std::span<const float> a, std::span<const float> w,
                   std::span<float> c, i64 M, i64 N, i64 K) {
  matmul_nt_f32_parallel(a, w, c, M, N, K);
}

}  // namespace infer::kernel

// 第 5 阶段：矩阵乘法优化，从 1.5 GFLOPS 一路往上爬。
//
//   ./build/examples/05_perf

#include <algorithm>
#include <chrono>
#include <cmath>
#include <format>
#include <functional>
#include <iostream>
#include <random>
#include <string>
#include <thread>
#include <vector>

#include "infer/kernel.hpp"
#include "infer/mlp.hpp"
#include "infer/model_file.hpp"
#include "infer/ops.hpp"
#include "infer/tensor.hpp"

using infer::Tensor;
using infer::i64;
namespace kernel = infer::kernel;
namespace ops = infer::ops;

template <class... Args>
void println(std::format_string<Args...> fmt, Args&&... args) {
  std::cout << std::format(fmt, std::forward<Args>(args)...) << '\n';
}

void section(const char* title) {
  std::cout << std::format("\n\033[36m===== {} =====\033[0m\n", title);
}

// 跑若干次取最小值。
//
// 为什么取最小值而不是平均值？因为干扰（操作系统调度、其他进程、
// cache 被别人挤掉）只会让某次变慢，不会让它变快。
// 最小值最接近「这段代码在理想条件下的真实速度」。
double bench_ms(const std::function<void()>& fn, int warmup = 1, int runs = 3) {
  for (int i = 0; i < warmup; ++i) fn();  // 预热：把数据和指令都拉进 cache
  double best = 1e30;
  for (int i = 0; i < runs; ++i) {
    const auto t0 = std::chrono::steady_clock::now();
    fn();
    const auto t1 = std::chrono::steady_clock::now();
    best = std::min(best, std::chrono::duration<double, std::milli>(t1 - t0).count());
  }
  return best;
}

void bar(double value, double max_value, int width = 30) {
  const int n = static_cast<int>(value / max_value * width + 0.5);
  std::cout << "\033[32m" << std::string(static_cast<std::size_t>(std::max(n, 1)), '#')
            << "\033[0m";
}

int main() {
  println("");
  println("CPU 线程数: {}    AVX2/FMA: {}", std::thread::hardware_concurrency(),
          kernel::has_avx2_support() ? "\033[32m可用\033[0m" : "\033[31m不可用\033[0m");

  // -------------------------------------------------------------------------
  section("1. 先算清楚理论上限");
  println("  本机 CPU 每核每周期能做多少浮点运算？");
  println("    AVX2 一条指令处理 8 个 float");
  println("    FMA 一条指令同时做乘和加      → 16 FLOP/指令");
  println("    每周期能发射 2 条 FMA         → 32 FLOP/周期/核");
  println("  按 ~3 GHz、7 个物理核估算：");
  println("    单核峰值 ≈ 32 × 3e9        = \033[1m96 GFLOPS\033[0m");
  println("    全核峰值 ≈ 96 × 7          = \033[1m672 GFLOPS\033[0m");
  println("");
  println("  真实代码能到峰值的 50~70% 就算很不错了（OpenBLAS 大约 85%）。");
  println("  知道上限才知道优化到哪算够 —— 否则你永远不知道还有多少空间。");

  // -------------------------------------------------------------------------
  section("2. 矩阵乘法 1024×1024×1024：五个版本");

  constexpr i64 N = 1024;
  const double flops = 2.0 * N * N * N;
  println("  计算量 {:.2f} GFLOP（{} 亿次乘加）", flops / 1e9,
          static_cast<i64>(flops / 2e8));
  println("");

  std::mt19937 rng(0);
  std::uniform_real_distribution<float> dist(-1.0F, 1.0F);
  Tensor a = Tensor::zeros({N, N});
  Tensor b = Tensor::zeros({N, N});
  for (float& v : a.data()) v = dist(rng);
  for (float& v : b.data()) v = dist(rng);

  Tensor ref = Tensor::zeros({N, N});
  Tensor out = Tensor::zeros({N, N});

  struct Variant {
    const char* name;
    const char* note;
    void (*fn)(std::span<const float>, std::span<const float>, std::span<float>,
               i64, i64, i64);
    int runs;
  };
  const Variant variants[] = {
      {"v1 朴素 i-j-k",  "教科书写法",              kernel::matmul_f32_ijk, 1},
      {"v2 换循环顺序",  "i-k-j，内层连续访问",      kernel::matmul_f32_ikj, 2},
      {"v3 循环分块",    "块装进 L1 cache",         kernel::matmul_f32_tiled, 2},
      {"v4 AVX2+FMA",   "4×16 微内核，累加器在寄存器", kernel::matmul_f32_avx2, 3},
      {"v5 多线程",      std::format("{} 线程并行", kernel::get_num_threads()).c_str(),
       kernel::matmul_f32_parallel, 3},
  };

  // 先用参考实现算出标准答案
  kernel::matmul_f32_ijk(a.data(), b.data(), ref.data(), N, N, N);

  double baseline = 0.0, best_gflops = 0.0;
  std::vector<std::pair<std::string, double>> results;

  for (const auto& v : variants) {
    std::ranges::fill(out.data(), 0.0F);
    const double ms = bench_ms([&] { v.fn(a.data(), b.data(), out.data(), N, N, N); },
                               0, v.runs);
    const double gflops = flops / (ms * 1e6);
    if (baseline == 0.0) baseline = ms;
    best_gflops = std::max(best_gflops, gflops);

    // 每个优化版都必须和参考实现对得上，否则再快也没意义
    const float diff = ops::max_abs_diff(out, ref);
    const bool ok = diff < 1e-3F;

    results.emplace_back(v.name, gflops);
    println("  {:<14} {:>9.1f} ms  {:>7.1f} GFLOPS  {:>6.1f}×   {}  {}",
            v.name, ms, gflops, baseline / ms,
            ok ? "\033[32m正确\033[0m" : "\033[31m错误!\033[0m", v.note);
  }

  println("");
  for (const auto& [name, g] : results) {
    std::cout << std::format("  {:<14} ", name);
    bar(g, best_gflops);
    std::cout << std::format(" {:.1f}\n", g);
  }
  println("");
  println("  总加速比 \033[1m{:.0f}×\033[0m，达到理论峰值的约 {:.0f}%",
          results.back().second / results.front().second, best_gflops / 672.0 * 100.0);

  // -------------------------------------------------------------------------
  section("3. 每一步到底优化了什么");
  println("  v1 → v2  换循环顺序：内层从「跳着读」变成「顺序读」");
  println("           一条 cache line 64 字节能装 16 个 float，顺序读才用得满");
  println("");
  println("  v2 → v3  分块：把 B 的一块 64×64 加载进 L1 后，被 64 行 A 反复使用");
  println("           L1 只有 48 KB，装不下整个矩阵，但装得下小块");
  println("");
  println("  v3 → v4  SIMD：一条 FMA 指令算 8 个 float 的乘加");
  println("           关键是 C 的 4×16 小块全程待在寄存器里，K 循环结束才写回内存");
  println("           寄存器只有 16 个 YMM，分块尺寸就是按这个定的");
  println("");
  println("  v4 → v5  多线程：按行切给 {} 个线程", kernel::get_num_threads());
  println("           切行不切列，因为不同线程写不同 cache line，避免 false sharing");

  // -------------------------------------------------------------------------
  section("4. 线程数的影响");
  const int saved = kernel::get_num_threads();
  println("  {:>8} {:>12} {:>12} {:>10}", "线程数", "耗时(ms)", "GFLOPS", "并行效率");
  double one_thread_ms = 0.0;
  for (int nt : {1, 2, 4, 8, saved}) {
    if (nt > saved) continue;
    kernel::set_num_threads(nt);
    const double ms = bench_ms(
        [&] { kernel::matmul_f32_parallel(a.data(), b.data(), out.data(), N, N, N); },
        1, 3);
    if (nt == 1) one_thread_ms = ms;
    println("  {:>8} {:>12.1f} {:>12.1f} {:>9.0f}%", nt, ms, flops / (ms * 1e6),
            one_thread_ms / ms / nt * 100.0);
  }
  kernel::set_num_threads(saved);
  println("");
  println("  并行效率不到 100% 很正常：内存带宽是所有核共享的，");
  println("  核多了之后瓶颈从「算不过来」变成「数据供不上」。");
  println("  而且本机 7 个物理核里有能效核，单核性能本来就不一样。");

  // -------------------------------------------------------------------------
  section("5. 回到阶段 3 遗留的问题：批量推理终于变快了");

  const std::string model_dir = std::string(INFER_MODEL_DIR) + "/";
  try {
    const auto model = infer::MLP::from_file(model_dir + "mnist_mlp.infer");
    const auto samples = infer::ModelFile::load(model_dir + "mnist_samples.infer");
    const Tensor images = samples.get("images");
    const i64 n = images.dim(0);

    // 逐张
    const double one_ms = bench_ms([&] {
      for (i64 i = 0; i < n; ++i) {
        const Tensor img = images.slice(0, i, i + 1).contiguous();
        (void)model.forward(img);
      }
    }, 1, 3);

    // 批量
    const double batch_ms = bench_ms([&] { (void)model.forward(images); }, 1, 3);

    println("  {} 张 MNIST 图片：", n);
    println("    逐张推理 {} 次: {:8.2f} ms", n, one_ms);
    println("    批量推理  1 次: {:8.2f} ms   \033[33m快 {:.1f}×\033[0m",
            batch_ms, one_ms / batch_ms);
    println("");
    println("  阶段 3 时这个比值是 0.9×（批量反而略慢）。");
    println("  当时的原因：样本循环在最外层，每个样本都要把整个权重矩阵流一遍。");
    println("  现在寄存器分块让权重块加载一次就服务 4 个样本，批量的优势才兑现。");
    println("");
    println("  \033[1m这就是阶段 3 那句话的完整含义：\033[0m");
    println("  架构层面的优化（batching），必须有 kernel 层面的支持才能落地。");
  } catch (const std::exception& e) {
    println("  跳过（没找到模型文件，先跑 tools/train_mnist.py）");
  }

  // -------------------------------------------------------------------------
  section("6. 小矩阵：多线程反而更慢");
  println("  创建一个线程要几十微秒。如果计算本身就只要几十微秒，纯属赔本。");
  println("");
  println("  {:>12} {:>12} {:>12} {:>10}", "矩阵规模", "串行(ms)", "并行(ms)", "结果");
  for (i64 sz : {32, 64, 128, 256, 512}) {
    Tensor sa = Tensor::full({sz, sz}, 0.5F);
    Tensor sb = Tensor::full({sz, sz}, 0.5F);
    Tensor sc = Tensor::zeros({sz, sz});

    kernel::set_num_threads(1);
    const double s_ms = bench_ms(
        [&] { kernel::matmul_f32_parallel(sa.data(), sb.data(), sc.data(), sz, sz, sz); },
        2, 5);
    kernel::set_num_threads(saved);
    const double p_ms = bench_ms(
        [&] { kernel::matmul_f32_parallel(sa.data(), sb.data(), sc.data(), sz, sz, sz); },
        2, 5);

    println("  {:>9}³ {:>12.3f} {:>12.3f} {:>13}", sz, s_ms, p_ms,
            p_ms < s_ms ? "\033[32m并行更快\033[0m" : "\033[33m串行更快\033[0m");
  }
  kernel::set_num_threads(saved);
  println("");
  println("  所以 kernel 里有个阈值判断：M×N×K 小于 100 万就不开线程。");
  println("  真实引擎还会用**线程池**避免反复创建线程 —— 那是练习题。");

  std::cout << '\n';
  return 0;
}

