void matmul_f32_avx2(std::span<const float> a, std::span<const float> b,
                     std::span<float> c, i64 M, i64 N, i64 K) {
#if INFER_HAS_AVX2
  const float* pa = a.data();
  const float* pb = b.data();
  float* pc = c.data();

  const i64 m_main = M / kMR * kMR;  // 能被微内核整除的部分
  const i64 n_main = N / kNR * kNR;

  for (i64 i = 0; i < m_main; i += kMR) {
    for (i64 j = 0; j < n_main; j += kNR) {
      micro_kernel_4x16(pa + i * K, pb + j, pc + i * N + j, K, K, N, N);
    }
    // 右边剩下不足 16 列的边角
    if (n_main < N) {
      scalar_block(pa + i * K, pb + n_main, pc + i * N + n_main,
                   kMR, N - n_main, K, K, N, N);
    }
  }
  // 下面剩下不足 4 行的边角
  if (m_main < M) {
    scalar_block(pa + m_main * K, pb, pc + m_main * N, M - m_main, N, K, K, N, N);
  }
#else
  matmul_f32_tiled(a, b, c, M, N, K);  // 没有 AVX2 就退回分块版
#endif
}

