void matmul_f32_avx2(std::span<const float> a, std::span<const float> b,
                     std::span<float> c, i64 M, i64 N, i64 K) {
#if INFER_HAS_AVX2
  const float* pa = a.data();
  const float* pb = b.data();
  float* pc = c.data();
  std::ranges::fill(c, 0.0F);

  // 三层分块 + 微内核，这是 BLIS/OpenBLAS 的经典结构（只差一步 packing）。
  //
  //   jc 循环：把 B 切成 256 列宽的 panel
  //     kc 循环：把公共维度切成 256 一段
  //       ic 循环：把 A 切成 128 行高的 panel
  //         微内核：一次算 C 的 4×16 小块，累加器全在寄存器里
  //
  // 每层分块对应一级 cache：
  //   B panel (256×256 float = 256 KB) 目标是待在 L2
  //   A panel (128×256 float = 128 KB) 也在 L2
  //   微内核的工作集只有几 KB，稳稳待在 L1
  for (i64 jc = 0; jc < N; jc += kBlockN) {
    const i64 jc_end = std::min(jc + kBlockN, N);
    for (i64 kc = 0; kc < K; kc += kBlockK) {
      const i64 kc_end = std::min(kc + kBlockK, K);
      const i64 kb = kc_end - kc;

      for (i64 ic = 0; ic < M; ic += kBlockM) {
        const i64 ic_end = std::min(ic + kBlockM, M);

        for (i64 i = ic; i < ic_end; i += kMR) {
          const i64 mr = std::min(kMR, ic_end - i);
          for (i64 j = jc; j < jc_end; j += kNR) {
            const i64 nr = std::min(kNR, jc_end - j);

            if (mr == kMR && nr == kNR) {
              micro_kernel_4x16(pa + i * K + kc, pb + kc * N + j,
                                pc + i * N + j, kb, K, N, N);
            } else {
              // 边角料走标量路径。真实库会用 padding 避免这些分支，
              // 我们图个简单，反正边角只占很小一部分。
              scalar_block_acc(pa + i * K + kc, pb + kc * N + j,
                               pc + i * N + j, mr, nr, kb, K, N, N);
            }
          }
        }
      }
    }
  }
#else
  matmul_f32_tiled(a, b, c, M, N, K);  // 没有 AVX2 就退回分块版
#endif
}

