// 阶段 5：所有优化版本都必须和参考实现算出同样的结果。
//
// 优化最怕的就是「快了但算错了」。参考实现（matmul_f32_ijk）永远保留，
// 每个优化版都拿它当标准答案对拍。

#include <random>
#include <vector>

#include "infer/kernel.hpp"
#include "infer/ops.hpp"
#include "infer/tensor.hpp"
#include "minitest.hpp"

using infer::Tensor;
using infer::i64;
namespace kernel = infer::kernel;
namespace ops = infer::ops;

namespace {

struct Pair {
  Tensor a, b;
};

Pair random_pair(i64 M, i64 K, i64 N, unsigned seed) {
  std::mt19937 rng(seed);
  std::uniform_real_distribution<float> dist(-1.0F, 1.0F);
  Tensor a = Tensor::zeros({M, K});
  Tensor b = Tensor::zeros({K, N});
  for (float& v : a.data()) v = dist(rng);
  for (float& v : b.data()) v = dist(rng);
  return {std::move(a), std::move(b)};
}

// f32 累加 K 次，误差大致随 √K 增长。给一个宽松但仍有意义的容差。
float tol_for(i64 K) { return 2e-4F * static_cast<float>(K) / 256.0F + 1e-4F; }

}  // namespace

TEST(matmul_variants_agree_on_many_shapes) {
  // 故意挑一堆非整数倍的尺寸，专门打微内核的边角处理。
  // 4×16 的微内核最容易在 M%4≠0 或 N%16≠0 的地方出错。
  const struct { i64 M, K, N; } cases[] = {
      {1, 1, 1},      {1, 784, 128},  {3, 5, 7},      {4, 16, 16},
      {5, 17, 19},    {16, 16, 16},   {31, 33, 37},   {64, 64, 64},
      {65, 63, 67},   {100, 200, 50}, {128, 128, 128},{7, 1, 13},
  };

  for (const auto& c : cases) {
    const auto [a, b] = random_pair(c.M, c.K, c.N, 42);
    Tensor ref = Tensor::zeros({c.M, c.N});
    kernel::matmul_f32_ijk(a.data(), b.data(), ref.data(), c.M, c.N, c.K);

    const float tol = tol_for(c.K);
    for (auto* fn : {kernel::matmul_f32_ikj, kernel::matmul_f32_tiled,
                     kernel::matmul_f32_avx2, kernel::matmul_f32_parallel,
                     kernel::matmul_f32}) {
      Tensor got = Tensor::full({c.M, c.N}, 12345.0F);  // 填脏数据，逼算子自己清零
      fn(a.data(), b.data(), got.data(), c.M, c.N, c.K);
      const float diff = ops::max_abs_diff(got, ref);
      if (diff > tol) {
        throw minitest::Failure(
            std::format("形状 {}x{}x{} 结果不一致，误差 {:.3e} > 容差 {:.3e}",
                        c.M, c.K, c.N, diff, tol));
      }
    }
  }
}

TEST(matmul_parallel_path_is_actually_exercised) {
  // 上面那些形状都太小，会被 kernel 内的阈值判定为「不值得开线程」而走串行。
  // 这条测试专门用一个足够大的矩阵，确保真的跑到多线程代码路径。
  //
  // 这里曾经藏过一个真实的 bug：并行版给每个线程切 span 时只给了偏移
  // 没给长度，于是每个线程的清零操作把后面线程的结果全擦了。
  // 小矩阵测试完全抓不到它 —— 测试必须覆盖到每条代码路径。
  constexpr i64 M = 200, K = 150, N = 140;  // M*N*K = 420 万，超过并行阈值
  const auto [a, b] = random_pair(M, K, N, 7);

  Tensor ref = Tensor::zeros({M, N});
  kernel::matmul_f32_ijk(a.data(), b.data(), ref.data(), M, N, K);

  const int saved = kernel::get_num_threads();
  for (int nt : {1, 2, 4, saved}) {
    kernel::set_num_threads(nt);
    Tensor got = Tensor::full({M, N}, -999.0F);
    kernel::matmul_f32_parallel(a.data(), b.data(), got.data(), M, N, K);
    const float diff = ops::max_abs_diff(got, ref);
    if (diff > tol_for(K)) {
      throw minitest::Failure(std::format("{} 线程时结果错误，误差 {:.3e}", nt, diff));
    }
  }
  kernel::set_num_threads(saved);
}

TEST(matmul_nt_variants_agree) {
  const struct { i64 M, K, N; } cases[] = {
      {1, 784, 128}, {3, 5, 7},     {4, 8, 2},      {5, 17, 3},
      {200, 784, 128},               {64, 64, 64},  {33, 31, 29},
  };

  for (const auto& c : cases) {
    std::mt19937 rng(11);
    std::uniform_real_distribution<float> dist(-1.0F, 1.0F);
    Tensor a = Tensor::zeros({c.M, c.K});
    Tensor w = Tensor::zeros({c.N, c.K});  // NT 布局：权重是 (out, in)
    for (float& v : a.data()) v = dist(rng);
    for (float& v : w.data()) v = dist(rng);

    Tensor ref = Tensor::zeros({c.M, c.N});
    kernel::matmul_nt_f32_naive(a.data(), w.data(), ref.data(), c.M, c.N, c.K);

    const float tol = tol_for(c.K);
    for (auto* fn : {kernel::matmul_nt_f32_avx2, kernel::matmul_nt_f32_parallel,
                     kernel::matmul_nt_f32}) {
      Tensor got = Tensor::full({c.M, c.N}, 777.0F);
      fn(a.data(), w.data(), got.data(), c.M, c.N, c.K);
      const float diff = ops::max_abs_diff(got, ref);
      if (diff > tol) {
        throw minitest::Failure(
            std::format("NT {}x{}x{} 误差 {:.3e} > 容差 {:.3e}",
                        c.M, c.K, c.N, diff, tol));
      }
    }
  }
}

TEST(matmul_thread_count_does_not_change_result) {
  // 改线程数只能影响速度，绝不能影响结果。
  // 如果变了，多半是某处有数据竞争。
  constexpr i64 M = 128, K = 128, N = 128;
  const auto [a, b] = random_pair(M, K, N, 3);

  const int saved = kernel::get_num_threads();
  kernel::set_num_threads(1);
  Tensor r1 = Tensor::zeros({M, N});
  kernel::matmul_f32_parallel(a.data(), b.data(), r1.data(), M, N, K);

  for (int nt : {2, 3, 8, saved}) {
    kernel::set_num_threads(nt);
    Tensor r2 = Tensor::zeros({M, N});
    kernel::matmul_f32_parallel(a.data(), b.data(), r2.data(), M, N, K);
    // 每行的计算完全独立，换线程数不改变任何一次浮点运算的顺序，
    // 所以这里可以要求逐位相同
    CHECK(ops::max_abs_diff(r1, r2) == 0.0F);
  }
  kernel::set_num_threads(saved);
}

TEST(matmul_zero_and_identity) {
  // 零矩阵：输出必须全 0（顺便验证算子会自己清零，而不是依赖调用方）
  Tensor z = Tensor::zeros({8, 8});
  Tensor out = Tensor::full({8, 8}, 5.0F);
  kernel::matmul_f32(z.data(), z.data(), out.data(), 8, 8, 8);
  for (float v : out.data()) CHECK(v == 0.0F);

  // 单位矩阵：A × I == A
  constexpr i64 n = 40;
  std::mt19937 rng(5);
  std::uniform_real_distribution<float> dist(-1.0F, 1.0F);
  Tensor a = Tensor::zeros({n, n});
  for (float& v : a.data()) v = dist(rng);
  Tensor eye = Tensor::zeros({n, n});
  for (i64 i = 0; i < n; ++i) eye(i, i) = 1.0F;

  Tensor got = Tensor::zeros({n, n});
  kernel::matmul_f32(a.data(), eye.data(), got.data(), n, n, n);
  CHECK(ops::max_abs_diff(got, a) < 1e-6F);
}

TEST(ops_layer_still_correct_after_optimization) {
  // ops 层一行代码都没改，但底层 kernel 换了。
  // 这条测试确认分层没有漏 —— 上层拿到的结果依然正确。
  Tensor a = Tensor::from({2, 3}, {1, 2, 3, 4, 5, 6});
  Tensor b = Tensor::from({3, 2}, {1, 2, 3, 4, 5, 6});
  Tensor c = ops::matmul(a, b);
  CHECK_NEAR(c(0, 0), 22.0, 1e-5);
  CHECK_NEAR(c(1, 1), 64.0, 1e-5);

  Tensor x = Tensor::from({1, 2}, {1, 2});
  Tensor w = Tensor::from({3, 2}, {1, 0, 0, 1, 1, 1});
  Tensor bias = Tensor::from({3}, {1, 2, 3});
  Tensor y = ops::linear(x, w, bias);
  CHECK_NEAR(y(0, 0), 2.0, 1e-5);
  CHECK_NEAR(y(0, 2), 6.0, 1e-5);
}

