section("1. 先测出本机的实际上限");
println("  理论峰值可以算：AVX2 一次 8 个 float × FMA 乘加合一 × 2 个发射端口");
println("                 = 32 FLOP/周期/核。但本机是混合架构（性能核 + 能效核），");
println("                 频率和 AVX2 吞吐都不一样，纸上算出来的数不太可信。");
println("");
println("  更靠谱的办法是**实测**：跑一段除了 FMA 什么都不干的循环，");
println("  用多个独立累加器填满流水线，不碰内存。这就是本机的天花板。");
println("");
const double peak_1 = measure_peak_gflops(1);
const double peak_all = measure_peak_gflops(kernel::get_num_threads());
println("    单线程实测峰值: \033[1m{:6.1f} GFLOPS\033[0m", peak_1);
println("    {:2} 线程实测峰值: \033[1m{:6.1f} GFLOPS\033[0m",
        kernel::get_num_threads(), peak_all);
println("");
println("  知道上限才知道优化到哪算够。下面所有成绩都会和这个数对比。");

// 实测本机浮点峰值：一段只做 FMA、完全不碰内存的循环。
//
// 关键是用**多个独立的累加器**。CPU 的 FMA 指令有 4~5 个周期的延迟，
// 如果只用一个累加器，下一条 FMA 必须等上一条算完，流水线全空着。
// 开 8 个互不依赖的累加器，就能让每个周期都有指令在发射。
double measure_peak_gflops(int threads) {
#if defined(__AVX2__) && defined(__FMA__)
  constexpr long long kIters = 2'000'000;
  constexpr int kAcc = 8;  // 8 个独立累加器，够填满流水线

  auto work = [&]() {
    __m256 acc[kAcc];
    for (int i = 0; i < kAcc; ++i) acc[i] = _mm256_set1_ps(static_cast<float>(i));
    const __m256 x = _mm256_set1_ps(1.0000001F);
    const __m256 y = _mm256_set1_ps(0.9999999F);
    for (long long it = 0; it < kIters; ++it) {
      for (int i = 0; i < kAcc; ++i) acc[i] = _mm256_fmadd_ps(x, y, acc[i]);
    }
    // 把结果用掉，防止编译器认定整段循环无用而删掉它
    __m256 s = acc[0];
    for (int i = 1; i < kAcc; ++i) s = _mm256_add_ps(s, acc[i]);
    float tmp[8];
    _mm256_storeu_ps(tmp, s);
    return tmp[0] + tmp[7];
  };

  volatile float sink = 0.0F;
  const auto t0 = std::chrono::steady_clock::now();
  {
    std::vector<std::jthread> ts;
    for (int t = 1; t < threads; ++t) ts.emplace_back([&] { sink = sink + work(); });
    sink = sink + work();
  }
  const auto t1 = std::chrono::steady_clock::now();
  const double sec = std::chrono::duration<double>(t1 - t0).count();

  // 每次 fmadd 处理 8 个 float，每个是一次乘 + 一次加 = 16 FLOP
  const double total = 16.0 * kAcc * static_cast<double>(kIters) * threads;
  return total / sec / 1e9;
#else
  (void)threads;
  return 0.0;
#endif
}

