#pragma once

#include <functional>
#include <string>
#include <vector>

#include "infer/model_file.hpp"
#include "infer/tensor.hpp"

namespace infer {

// ---------------------------------------------------------------------------
// GPT-2 的结构
//
//   token ids [T]
//        │
//   ┌────▼─────────────────────────────┐
//   │ wte[token] + wpe[position]       │  词嵌入 + 位置嵌入
//   └────┬─────────────────────────────┘
//        │  x: [T, 768]
//   ╔════▼═════════════════════════════╗
//   ║  Transformer Block  × 12          ║
//   ║                                   ║
//   ║    x ──┬──→ LayerNorm             ║
//   ║        │        │                 ║
//   ║        │   Multi-Head Attention   ║   ← 唯一让 token 之间交换信息的地方
//   ║        │        │                 ║
//   ║        └────→  (+)  残差           ║
//   ║                 │                 ║
//   ║        ┌────────┤                 ║
//   ║        │   LayerNorm              ║
//   ║        │        │                 ║
//   ║        │       MLP (768→3072→768) ║   ← 每个 token 独立处理
//   ║        │        │                 ║
//   ║        └────→  (+)  残差           ║
//   ╚════┬══════════════════════════════╝
//        │
//   ┌────▼─────────────────────────────┐
//   │ LayerNorm                        │
//   │ × wteᵀ  (和词嵌入共享权重)         │  输出 logits [T, 50257]
//   └──────────────────────────────────┘
//
// 124M 参数里，注意力占 28M，MLP 占 57M，词嵌入占 38M。
// 所以推理时间大头在 MLP，不是很多人以为的注意力。
// ---------------------------------------------------------------------------

struct GPT2Config {
  int n_layer = 12;
  int n_head = 12;
  int n_embd = 768;
  int n_vocab = 50257;
  int n_ctx = 1024;

  [[nodiscard]] int head_size() const { return n_embd / n_head; }
};

// ---------------------------------------------------------------------------
// KV-Cache：LLM 推理最重要的优化
//
//   不用 cache：每生成一个词，整段重算一遍
//     第 1 步: [The]                       算 1 个
//     第 2 步: [The capital]               算 2 个  ← "The" 白算了
//     第 3 步: [The capital of]            算 3 个  ← 前两个又白算
//     总计算量 O(n²)
//
//   用 cache：把每层算过的 K、V 存起来
//     ┌──────── KV Cache ────────┐
//     │ K: [The][capital]  ...   │
//     │ V: [The][capital]  ...   │
//     └──────────────────────────┘
//     第 3 步: 只算 [of] 的 Q/K/V，和 cache 拼起来做注意力
//     总计算量 O(n)
//
// 代价是内存：每层要存 2 × n_ctx × n_embd 个 float。
// GPT-2 满上下文时 = 12 层 × 2 × 1024 × 768 × 4 字节 ≈ 72 MB。
// 大模型上 KV-Cache 往往比权重还占地方，所以有了 MQA/GQA/PagedAttention 这些优化。
// ---------------------------------------------------------------------------
class KVCache {
 public:
  KVCache(const GPT2Config& cfg, int max_len);

  [[nodiscard]] int length() const noexcept { return len_; }
  [[nodiscard]] int capacity() const noexcept { return max_len_; }
  void reset() noexcept { len_ = 0; }

  // 把某层某个位置的 K/V 写进缓存
  void append(int layer, int pos, std::span<const float> k, std::span<const float> v);
  void set_length(int n) noexcept { len_ = n; }

  [[nodiscard]] std::span<const float> keys(int layer) const;
  [[nodiscard]] std::span<const float> values(int layer) const;

  [[nodiscard]] std::size_t bytes() const noexcept;

 private:
  GPT2Config cfg_;
  int max_len_ = 0;
  int len_ = 0;
  std::vector<Tensor> k_;  // 每层一个 [max_len, n_embd]
  std::vector<Tensor> v_;
};

// 采样策略：模型给出 50257 个 logits，怎么从里面挑一个 token
struct SamplerConfig {
  float temperature = 1.0F;  // 越低越保守，0 表示贪心（永远选最大的）
  int top_k = 0;             // 只在概率最高的 k 个里选，0 表示不限
  float top_p = 1.0F;        // 核采样：只在累计概率达到 p 的最小集合里选
  std::uint64_t seed = 42;
};

class Sampler {
 public:
  explicit Sampler(SamplerConfig cfg) : cfg_(cfg), state_(cfg.seed ? cfg.seed : 1) {}
  [[nodiscard]] int sample(std::span<const float> logits);

 private:
  SamplerConfig cfg_;
  std::uint64_t state_;
  [[nodiscard]] float next_uniform();
};

class GPT2 {
 public:
  static GPT2 load(const std::string& model_dir);

  [[nodiscard]] const GPT2Config& config() const noexcept { return cfg_; }

  // 一次处理整个序列（prefill 阶段），返回全部位置的 logits [T, n_vocab]。
  // 不用 KV-Cache，用于对拍和理解基本流程。
  [[nodiscard]] Tensor forward(std::span<const int> tokens);

  // 带 KV-Cache 的单步推理：只处理一个新 token，返回它的 logits [n_vocab]。
  // 这是实际生成时走的路径。
  [[nodiscard]] Tensor forward_one(int token, int pos, KVCache& cache);

  // 生成：先把 prompt 喂进去（prefill），再逐个 token 往外吐（decode）
  struct GenStats {
    double prefill_ms = 0;
    double decode_ms = 0;
    int generated = 0;
  };
  std::vector<int> generate(std::span<const int> prompt, int max_new_tokens,
                            Sampler& sampler, GenStats* stats = nullptr,
                            const std::function<void(int)>& on_token = {});

  // 逐层中间结果，用来和 Python 参考实现对拍
  struct Trace {
    Tensor embed;
    Tensor l0_attn_out;
    Tensor l0_out;
    Tensor final_norm;
    Tensor logits;
  };
  [[nodiscard]] Trace forward_trace(std::span<const int> tokens);

 private:
  GPT2Config cfg_;
  ModelFile weights_;

  struct Layer {
    Tensor ln1_w, ln1_b, ln2_w, ln2_b;
    Tensor attn_w, attn_b;    // c_attn: [n_embd, 3*n_embd]
    Tensor attn_proj_w, attn_proj_b;
    Tensor fc_w, fc_b;        // c_fc:   [n_embd, 4*n_embd]
    Tensor proj_w, proj_b;    // c_proj: [4*n_embd, n_embd]
  };
  std::vector<Layer> layers_;
  Tensor wte_, wpe_, lnf_w_, lnf_b_;

  Tensor run_blocks(const Tensor& x, Trace* trace);
};

}  // namespace infer

