#include <algorithm>
#include <cmath>
#include <vector>

#include "infer/kernel.hpp"

namespace infer::kernel {

namespace {

// 一行的 softmax，原地做。减最大值是为了数值稳定 —— 这一课阶段 2 讲过：
// exp(800) 会溢出成 inf，减掉最大值后指数最大是 exp(0)=1，永远安全。
void softmax_inplace(float* s, i64 n) {
  float m = s[0];
  for (i64 i = 1; i < n; ++i) m = std::max(m, s[i]);
  float sum = 0.0F;
  for (i64 i = 0; i < n; ++i) {
    s[i] = std::exp(s[i] - m);
    sum += s[i];
  }
  const float inv = 1.0F / sum;
  for (i64 i = 0; i < n; ++i) s[i] *= inv;
}

}  // namespace

void attention_f32(std::span<const float> q, std::span<const float> k,
                   std::span<const float> v, std::span<float> out,
                   i64 Tq, i64 Tk, i64 n_head, i64 head_size, i64 q_offset) {
  const i64 C = n_head * head_size;
  // 1/√d 这个缩放很关键：点积的方差随维度 d 线性增长，不缩放的话
  // softmax 的输入会越来越大，梯度/概率分布退化成 one-hot。
  const float scale = 1.0F / std::sqrt(static_cast<float>(head_size));

  std::vector<float> scores(static_cast<std::size_t>(Tk));

  for (i64 h = 0; h < n_head; ++h) {
    const i64 hoff = h * head_size;

    for (i64 i = 0; i < Tq; ++i) {
      const float* qi = q.data() + i * C + hoff;
      // 因果掩码：第 i 个查询的绝对位置是 q_offset+i，只能看到到这里为止
      const i64 visible = std::min(q_offset + i + 1, Tk);

      for (i64 j = 0; j < visible; ++j) {
        const float* kj = k.data() + j * C + hoff;
        float dot = 0.0F;
        for (i64 d = 0; d < head_size; ++d) dot += qi[d] * kj[d];
        scores[static_cast<std::size_t>(j)] = dot * scale;
      }

      softmax_inplace(scores.data(), visible);

      // 按注意力权重把 V 加权求和
      float* oi = out.data() + i * C + hoff;
      std::fill(oi, oi + head_size, 0.0F);
      for (i64 j = 0; j < visible; ++j) {
        const float w = scores[static_cast<std::size_t>(j)];
        const float* vj = v.data() + j * C + hoff;
        for (i64 d = 0; d < head_size; ++d) oi[d] += w * vj[d];
      }
    }
  }
}

}  // namespace infer::kernel

