// ---------------------------------------------------------------------------
// 阶段 6：GEMV —— 矩阵 × 向量
//
// 为什么 M=1 要单独写一套？两个原因，第二个更致命。
//
// 【原因一：计算强度完全不同】
//   GEMM (M=N=K=1024)：读 2 M 个 float，做 10 亿次乘加 → 每读一个数算 500 次
//   GEMV (M=1)        ：读 K×N 个 float，做 K×N 次乘加  → 每读一个数算 1 次
//
//   GEMM 是**算力瓶颈**，靠分块把数据留在 cache 里反复用；
//   GEMV 是**带宽瓶颈**，每个权重只用一次，分块毫无意义，
//   能跑多快完全取决于内存能多快把权重送过来。
//
// 【原因二：按行并行会退化成单线程】
//   前面的 parallel_rows 按 C 的行切分。M=1 只有一行，切无可切，
//   14 个核里 13 个在睡觉。GEMV 必须按**输出列 N** 切分。
//   好在 N 总是很大（GPT-2 里是 2304 / 3072 / 50257），切起来绰绰有余。
//
// 这解释了 LLM 推理的一个基本事实：
//   prefill（一次处理整个 prompt，M = 序列长度）走 GEMM，吃算力；
//   decode （每次生成一个词，M = 1）        走 GEMV，吃带宽。
//   两个阶段的优化方向是相反的。
// ---------------------------------------------------------------------------

namespace {
// GEMV 的并行门槛比 GEMM 低得多：GEMV 慢在搬内存，多几个核就多几条访存通道。
// 约 50 万次乘加 ≈ 要读 2 MB 权重，这时候开线程已经稳赚。
constexpr i64 kGemvMinWork = 1 << 19;
}  // namespace

void gemv_f32(std::span<const float> x, std::span<const float> b,
              std::span<float> y, i64 N, i64 K) {
  // y[N] = x[K] × B[K,N]
  // 按输出列分段。每个线程负责 y 的一段连续区间，
  // 段长至少几百个 float，远大于一条 cache line，不用担心 false sharing。
  parallel_range(N, N * K, kGemvMinWork, [&](i64 j_lo, i64 j_hi) {
    const i64 width = j_hi - j_lo;
    if (width <= 0) return;
    float* py = y.data() + j_lo;
    std::fill(py, py + width, 0.0F);

    // 循环顺序是 k 外 j 内：B 沿 j 连续，这样最内层是连续读 + 连续累加，
    // 编译器能直接向量化（等价于手写 AVX2，这里让编译器干）。
    for (i64 k = 0; k < K; ++k) {
      const float xk = x[static_cast<std::size_t>(k)];
      if (xk == 0.0F) continue;
      const float* pb = b.data() + k * N + j_lo;
#if INFER_HAS_AVX2
      const __m256 vx = _mm256_set1_ps(xk);
      i64 j = 0;
      for (; j + 8 <= width; j += 8) {
        _mm256_storeu_ps(py + j,
                         _mm256_fmadd_ps(vx, _mm256_loadu_ps(pb + j),
                                         _mm256_loadu_ps(py + j)));
      }
      for (; j < width; ++j) py[j] += xk * pb[j];
#else
      for (i64 j = 0; j < width; ++j) py[j] += xk * pb[j];
#endif
    }
  });
}

void gemv_nt_f32(std::span<const float> x, std::span<const float> w,
                 std::span<float> y, i64 N, i64 K) {
  // y[N] = W[N,K] × x[K]，每个输出就是 W 的一行和 x 的点积。
  // 这个布局对 GEMV 更友好：两个操作数都沿 k 连续读。
  parallel_range(N, N * K, kGemvMinWork, [&](i64 j_lo, i64 j_hi) {
    for (i64 j = j_lo; j < j_hi; ++j) {
      const float* pw = w.data() + j * K;
#if INFER_HAS_AVX2
      // 4 个独立累加器。FMA 有约 4 周期延迟但每周期能发射一条，
      // 单个累加器会被延迟卡住，4 个才能把流水线填满。
      __m256 a0 = _mm256_setzero_ps(), a1 = _mm256_setzero_ps();
      __m256 a2 = _mm256_setzero_ps(), a3 = _mm256_setzero_ps();
      i64 k = 0;
      for (; k + 32 <= K; k += 32) {
        a0 = _mm256_fmadd_ps(_mm256_loadu_ps(x.data() + k + 0),
                             _mm256_loadu_ps(pw + k + 0), a0);
        a1 = _mm256_fmadd_ps(_mm256_loadu_ps(x.data() + k + 8),
                             _mm256_loadu_ps(pw + k + 8), a1);
        a2 = _mm256_fmadd_ps(_mm256_loadu_ps(x.data() + k + 16),
                             _mm256_loadu_ps(pw + k + 16), a2);
        a3 = _mm256_fmadd_ps(_mm256_loadu_ps(x.data() + k + 24),
                             _mm256_loadu_ps(pw + k + 24), a3);
      }
      for (; k + 8 <= K; k += 8) {
        a0 = _mm256_fmadd_ps(_mm256_loadu_ps(x.data() + k),
                             _mm256_loadu_ps(pw + k), a0);
      }
      float sum = hsum256(_mm256_add_ps(_mm256_add_ps(a0, a1),
                                        _mm256_add_ps(a2, a3)));
      for (; k < K; ++k) sum += x[static_cast<std::size_t>(k)] * pw[k];
#else
      float sum = 0.0F;
      for (i64 k = 0; k < K; ++k) sum += x[static_cast<std::size_t>(k)] * pw[k];
#endif
      y[static_cast<std::size_t>(j)] = sum;
    }
  });
}

}  // namespace infer::kernel

// --- 阶段 6：GEMV（矩阵 × 向量）----------------------------------------------
// 就是 M == 1 的 matmul，但必须单独优化，因为它和 GEMM 的瓶颈完全不同：
// GEMM 缺算力（靠分块复用 cache），GEMV 缺带宽（每个权重只用一次）。
// 而且按行并行在 M=1 时会退化成单线程，必须改成按输出列并行。
//
// LLM 逐词生成时全程走这条路，所以它直接决定「每秒能吐几个字」。
//
// y[N] = x[K] × B[K,N]
void gemv_f32(std::span<const float> x, std::span<const float> b,
              std::span<float> y, i64 N, i64 K);
// y[N] = W[N,K] × x[K]
void gemv_nt_f32(std::span<const float> x, std::span<const float> w,
                 std::span<float> y, i64 N, i64 K);

