#pragma once

#include <cstdint>
#include <functional>

namespace infer {

using i64 = std::int64_t;

// ---------------------------------------------------------------------------
// 常驻线程池
//
// 阶段 5 的多线程 matmul 是「用的时候现建 jthread，用完 join」。
// 那时候没问题：一次矩阵乘要跑几十毫秒，0.6 ms 的建线程开销只占 1%。
//
// 到了阶段 6 的逐词生成，这个做法直接崩了：
//
//   每生成 1 个词 = 49 次矩阵-向量乘
//   每次都建 14 个线程 = 686 次线程创建/销毁
//   ≈ 60 ms 纯开销，而这个词本身只需要 38 ms
//
//   实测（14 核）：1 线程 26 token/s，14 线程 10 token/s —— 越并行越慢。
//
// 解决办法是把线程**留住**：启动时建好，之后反复复用，只传递任务。
//
//   现建现用:  [建线程][干活][销毁]  [建线程][干活][销毁]  ...
//   线程池  :  [建线程] [干活][干活][干活][干活] ... [销毁]
//              └ 只有一次 ┘
//
// 同步策略是先自旋后睡眠：任务来得密集时靠自旋抢延迟（微秒级唤醒），
// 空闲下来就睡觉，不白烧 CPU。llama.cpp、OpenMP 用的都是这个套路。
// ---------------------------------------------------------------------------
class ThreadPool {
 public:
  // 取全局线程池。n 变化时会重建。
  static ThreadPool& instance(int n);

  [[nodiscard]] int size() const noexcept { return n_threads_; }

  // 把 [0, total) 切成 size() 段并行跑，全部做完才返回。
  // fn 会被不同线程以不同的 [lo, hi) 调用，区间之间互不重叠。
  void parallel_for(i64 total, const std::function<void(i64, i64)>& fn);

  ThreadPool(const ThreadPool&) = delete;
  ThreadPool& operator=(const ThreadPool&) = delete;

  ~ThreadPool();

 private:
  explicit ThreadPool(int n);

  struct Impl;
  Impl* impl_;
  int n_threads_;
};

}  // namespace infer

#include "infer/thread_pool.hpp"

#include <algorithm>
#include <atomic>
#include <condition_variable>
#include <memory>
#include <mutex>
#include <thread>
#include <vector>

#if defined(__x86_64__) || defined(_M_X64)
#include <immintrin.h>
#define INFER_PAUSE() _mm_pause()
#else
#define INFER_PAUSE() std::this_thread::yield()
#endif

namespace infer {

namespace {
// 自旋多少次之后改为睡眠等待。
// 太小：任务密集时频繁进内核睡/醒，每次十几微秒，白白浪费。
// 太大：空闲时一直空转，把 CPU 烧满。
// 几千次 pause 大约几十微秒，正好盖住一次 GEMV 的间隔。
constexpr int kSpinRounds = 4000;
}  // namespace

struct ThreadPool::Impl {
  std::vector<std::jthread> workers;
  std::vector<std::pair<i64, i64>> ranges;

  const std::function<void(i64, i64)>* job = nullptr;

  // epoch 每提交一批任务就加 1。worker 靠「epoch 变了没」判断有没有新活，
  // 比维护一个任务队列简单得多，也没有内存分配。
  std::atomic<std::uint64_t> epoch{0};
  std::atomic<int> remaining{0};
  std::atomic<bool> stopping{false};

  std::mutex mu;
  std::condition_variable cv;       // worker 睡在这里等新任务
  std::condition_variable done_cv;  // 主线程睡在这里等任务做完

  void wake_all() {
    {
      const std::lock_guard lk(mu);
    }
    cv.notify_all();
  }

  // 先自旋、后睡眠地等某个条件成立
  template <class Pred>
  void wait_for(std::condition_variable& which, Pred pred) {
    for (int i = 0; i < kSpinRounds; ++i) {
      if (pred()) return;
      INFER_PAUSE();
    }
    std::unique_lock lk(mu);
    which.wait(lk, pred);
  }
};

ThreadPool::ThreadPool(int n) : impl_(new Impl), n_threads_(std::max(n, 1)) {
  impl_->ranges.resize(static_cast<std::size_t>(n_threads_), {0, 0});

  // worker 0 是主线程自己，所以只开 n-1 个后台线程
  for (int t = 1; t < n_threads_; ++t) {
    impl_->workers.emplace_back([this, t] {
      Impl& s = *impl_;
      std::uint64_t seen = 0;
      while (true) {
        s.wait_for(s.cv, [&] {
          return s.stopping.load(std::memory_order_acquire) ||
                 s.epoch.load(std::memory_order_acquire) != seen;
        });
        if (s.stopping.load(std::memory_order_acquire)) return;
        seen = s.epoch.load(std::memory_order_acquire);

        const auto [lo, hi] = s.ranges[static_cast<std::size_t>(t)];
        if (lo < hi) (*s.job)(lo, hi);

        // 最后一个干完的负责叫醒主线程
        if (s.remaining.fetch_sub(1, std::memory_order_acq_rel) == 1) {
          const std::lock_guard lk(s.mu);
          s.done_cv.notify_one();
        }
      }
    });
  }
}

ThreadPool::~ThreadPool() {
  impl_->stopping.store(true, std::memory_order_release);
  impl_->wake_all();
  impl_->workers.clear();  // jthread 析构自动 join
  delete impl_;
}

void ThreadPool::parallel_for(i64 total, const std::function<void(i64, i64)>& fn) {
  if (total <= 0) return;
  if (n_threads_ <= 1 || total < 2) {
    fn(0, total);
    return;
  }

  Impl& s = *impl_;
  const auto chunks = static_cast<int>(std::min<i64>(n_threads_, total));
  const i64 per = (total + chunks - 1) / chunks;
  for (int t = 0; t < n_threads_; ++t) {
    const i64 lo = std::min(static_cast<i64>(t) * per, total);
    const i64 hi = std::min(lo + per, total);
