// 轻量的「函数引用」。
//
// 为什么不用 std::function？因为它可能在堆上分配。逐词生成时每秒要提交
// 几千次任务，每次一个 malloc 是实打实的浪费。TaskRef 只存一个对象指针
// 和一个静态函数指针，永远不分配 —— 代价是它不持有对象，
// 调用期间原 lambda 必须还活着（我们的用法里它就在栈上，没问题）。
class TaskRef {
 public:
  template <class F>
    requires(!std::is_same_v<std::decay_t<F>, TaskRef>)
  TaskRef(F&& f)  // NOLINT(google-explicit-constructor) 故意允许隐式转换
      : obj_(const_cast<void*>(static_cast<const void*>(&f))),
        call_([](void* p, i64 lo, i64 hi) {
          (*static_cast<std::remove_reference_t<F>*>(p))(lo, hi);
        }) {}

  void operator()(i64 lo, i64 hi) const { call_(obj_, lo, hi); }

 private:
  void* obj_;
  void (*call_)(void*, i64, i64);
};

