#include "infer/thread_pool.hpp"

#include <algorithm>
#include <atomic>
#include <condition_variable>
#include <memory>
#include <mutex>
#include <thread>
#include <vector>

#if defined(__x86_64__) || defined(_M_X64)
#include <immintrin.h>
#define INFER_PAUSE() _mm_pause()
#else
#define INFER_PAUSE() std::this_thread::yield()
#endif

namespace infer {

namespace {
// 自旋多少轮之后改为睡眠等待。
//
// 这个值有两面：
//   太小 —— 任务密集时频繁进出内核，每次唤醒十几微秒，白白浪费；
//   太大 —— 空闲的 worker 一直空转，不但烧电，在超线程 CPU 上还会
//            抢走兄弟逻辑核的执行资源，把主线程的串行部分拖慢。
// 第二点很容易被忽略，却正是「线程越多越慢」的一个隐藏原因。
constexpr int kSpinRounds = 1500;
}  // namespace

struct ThreadPool::Impl {
  std::vector<std::jthread> workers;
  std::vector<std::pair<i64, i64>> ranges;

  alignas(64) std::atomic<std::uint64_t> epoch{0};
  alignas(64) std::atomic<int> remaining{0};
  // 有几个 worker 真的睡着了。全在自旋时就不用去碰 mutex 和 notify，
  // 这条快路径省掉了每次提交任务的锁开销。
  alignas(64) std::atomic<int> sleepers{0};
  std::atomic<bool> stopping{false};

  const TaskRef* job = nullptr;

  std::mutex mu;
  std::condition_variable cv;
  std::condition_variable done_cv;
  bool main_waiting = false;

  void submit_wake() {
    if (sleepers.load(std::memory_order_acquire) > 0) {
      const std::lock_guard lk(mu);
      cv.notify_all();
    }
  }
};

ThreadPool::ThreadPool(int n) : impl_(new Impl), n_threads_(std::max(n, 1)) {
  impl_->ranges.resize(static_cast<std::size_t>(n_threads_), {0, 0});

  // worker 0 就是主线程自己，所以只开 n-1 个后台线程
  for (int t = 1; t < n_threads_; ++t) {
    impl_->workers.emplace_back([this, t] {
      Impl& s = *impl_;
      std::uint64_t seen = 0;
      const auto has_work = [&] {
        return s.stopping.load(std::memory_order_acquire) ||
               s.epoch.load(std::memory_order_acquire) != seen;
      };

      while (true) {
        // 先自旋。任务来得密集时，绝大多数情况在这里就命中了，
        // 一次 mutex 都不用碰。
        bool got = false;
        for (int i = 0; i < kSpinRounds; ++i) {
          if (has_work()) { got = true; break; }
          INFER_PAUSE();
        }
        if (!got) {
          // 自旋没等到，说明这会儿闲着，去睡
          std::unique_lock lk(s.mu);
          s.sleepers.fetch_add(1, std::memory_order_release);
          s.cv.wait(lk, has_work);
          s.sleepers.fetch_sub(1, std::memory_order_release);
        }
        if (s.stopping.load(std::memory_order_acquire)) return;
        seen = s.epoch.load(std::memory_order_acquire);

        const auto [lo, hi] = s.ranges[static_cast<std::size_t>(t)];
        if (lo < hi) (*s.job)(lo, hi);

        if (s.remaining.fetch_sub(1, std::memory_order_acq_rel) == 1) {
          // 自己是最后一个干完的。只有主线程真的睡着了才需要叫它。
          const std::lock_guard lk(s.mu);
          if (s.main_waiting) s.done_cv.notify_one();
        }
      }
    });
  }
}

ThreadPool::~ThreadPool() {
  {
    const std::lock_guard lk(impl_->mu);
    impl_->stopping.store(true, std::memory_order_release);
  }
  impl_->cv.notify_all();
  impl_->workers.clear();  // jthread 析构自动 join
  delete impl_;
}

void ThreadPool::parallel_for(i64 total, TaskRef fn) {
  if (total <= 0) return;
  if (n_threads_ <= 1 || total < 2) {
    fn(0, total);
    return;
  }

  Impl& s = *impl_;
  const auto chunks = static_cast<int>(std::min<i64>(n_threads_, total));
  const i64 per = (total + chunks - 1) / chunks;
  for (int t = 0; t < n_threads_; ++t) {
    const i64 lo = std::min(static_cast<i64>(t) * per, total);
    s.ranges[static_cast<std::size_t>(t)] = {lo, t < chunks ? std::min(lo + per, total) : lo};
  }

  s.job = &fn;
  // 顺序要紧：remaining 必须在 epoch 之前设好，否则 worker 可能先看到
  // 新 epoch、干完活，去减一个还没写入的计数。
  s.remaining.store(n_threads_ - 1, std::memory_order_release);
  s.epoch.fetch_add(1, std::memory_order_acq_rel);
  s.submit_wake();

  const auto [lo, hi] = s.ranges[0];
  if (lo < hi) fn(lo, hi);  // 主线程也干一份，不干等着

  // 等其他人干完，同样是先自旋后睡眠
  for (int i = 0; i < kSpinRounds; ++i) {
    if (s.remaining.load(std::memory_order_acquire) == 0) { s.job = nullptr; return; }
    INFER_PAUSE();
  }
  {
    std::unique_lock lk(s.mu);
    s.main_waiting = true;
    s.done_cv.wait(lk, [&] { return s.remaining.load(std::memory_order_acquire) == 0; });
    s.main_waiting = false;
  }
  s.job = nullptr;
}

ThreadPool& ThreadPool::instance(int n) {
  // 线程数变了就重建。实际使用中只会在启动时设一次。
  static std::unique_ptr<ThreadPool> pool;
  static std::mutex mu;
  const std::lock_guard lk(mu);
  if (!pool || pool->size() != std::max(n, 1)) {
    pool.reset(new ThreadPool(n));  // NOLINT(modernize-make-unique) 构造函数私有
  }
  return *pool;
}

