// 「有几个核就用几个核」是错的。跨核同步有固定的物理成本：
// 缓存一致性流量、线程唤醒、甚至能效核从低功耗状态爬出来。
// 本机实测这个成本在 1 ms 量级，而 GPT-2 里一个 768×768 的
// 矩阵-向量乘本身只要 0.2 ms —— 叫人来帮忙，比自己干还慢。
//
// 所以按工作量分配：活儿够多才值得多叫人。
[[nodiscard]] static int threads_for(i64 work, int available) noexcept;

constexpr i64 kChunksPerThread = 4;

// 一个线程至少要分到这么多工作量（乘加次数）才值得叫上它。
//
// 这个数是**实测反推**的，不是拍脑袋：
//   本机单线程 GEMV 约 10 GB/s，也就是每秒处理 2.5G 个 f32 权重。
//   一次跨核同步的成本约 1 ms，对应 250 万个权重的处理时间。
//   留一倍余量 → 约 400 万。
//
// 换台机器（尤其是全大核的服务器 CPU）这个值会小很多。
// 不要照抄，跑一遍 examples/06_gpt2 的线程扫描，按自己的数据定。
constexpr i64 kMinWorkPerThread = 1 << 22;  // 约 419 万
}  // namespace

int ThreadPool::threads_for(i64 work, int available) noexcept {
  if (available <= 1) return 1;
  const i64 k = work / kMinWorkPerThread;
  return static_cast<int>(std::clamp<i64>(k, 1, available));
}

