void ThreadPool::parallel_for(i64 total, int max_threads, TaskRef fn) {
  if (total <= 0) return;
  const int use = std::clamp(max_threads, 1, n_threads_);
  if (use <= 1 || total < 2) {
    fn(0, total);  // 完全不碰线程池，同步开销为零
    return;
  }

  Impl& s = *impl_;
  // 块数按**实际要用的**线程数算。多余的 worker 抢不到块，
  // 一次 fetch_add 就退出了。
  const i64 want = static_cast<i64>(use) * kChunksPerThread;

