void parallel_range(i64 total, i64 work, i64 min_work, F&& fn) {
  const int nt = get_num_threads();
  if (nt <= 1 || work < min_work || total < 2) {
    fn(i64{0}, total);
    return;
  }
  // 不是「有几个核用几个核」，而是按工作量决定叫几个人来。
  // 原因见 thread_pool.hpp 里 threads_for 的注释。
  ThreadPool& pool = ThreadPool::instance(nt);
