// 阶段 6 的测试：分词器、注意力、GEMV、KV-Cache、端到端对拍。
//
// 需要先跑 tools/convert_gpt2.py 生成模型文件。
// 文件不在时相关用例会自动跳过，不会让整个测试套变红。

#include <cmath>
#include <filesystem>
#include <numeric>
#include <random>

#include "infer/gpt2.hpp"
#include "infer/kernel.hpp"
#include "infer/model_file.hpp"
#include "infer/ops.hpp"
#include "infer/thread_pool.hpp"
#include "infer/tokenizer.hpp"
#include "minitest.hpp"

using infer::GPT2;
using infer::KVCache;
using infer::Sampler;
using infer::SamplerConfig;
using infer::Tensor;
using infer::ThreadPool;
using infer::Tokenizer;
namespace ops = infer::ops;
namespace kernel = infer::kernel;

namespace {

std::string model_dir() { return INFER_MODEL_DIR; }

bool has_model() {
  return std::filesystem::exists(model_dir() + "/gpt2.infer") &&
         std::filesystem::exists(model_dir() + "/gpt2_vocab.bin");
}

Tensor random_tensor(std::initializer_list<infer::i64> shape, unsigned seed) {
  Tensor t = Tensor::zeros(shape);
  std::mt19937 rng(seed);
  std::normal_distribution<float> dist(0.0F, 1.0F);
  for (float& v : t.data()) v = dist(rng);
  return t;
}

}  // namespace

// ---------------------------------------------------------------------------
// GEMV：M==1 时走的是另一条代码路径，必须单独对拍
// ---------------------------------------------------------------------------

TEST(gemv_matches_general_matmul) {
  // 特意取非 8 倍数的尺寸，把 SIMD 的边角处理逼出来
  for (auto [N, K] : {std::pair{1, 1}, {7, 5}, {64, 64}, {130, 99}, {2304, 768}}) {
    const Tensor x = random_tensor({1, K}, 1);
    const Tensor b = random_tensor({K, N}, 2);

    Tensor want = Tensor::zeros({1, N});
    kernel::matmul_f32_ijk(x.data(), b.data(), want.data(), 1, N, K);
    Tensor got = Tensor::zeros({1, N});
    kernel::gemv_f32(x.data(), b.data(), got.data(), N, K);

    CHECK_NEAR(ops::max_abs_diff(want, got), 0.0F, 2e-4F);
  }
}

TEST(gemv_nt_matches_general_matmul) {
  for (auto [N, K] : {std::pair{1, 1}, {3, 7}, {64, 64}, {130, 99}, {50257, 768}}) {
    const Tensor x = random_tensor({1, K}, 3);
    const Tensor w = random_tensor({N, K}, 4);

    Tensor want = Tensor::zeros({1, N});
    kernel::matmul_nt_f32_naive(x.data(), w.data(), want.data(), 1, N, K);
    Tensor got = Tensor::zeros({1, N});
    kernel::gemv_nt_f32(x.data(), w.data(), got.data(), N, K);

    CHECK_NEAR(ops::max_abs_diff(want, got), 0.0F, 2e-3F);
  }
}

TEST(matmul_dispatches_to_gemv_transparently) {
  // matmul_f32 在 M==1 时会偷偷改走 gemv，结果必须完全一致
  const infer::i64 N = 512, K = 300;
  const Tensor x = random_tensor({1, K}, 5);
  const Tensor b = random_tensor({K, N}, 6);
  Tensor want = Tensor::zeros({1, N});
  Tensor got = Tensor::zeros({1, N});
  kernel::matmul_f32_ijk(x.data(), b.data(), want.data(), 1, N, K);
  kernel::matmul_f32(x.data(), b.data(), got.data(), 1, N, K);
  CHECK_NEAR(ops::max_abs_diff(want, got), 0.0F, 2e-4F);
}

TEST(gemv_result_independent_of_thread_count) {
  const infer::i64 N = 4096, K = 768;  // 够大，一定会走并行
  const Tensor x = random_tensor({1, K}, 7);
  const Tensor w = random_tensor({N, K}, 8);

  const int saved = kernel::get_num_threads();
  kernel::set_num_threads(1);
  Tensor a = Tensor::zeros({1, N});
  kernel::gemv_nt_f32(x.data(), w.data(), a.data(), N, K);

  for (int nt : {2, 3, 8, 16}) {
    kernel::set_num_threads(nt);
    Tensor b = Tensor::zeros({1, N});
    kernel::gemv_nt_f32(x.data(), w.data(), b.data(), N, K);
    // 并行只改变分工，不改变每个输出的算法，结果应当逐位相同
    CHECK(ops::max_abs_diff(a, b) == 0.0F);
  }
  kernel::set_num_threads(saved);
}

// ---------------------------------------------------------------------------
// 线程池
// ---------------------------------------------------------------------------

TEST(thread_pool_covers_every_index_exactly_once) {
  ThreadPool& pool = ThreadPool::instance(8);
  for (infer::i64 total : {1, 2, 7, 100, 1000}) {
    std::vector<std::atomic<int>> hits(static_cast<std::size_t>(total));
    pool.parallel_for(total, 8, [&](infer::i64 lo, infer::i64 hi) {
      for (infer::i64 i = lo; i < hi; ++i) {
        hits[static_cast<std::size_t>(i)].fetch_add(1);
      }
    });
    for (const auto& h : hits) CHECK(h.load() == 1);
  }
}

TEST(thread_pool_reuses_threads_across_many_submits) {
  // 逐词生成时每秒要提交几千次任务，反复提交必须稳定
  ThreadPool& pool = ThreadPool::instance(4);
  std::atomic<std::int64_t> sum{0};
  for (int round = 0; round < 500; ++round) {
    pool.parallel_for(100, 4, [&](infer::i64 lo, infer::i64 hi) {
      std::int64_t local = 0;
      for (infer::i64 i = lo; i < hi; ++i) local += i;
      sum.fetch_add(local);
    });
  }
  CHECK(sum.load() == 500LL * (99 * 100 / 2));
}

TEST(threads_for_scales_with_work_not_core_count) {
  // 小活儿不叫人
  CHECK(ThreadPool::threads_for(1000, 16) == 1);
  // 大活儿叫满
  CHECK(ThreadPool::threads_for(1LL << 40, 16) == 16);
  // 只有一个核时永远是 1
  CHECK(ThreadPool::threads_for(1LL << 40, 1) == 1);
  // 中间档位单调不减
  int prev = 0;
  for (int p = 20; p < 34; ++p) {
    const int n = ThreadPool::threads_for(1LL << p, 16);
    CHECK(n >= prev);
    prev = n;
  }
}

// ---------------------------------------------------------------------------
// 注意力
// ---------------------------------------------------------------------------

TEST(attention_causal_mask_hides_the_future) {
  // 改掉最后一个位置的 K/V，第 0 个位置的输出不该有任何变化 ——
  // 因为因果掩码不让它看到后面。这个性质错了，模型训练时就能偷看答案。
  const int T = 4, H = 2, HS = 3, C = H * HS;
  const Tensor q = random_tensor({T, C}, 11);
  Tensor k = random_tensor({T, C}, 12);
  Tensor v = random_tensor({T, C}, 13);

  const Tensor before = ops::attention(q, k, v, H);
  for (infer::i64 j = 0; j < C; ++j) {
    k.data()[static_cast<std::size_t>((T - 1) * C + j)] += 100.0F;
    v.data()[static_cast<std::size_t>((T - 1) * C + j)] += 100.0F;
  }
  const Tensor after = ops::attention(q, k, v, H);

  for (infer::i64 j = 0; j < C; ++j) {
    CHECK_NEAR(before.data()[static_cast<std::size_t>(j)],
               after.data()[static_cast<std::size_t>(j)], 1e-6F);
  }
  // 而最后一个位置必须变
  CHECK(std::fabs(before.data()[static_cast<std::size_t>((T - 1) * C)] -
                  after.data()[static_cast<std::size_t>((T - 1) * C)]) > 1e-3F);
}

TEST(attention_first_position_just_copies_v) {
  // 第 0 个位置只能看到自己，softmax 后权重必然是 1，输出就等于 v[0]
  const int T = 3, H = 2, HS = 4, C = H * HS;
  const Tensor q = random_tensor({T, C}, 14);
  const Tensor k = random_tensor({T, C}, 15);
  const Tensor v = random_tensor({T, C}, 16);
  const Tensor out = ops::attention(q, k, v, H);
  for (infer::i64 j = 0; j < C; ++j) {
    CHECK_NEAR(out.data()[static_cast<std::size_t>(j)],
               v.data()[static_cast<std::size_t>(j)], 1e-6F);
  }
}

TEST(attention_heads_do_not_mix) {
  // 把第 1 个头的输入全部改掉，第 0 个头的输出不该动。
  // 多头注意力的每个头是完全独立的，写错下标很容易让它们串味。
  const int T = 3, H = 2, HS = 4, C = H * HS;
  const Tensor q = random_tensor({T, C}, 17);
  Tensor k = random_tensor({T, C}, 18);
  const Tensor v = random_tensor({T, C}, 19);
  const Tensor before = ops::attention(q, k, v, H);
  for (infer::i64 t = 0; t < T; ++t) {
    for (infer::i64 j = HS; j < C; ++j) {
      k.data()[static_cast<std::size_t>(t * C + j)] *= 5.0F;
    }
  }
  const Tensor after = ops::attention(q, k, v, H);
  for (infer::i64 t = 0; t < T; ++t) {
    for (infer::i64 j = 0; j < HS; ++j) {  // 只看第 0 个头
      CHECK_NEAR(before.data()[static_cast<std::size_t>(t * C + j)],
                 after.data()[static_cast<std::size_t>(t * C + j)], 1e-6F);
    }
  }
}

TEST(attention_rejects_bad_head_count) {
  const Tensor q = random_tensor({2, 6}, 20);
  CHECK_THROWS(ops::attention(q, q, q, 4));  // 6 不能被 4 整除
}

// ---------------------------------------------------------------------------
// 采样
// ---------------------------------------------------------------------------

TEST(sampler_temperature_zero_is_greedy) {
  const std::vector<float> logits = {0.1F, 5.0F, 0.2F, 4.9F};
  Sampler s{SamplerConfig{.temperature = 0.0F}};
  for (int i = 0; i < 20; ++i) CHECK(s.sample(logits) == 1);
}

TEST(sampler_top_k_never_picks_outside_top_k) {
  std::vector<float> logits(100, 0.0F);
  logits[7] = 10.0F;
  logits[42] = 9.0F;
  Sampler s{SamplerConfig{.temperature = 1.0F, .top_k = 2}};
  for (int i = 0; i < 200; ++i) {
    const int id = s.sample(logits);
    CHECK(id == 7 || id == 42);
  }
}

TEST(sampler_is_reproducible_with_same_seed) {
  std::vector<float> logits(50);
  std::iota(logits.begin(), logits.end(), 0.0F);
  auto run = [&] {
    Sampler s{SamplerConfig{.temperature = 1.0F, .seed = 12345}};
    std::vector<int> out;
    for (int i = 0; i < 30; ++i) out.push_back(s.sample(logits));
    return out;
  };
  CHECK(run() == run());
}

// ---------------------------------------------------------------------------
// 分词器
// ---------------------------------------------------------------------------

TEST(pre_tokenize_keeps_space_with_following_word) {
  // GPT-2 的切分规则里，空格是跟在**后一个词前面**的
  const auto p = Tokenizer::pre_tokenize("The capital of");
  CHECK(p.size() == 3);
  CHECK(p[0] == "The");
  CHECK(p[1] == " capital");
  CHECK(p[2] == " of");
}

TEST(pre_tokenize_splits_contractions) {
  const auto p = Tokenizer::pre_tokenize("don't");
  CHECK(p.size() == 2);
  CHECK(p[0] == "don");
  CHECK(p[1] == "'t");
}

TEST(pre_tokenize_handles_runs_of_spaces) {
  // 连续空白里，最后一个要让给后面的词当前导空格
  const auto p = Tokenizer::pre_tokenize("a   b");
  CHECK(p.size() == 3);
  CHECK(p[0] == "a");
  CHECK(p[1] == "  ");
  CHECK(p[2] == " b");
}

TEST(pre_tokenize_never_loses_characters) {
  // 不管怎么切，拼回去必须和原文一模一样
  for (std::string_view text : {"Hello, world!", "  leading", "trailing  ",
                                "a1b2  c3!!", "\n\nnewlines\n", "emoji 你好 ok",
                                "", " ", "'tis"}) {
    std::string joined;
    for (const auto& c : Tokenizer::pre_tokenize(text)) joined += c;
    CHECK(joined == text);
  }
}

TEST(tokenizer_roundtrip) {
  if (!has_model()) { SKIP("需要先跑 tools/convert_gpt2.py"); }
  const Tokenizer tok =
      Tokenizer::load(model_dir() + "/gpt2_vocab.bin", model_dir() + "/gpt2_merges.bin");
  CHECK(tok.vocab_size() == 50257);
  for (std::string_view text : {"The capital of France is", "Hello, world!",
                                "  spaces   everywhere  ", "don't stop",
                                "1, 2, 3, 4, 5,", "print(\"hi\")\n"}) {
    CHECK(tok.decode(tok.encode(text)) == text);
  }
}

TEST(tokenizer_matches_known_gpt2_ids) {
  if (!has_model()) { SKIP("需要先跑 tools/convert_gpt2.py"); }
  const Tokenizer tok =
      Tokenizer::load(model_dir() + "/gpt2_vocab.bin", model_dir() + "/gpt2_merges.bin");
  // 这些 id 是 GPT-2 官方分词器的输出，写死在这里当回归基准
  const std::vector<int> want = {464, 3139, 286, 4881, 318};
  CHECK(tok.encode("The capital of France is") == want);
  CHECK(tok.encode(" Paris") == std::vector<int>{6342});
  CHECK(tok.encode("Hello") == std::vector<int>{15496});
}

// ---------------------------------------------------------------------------
// 端到端
// ---------------------------------------------------------------------------

TEST(gpt2_matches_numpy_reference_layer_by_layer) {
  if (!has_model()) { SKIP("需要先跑 tools/convert_gpt2.py"); }
  const infer::ModelFile ref =
      infer::ModelFile::load(model_dir() + "/gpt2_reference.infer");
  GPT2 model = GPT2::load(model_dir());

  std::vector<int> tokens;
  for (float f : ref.get("tokens").data()) tokens.push_back(static_cast<int>(f));

  const GPT2::Trace tr = model.forward_trace(tokens);
  CHECK_NEAR(ops::max_abs_diff(tr.embed, ref.get("embed")), 0.0F, 1e-6F);
  CHECK_NEAR(ops::max_abs_diff(tr.l0_attn_out, ref.get("l0_attn_out")), 0.0F, 1e-4F);
  CHECK_NEAR(ops::max_abs_diff(tr.l0_out, ref.get("l0_out")), 0.0F, 1e-3F);
  CHECK_NEAR(ops::max_abs_diff(tr.final_norm, ref.get("final_norm")), 0.0F, 5e-3F);
  CHECK_NEAR(ops::max_abs_diff(tr.logits, ref.get("logits")), 0.0F, 5e-2F);
}

TEST(gpt2_kv_cache_matches_full_recompute) {
  if (!has_model()) { SKIP("需要先跑 tools/convert_gpt2.py"); }
  GPT2 model = GPT2::load(model_dir());
  const std::vector<int> tokens = {464, 3139, 286, 4881, 318};

  // 路线 A：一次算完整个序列
  const Tensor full = model.forward(tokens);
  const Tensor want = full.slice(0, full.dim(0) - 1, full.dim(0)).contiguous();

  // 路线 B：一个一个喂，用 KV-Cache
  KVCache cache(model.config(), 16);
  Tensor got;
  for (std::size_t i = 0; i < tokens.size(); ++i) {
    got = model.forward_one(tokens[i], static_cast<int>(i), cache);
  }
  CHECK(cache.length() == static_cast<int>(tokens.size()));

  // 两条路线数学上等价，只有浮点累加顺序不同
  CHECK_NEAR(ops::max_abs_diff(want.reshape({model.config().n_vocab}), got), 0.0F, 2e-2F);
  // 更关键的是 argmax 必须一致，否则生成的文本会分叉
  CHECK(ops::argmax(want) == ops::argmax(got));
}

TEST(gpt2_prefill_then_decode_matches_token_by_token) {
  if (!has_model()) { SKIP("需要先跑 tools/convert_gpt2.py"); }
  GPT2 model = GPT2::load(model_dir());
  const std::vector<int> prompt = {464, 3139, 286, 4881, 318};

  // generate() 走的是「prompt 一次 prefill，之后逐词 decode」
  Sampler greedy{SamplerConfig{.temperature = 0.0F}};
  const std::vector<int> out = model.generate(prompt, 4, greedy);
  CHECK(out.size() == prompt.size() + 4);

  // 逐个 token 喂，应该得到一模一样的结果
  KVCache cache(model.config(), 32);
  std::vector<int> step;
  Tensor logits;
  for (std::size_t i = 0; i < prompt.size(); ++i) {
    step.push_back(prompt[i]);
    logits = model.forward_one(prompt[i], static_cast<int>(i), cache);
  }
  for (int i = 0; i < 4; ++i) {
    const auto next = static_cast<int>(ops::argmax(logits));
    step.push_back(next);
    logits = model.forward_one(next, static_cast<int>(step.size()) - 1, cache);
  }
  CHECK(step == out);
}

TEST(gpt2_counts_to_six) {
  if (!has_model()) { SKIP("需要先跑 tools/convert_gpt2.py"); }
  // 验收判据要选模型**一定**答得对的题。
  // "The capital of France is" -> " Paris" 看着很诱人，但 GPT-2 small
  // 只有 124M 参数，它更爱接万能的 " the"，Paris 只排第 5。
  // 用这个判据会让你以为代码有 bug，然后浪费一整天去找根本不存在的问题。
  //
  // 数数就不一样了：这是纯语法模式，小模型也稳稳能答对。
  GPT2 model = GPT2::load(model_dir());
  const std::vector<int> tokens = {16, 11, 362, 11, 513, 11, 604, 11, 642, 11};
  const Tensor logits = model.forward(tokens);
  const Tensor last = logits.slice(0, logits.dim(0) - 1, logits.dim(0)).contiguous();
  CHECK(ops::argmax(last) == 718);  // " 6"
}

TEST(gpt2_rejects_context_overflow) {
  if (!has_model()) { SKIP("需要先跑 tools/convert_gpt2.py"); }
  GPT2 model = GPT2::load(model_dir());
  const std::vector<int> too_long(model.config().n_ctx + 1, 464);
  CHECK_THROWS(model.forward(too_long));
}

