struct Failure : std::exception {
  std::string msg;
  explicit Failure(std::string m) : msg(std::move(m)) {}
  [[nodiscard]] const char* what() const noexcept override { return msg.c_str(); }
};

// 依赖外部数据（模型权重等）的用例，数据不在时跳过。
// 单独用一个异常类型，是为了让跳过**显示出来** —— 静默通过的测试
// 最危险：你以为它在保护你，其实它从来没运行过。
struct Skipped : std::exception {
  std::string msg;
  explicit Skipped(std::string m) : msg(std::move(m)) {}
  [[nodiscard]] const char* what() const noexcept override { return msg.c_str(); }
};

inline int run_all() {
