#pragma once

#include <cstdint>
#include <span>
#include <string>

#include "infer/tensor.hpp"

namespace infer {

// ---------------------------------------------------------------------------
// INT8 量化
//
// 阶段 6 的结论是：逐词生成（decode）卡在**内存带宽**上 ——
// 每生成一个词都要把 500 MB 权重完整读一遍。
//
// 那就让权重变小。f32 换成 int8，每个数从 4 字节降到 1 字节：
//
//     f32 权重              量化                 int8 + scale
//     ┌──────────┐                             ┌──────┐
//     │  0.0123  │  找出这一组的最大绝对值        │  12  │
//     │ -0.0456  │  scale = absmax / 127   →   │ -47  │  + 一个 f32 scale
//     │  0.0891  │  q = round(x / scale)       │  92  │
//     │   ...    │                             │ ...  │
//     └──────────┘                             └──────┘
//      每个 4 字节                               每个 1 字节
//
// 有一件事一定要说清楚，因为很容易误解：
//
//     **量化在这里的收益来自带宽，不是算力。**
//
// 我们的实现把 int8 读进来后**转成 float 再算**，乘加次数一分没少。
// 快是因为要搬的字节少了 3/4。真正用整数指令算（int8 点积）需要把激活
// 也量化，误差更大、代码更复杂，收益在带宽瓶颈的场景下反而不明显。
// 这个取舍叫 W8A32：权重 8 位，激活还是 32 位浮点。
// ---------------------------------------------------------------------------

// 每多少个数共享一个 scale。
//
// 为什么不是整个张量共享一个？因为权重里只要有一个离群的大值，
// 就会把 scale 撑大，让其余所有数挤到 int8 的低位上，精度全丢：
//
//   整个张量一个 scale            每 32 个一组一个 scale
//   [0.01 0.02 ... 5.0]          [0.01 0.02 ...][... 5.0 ...]
//    scale = 5.0/127 = 0.039      前一组 scale 小，精度保住了
//    0.01 → round(0.25) = 0       0.01 → round(40) = 40  ✓
//    全变成 0 了
//
// 32 是 llama.cpp 的 Q8_0 用的值，也正好是 4 个 AVX2 向量。
constexpr i64 kQGroup = 32;

// 量化权重的**视图**，不拥有内存。
//
// 不拥有是刻意的：这样它既能指向内存里的 buffer，也能直接指向 mmap
// 映射上来的文件，后者根本没有「加载」这一步。
struct QView {
  const std::int8_t* q = nullptr;  // rows × cols 个量化值
  const float* scales = nullptr;   // rows × (cols / group) 个 scale
  i64 rows = 0;
  i64 cols = 0;
  i64 group = kQGroup;

  [[nodiscard]] i64 groups_per_row() const noexcept { return (cols + group - 1) / group; }
  [[nodiscard]] bool valid() const noexcept { return q != nullptr && scales != nullptr; }
  // 量化后占多少字节（含 scale）
  [[nodiscard]] i64 bytes() const noexcept {
    return rows * cols + rows * groups_per_row() * static_cast<i64>(sizeof(float));
  }
};

// 拥有内存的量化张量，给「运行时量化」和测试用。
// 真正跑 GPT-2 时权重是预先量化好存在文件里的，用的是 QView。
class QTensor {
 public:
  QTensor() = default;
  // 把一个 f32 的二维张量按行分组量化
  static QTensor from(const Tensor& w, i64 group = kQGroup);

  [[nodiscard]] QView view() const noexcept;
  [[nodiscard]] i64 rows() const noexcept { return rows_; }
  [[nodiscard]] i64 cols() const noexcept { return cols_; }
  [[nodiscard]] Tensor dequantize() const;

 private:
  std::vector<std::int8_t> q_;
  std::vector<float> scales_;
  i64 rows_ = 0, cols_ = 0, group_ = kQGroup;
};

namespace kernel {

// 把一行 f32 量化成 int8 + 每组一个 scale。
// scales 的长度必须是 ceil(n / group)。
void quantize_row_q8(std::span<const float> src, std::int8_t* q, float* scales,
                     i64 group);

// 反量化回 f32，用来看量化到底丢了多少精度
void dequantize_q8(const QView& w, std::span<float> out);

// y[N] = W[N,K] × x[K]，W 是量化的。
// 对应 ops::linear 那个 (out, in) 布局，也就是 GPT-2 里所有的权重矩阵。
void gemv_nt_q8_f32(std::span<const float> x, const QView& w, std::span<float> y);

// y[N] = x[K] × B[K,N]，B 是量化的（按列分组，对应 HuggingFace Conv1D 布局）。
// 注意这里 B 的分组方向和上面不同，见 src/quant.cpp 里的说明。
void gemm_q8_f32(std::span<const float> a, const QView& b, std::span<float> c,
                 i64 M);

}  // namespace kernel

}  // namespace infer

