#include "infer/quant.hpp"

#include <algorithm>
#include <cmath>
#include <format>
#include <stdexcept>

#include "infer/kernel.hpp"
#include "infer/thread_pool.hpp"

#if defined(__AVX2__) && defined(__FMA__)
#include <immintrin.h>
#define INFER_HAS_AVX2 1
#else
#define INFER_HAS_AVX2 0
#endif

namespace infer {

namespace {

[[noreturn]] void fail(const std::string& msg) {
  throw std::invalid_argument("[infer::quant] " + msg);
}

}  // namespace

namespace kernel {

// ---------------------------------------------------------------------------
// 量化一行
// ---------------------------------------------------------------------------
void quantize_row_q8(std::span<const float> src, std::int8_t* q, float* scales,
                     i64 group) {
  const auto n = static_cast<i64>(src.size());
  i64 gi = 0;
  for (i64 base = 0; base < n; base += group, ++gi) {
    const i64 len = std::min(group, n - base);

    // 对称量化：只看最大绝对值，不记录零点。
    // 权重分布本来就大致以 0 为中心，省下零点既省存储又省一次减法。
    // 激活值（尤其 GELU 之后）不对称，那才需要非对称量化。
    float absmax = 0.0F;
    for (i64 i = 0; i < len; ++i) absmax = std::max(absmax, std::fabs(src[static_cast<std::size_t>(base + i)]));

    // 127 而不是 128：对称量化下 -128 那一档用不上，
    // 硬要用会让正负范围不对称，反而引入偏差。
    const float scale = absmax / 127.0F;
    scales[gi] = scale;
    const float inv = scale > 0.0F ? 1.0F / scale : 0.0F;

    for (i64 i = 0; i < len; ++i) {
      // std::lround 是四舍五入到最近整数。用截断（直接转 int）会引入
      // 系统性的偏向零的偏差，整个矩阵累加起来就变成可观的误差了。
      const auto v = std::lround(src[static_cast<std::size_t>(base + i)] * inv);
      q[base + i] = static_cast<std::int8_t>(std::clamp<long>(v, -127, 127));
    }
  }
}

void dequantize_q8(const QView& w, std::span<float> out) {
  if (!w.valid()) fail("dequantize_q8: 视图是空的");
  const i64 gpr = w.groups_per_row();
  for (i64 r = 0; r < w.rows; ++r) {
    for (i64 g = 0; g < gpr; ++g) {
      const float s = w.scales[r * gpr + g];
      const i64 base = g * w.group;
      const i64 len = std::min(w.group, w.cols - base);
      for (i64 i = 0; i < len; ++i) {
        out[static_cast<std::size_t>(r * w.cols + base + i)] =
            static_cast<float>(w.q[r * w.cols + base + i]) * s;
      }
    }
  }
}

// ---------------------------------------------------------------------------
// 量化矩阵乘
// ---------------------------------------------------------------------------

namespace {

#if INFER_HAS_AVX2
// 读 8 个 int8，符号扩展成 8 个 float。
// 这是整个量化推理的热点操作：真正的开销在把 1 字节变成 4 字节，
// 而不在乘加。所以说量化买到的是带宽，不是算力。
inline __m256 load8_i8_as_f32(const std::int8_t* p) {
  const __m128i b = _mm_loadl_epi64(reinterpret_cast<const __m128i*>(p));
  return _mm256_cvtepi32_ps(_mm256_cvtepi8_epi32(b));
}

inline float hsum(__m256 v) {
  __m128 lo = _mm256_castps256_ps128(v);
  lo = _mm_add_ps(lo, _mm256_extractf128_ps(v, 1));
  lo = _mm_add_ps(lo, _mm_movehl_ps(lo, lo));
  lo = _mm_add_ss(lo, _mm_shuffle_ps(lo, lo, 1));
  return _mm_cvtss_f32(lo);
}
#endif

// 算 y[row] = Σ_g scale[row][g] · (x · q[row][g组])
//
// 关键在于**组内先用整数值累加，出组才乘一次 scale**。
// 如果每个元素都乘 scale，乘法次数翻倍，而且精度还更差
// （小数反复相乘累积舍入误差）。
float dot_row_q8(const float* x, const std::int8_t* q, const float* scales,
                 i64 cols, i64 group) {
  float total = 0.0F;
  i64 gi = 0;
  for (i64 base = 0; base < cols; base += group, ++gi) {
    const i64 len = std::min(group, cols - base);
    const float s = scales[gi];
    if (s == 0.0F) continue;  // 整组都是 0，跳过

#if INFER_HAS_AVX2
    // group 是 32，正好 4 个 AVX2 向量。4 个独立累加器把 FMA 流水线填满。
    if (len == 32) {
      __m256 a0 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 0), load8_i8_as_f32(q + base + 0));
      __m256 a1 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 8), load8_i8_as_f32(q + base + 8));
      __m256 a2 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 16), load8_i8_as_f32(q + base + 16));
      __m256 a3 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 24), load8_i8_as_f32(q + base + 24));
      total += s * hsum(_mm256_add_ps(_mm256_add_ps(a0, a1), _mm256_add_ps(a2, a3)));
      continue;
    }
#endif
    float acc = 0.0F;
    for (i64 i = 0; i < len; ++i) {
      acc += x[base + i] * static_cast<float>(q[base + i]);
    }
    total += s * acc;
  }
  return total;
}

}  // namespace

void matmul_nt_q8_f32(std::span<const float> x, const QView& w, std::span<float> y,
                      i64 M) {
  if (!w.valid()) fail("matmul_nt_q8_f32: 权重视图是空的");
  const i64 N = w.rows, K = w.cols;
  const i64 gpr = w.groups_per_row();

  // 并行策略和阶段 6 的浮点版完全一样：按输出列 N 切，
  // 按工作量决定叫几个线程。量化只是让每份活儿搬的字节少了 3/4。
  const int nt = kernel::get_num_threads();
  const i64 work = M * N * K;
  auto body = [&](i64 j_lo, i64 j_hi) {
    for (i64 j = j_lo; j < j_hi; ++j) {
      const std::int8_t* qrow = w.q + j * K;
      const float* srow = w.scales + j * gpr;
      for (i64 m = 0; m < M; ++m) {
        y[static_cast<std::size_t>(m * N + j)] =
            dot_row_q8(x.data() + m * K, qrow, srow, K, w.group);
      }
    }
  };

  if (nt <= 1 || N < 2) {
    body(0, N);
    return;
  }
  ThreadPool& pool = ThreadPool::instance(nt);
  pool.parallel_for(N, ThreadPool::threads_for(work, nt), body);
}

}  // namespace kernel

// ---------------------------------------------------------------------------
// QTensor
// ---------------------------------------------------------------------------

QTensor QTensor::from(const Tensor& w, i64 group) {
  if (w.ndim() != 2) {
    fail(std::format("QTensor::from 需要二维张量，拿到 {} 维", w.ndim()));
  }
  if (group <= 0) fail("组大小必须是正数");

  QTensor out;
  out.rows_ = w.dim(0);
  out.cols_ = w.dim(1);
  out.group_ = group;
  const i64 gpr = (out.cols_ + group - 1) / group;

  out.q_.resize(static_cast<std::size_t>(out.rows_ * out.cols_));
  out.scales_.resize(static_cast<std::size_t>(out.rows_ * gpr));

  const Tensor cw = w.contiguous();
  std::span<const float> src = cw.data();
  for (i64 r = 0; r < out.rows_; ++r) {
    kernel::quantize_row_q8(
        src.subspan(static_cast<std::size_t>(r * out.cols_),
                    static_cast<std::size_t>(out.cols_)),
        out.q_.data() + r * out.cols_, out.scales_.data() + r * gpr, group);
  }
  return out;
}

QView QTensor::view() const noexcept {
  return QView{.q = q_.data(),
               .scales = scales_.data(),
               .rows = rows_,
               .cols = cols_,
               .group = group_};
}

Tensor QTensor::dequantize() const {
  Tensor out = Tensor::zeros({rows_, cols_});
  kernel::dequantize_q8(view(), out.data());
  return out;
}

}  // namespace infer

#pragma once

#include <cstddef>
#include <span>
#include <string>
#include <unordered_map>
#include <vector>

#include "infer/model_file.hpp"
#include "infer/quant.hpp"

namespace infer {

// ---------------------------------------------------------------------------
// 内存映射文件
//
// 阶段 3 的 ModelFile 是「把整个文件 read() 进一个 vector」。
// 500 MB 的 GPT-2 要花约 2 秒，而且内存里存了两份（页缓存 + 我们的 vector）。
//
// mmap 换了个思路：**不读文件，只是告诉内核「把这个文件摆到我的地址空间里」**。
//
//   read()                        mmap()
//   ┌────────┐                    ┌────────┐
//   │ 磁盘   │                    │ 磁盘   │
//   └───┬────┘                    └───┬────┘
//       │ 读                          │ 建立映射（不搬数据）
//   ┌───▼────┐                    ┌───▼──────────┐
//   │页缓存  │                    │ 页缓存 ←──┐  │
//   └───┬────┘                    └───────────┼──┘
//       │ 拷贝                                │ 虚拟地址直接指向它
//   ┌───▼────┐                    ┌───────────┴──┐
//   │ 我的   │                    │ 我的地址空间  │
//   │ vector │                    │（没有副本）   │
//   └────────┘                    └──────────────┘
//    2 秒，两份内存                 约 0 秒，一份内存
//
// 好处不止是快：
//   1. 真正用到的页才会从磁盘调进来（按需分页）
//   2. 多个进程映射同一个文件，**共享同一份物理内存**
//      —— 同一台机器上跑 8 个推理服务，权重只占一份
//   3. 内存压力大时内核可以把干净页直接丢掉，需要时再读回来，
//      不会像 malloc 的内存那样被迫写进 swap
//
// 代价：第一次访问某一页会触发缺页中断去读磁盘。所以「加载耗时」
// 其实是被推迟到了第一次推理，而不是消失了。冷启动跑一次就知道。
// ---------------------------------------------------------------------------
class MappedFile {
 public:
  MappedFile() = default;
  static MappedFile open(const std::string& path);

  ~MappedFile();
  MappedFile(MappedFile&& other) noexcept;
  MappedFile& operator=(MappedFile&& other) noexcept;
  MappedFile(const MappedFile&) = delete;
  MappedFile& operator=(const MappedFile&) = delete;

  [[nodiscard]] std::span<const std::byte> bytes() const noexcept {
    return {static_cast<const std::byte*>(addr_), size_};
  }
  [[nodiscard]] std::size_t size() const noexcept { return size_; }
  [[nodiscard]] bool is_open() const noexcept { return addr_ != nullptr; }

  // 提示内核「我接下来会顺序读完整个文件」，让它提前预读。
  // 纯优化，不调也能正常工作。
  void advise_sequential() const;
  // 反过来：主动把页调进内存，把缺页成本一次付清而不是分摊到推理时
  void prefault() const;

 private:
  void* addr_ = nullptr;
  std::size_t size_ = 0;
  int fd_ = -1;
};

// ---------------------------------------------------------------------------
// 零拷贝的模型文件
//
// 和 ModelFile 的接口几乎一样，区别在于 get_view() 返回的是**指向映射区
// 的指针**，没有任何拷贝。500 MB 的模型「加载」时间接近 0。
// ---------------------------------------------------------------------------
class MappedModel {
 public:
  static MappedModel open(const std::string& path);

  [[nodiscard]] bool has(const std::string& name) const;

  // f32 张量的零拷贝视图。
  //
  // 注意返回的 span 的生命周期绑在 MappedModel 上 —— 对象一析构，
  // 映射就没了，所有 span 全部失效。这是零拷贝的代价：
  // 省掉拷贝，就得自己管好生命周期。
  [[nodiscard]] std::span<const float> get_view(const std::string& name) const;
  [[nodiscard]] Shape shape_of(const std::string& name) const;

  // 量化权重的视图。约定：名字为 X 的量化权重存成两个张量
  // X.q（int8 数据）和 X.s（f32 scale）。
  [[nodiscard]] QView get_qview(const std::string& name) const;

  // 需要拷贝的时候（比如要改内容）还是可以拿到普通 Tensor
  [[nodiscard]] Tensor get(const std::string& name) const;

  [[nodiscard]] const std::vector<TensorInfo>& tensors() const noexcept { return infos_; }
  [[nodiscard]] std::size_t mapped_bytes() const noexcept { return map_.size(); }
  [[nodiscard]] std::string summary() const;

  void advise_sequential() const { map_.advise_sequential(); }
  void prefault() const { map_.prefault(); }

 private:
  MappedFile map_;
  std::uint64_t data_start_ = 0;
  std::vector<TensorInfo> infos_;
  std::unordered_map<std::string, std::size_t> index_;

  [[nodiscard]] const TensorInfo& must_find(const std::string& name) const;
  [[nodiscard]] const std::byte* data_ptr(const TensorInfo& info) const;
};

}  // namespace infer

