template <class T>
T read_le(const std::vector<std::byte>& buf, std::size_t& pos) {
  if (pos + sizeof(T) > buf.size()) {
    fail(std::format("文件在偏移 {} 处提前结束（还想读 {} 字节）", pos, sizeof(T)));
  }
  T v{};
  std::memcpy(&v, buf.data() + pos, sizeof(T));
  pos += sizeof(T);
  if constexpr (std::endian::native == std::endian::big) {
    // x86 和 arm 都是小端，这段几乎不会执行到，但写上才算正确
    auto* p = reinterpret_cast<std::byte*>(&v);
    std::reverse(p, p + sizeof(T));
  }
  return v;
}

std::string read_string(const std::vector<std::byte>& buf, std::size_t& pos, std::size_t n) {
  if (pos + n > buf.size()) fail("读字符串时文件提前结束");
  std::string s(reinterpret_cast<const char*>(buf.data() + pos), n);
  pos += n;
  return s;
}

}  // namespace

ModelFile ModelFile::load(const std::string& path) {
  std::ifstream f(path, std::ios::binary | std::ios::ate);
  if (!f) {
    fail("打不开模型文件: " + path +
         "\n  先运行: .venv/bin/python tools/train_mnist.py");
  }
  const auto size = static_cast<std::size_t>(f.tellg());
  f.seekg(0);

  std::vector<std::byte> buf(size);
  f.read(reinterpret_cast<char*>(buf.data()), static_cast<std::streamsize>(size));
  if (!f) fail("读取文件失败: " + path);

  std::size_t pos = 0;
  if (size < 12 || std::memcmp(buf.data(), "INFR", 4) != 0) {
    fail("文件头不是 INFR，这不是一个 .infer 模型文件: " + path);
  }
  pos = 4;

  ModelFile m;
  m.version_ = read_le<std::uint32_t>(buf, pos);
  if (m.version_ != 1) {
    fail(std::format("不支持的版本 {}（本程序只认版本 1）", m.version_));
  }
  const auto count = read_le<std::uint32_t>(buf, pos);

  m.infos_.reserve(count);
  for (std::uint32_t i = 0; i < count; ++i) {
    TensorInfo info;
    const auto name_len = read_le<std::uint32_t>(buf, pos);
    info.name = read_string(buf, pos, name_len);

    const auto dtype_code = read_le<std::uint32_t>(buf, pos);
    if (dtype_code != 0) {
      fail(std::format("张量 '{}' 的 dtype 编码 {} 暂不支持（目前只有 f32）",
                       info.name, dtype_code));
    }
    info.dtype = DType::F32;

    const auto ndim = read_le<std::uint32_t>(buf, pos);
    info.shape.resize(ndim);
    for (std::uint32_t d = 0; d < ndim; ++d) {
      info.shape[d] = read_le<std::int64_t>(buf, pos);
    }
    info.offset = read_le<std::uint64_t>(buf, pos);
    info.nbytes = read_le<std::uint64_t>(buf, pos);

    // 元信息自洽性检查：声明的字节数必须和 shape 对得上。
    // 模型文件损坏或格式写错时，在这里报错远好过后面读出一堆 nan。
    const auto expect = static_cast<std::uint64_t>(numel_of(info.shape)) *
                        dtype_size(info.dtype);
    if (info.nbytes != expect) {
      fail(std::format("张量 '{}' 元信息不一致：声明 {} 字节，但形状需要 {} 字节",
                       info.name, info.nbytes, expect));
    }

    m.index_.emplace(info.name, m.infos_.size());
    m.infos_.push_back(std::move(info));
  }

  const auto data_start = read_le<std::uint64_t>(buf, pos);
  if (data_start > size) {
    fail(std::format("data_start={} 超出文件大小 {}", data_start, size));
  }
  m.data_.assign(buf.begin() + static_cast<std::ptrdiff_t>(data_start), buf.end());

  // 再检查一遍每个张量的数据都在数据区范围内
  for (const auto& info : m.infos_) {
    if (info.offset + info.nbytes > m.data_.size()) {
      fail(std::format("张量 '{}' 的数据超出文件末尾", info.name));
    }
  }
  return m;
}

