#include "infer/mmap_file.hpp"

#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

#include <cstring>
#include <format>
#include <stdexcept>
#include <utility>

namespace infer {

namespace {

[[noreturn]] void fail(const std::string& msg) {
  throw std::runtime_error("[infer::MappedFile] " + msg);
}

}  // namespace

// ---------------------------------------------------------------------------
// MappedFile
// ---------------------------------------------------------------------------

MappedFile MappedFile::open(const std::string& path) {
  MappedFile m;
  m.fd_ = ::open(path.c_str(), O_RDONLY);
  if (m.fd_ < 0) {
    fail(std::format("打不开 {}: {}", path, std::strerror(errno)));
  }

  struct stat st{};
  if (::fstat(m.fd_, &st) != 0) {
    ::close(m.fd_);
    fail(std::format("fstat {} 失败: {}", path, std::strerror(errno)));
  }
  m.size_ = static_cast<std::size_t>(st.st_size);
  if (m.size_ == 0) {
    ::close(m.fd_);
    fail("文件是空的: " + path);
  }

  // PROT_READ 只读，MAP_PRIVATE 写时复制（我们不写，所以永远不会复制）。
  // 关键点：这个调用**不读任何数据**，只是在页表里记一笔。
  // 所以映射 500 MB 和映射 5 KB 的耗时几乎一样。
  m.addr_ = ::mmap(nullptr, m.size_, PROT_READ, MAP_PRIVATE, m.fd_, 0);
  if (m.addr_ == MAP_FAILED) {
    ::close(m.fd_);
    m.addr_ = nullptr;
    fail(std::format("mmap {} 失败: {}", path, std::strerror(errno)));
  }
  return m;
}

MappedFile::~MappedFile() {
  if (addr_ != nullptr) ::munmap(addr_, size_);
  if (fd_ >= 0) ::close(fd_);
}

MappedFile::MappedFile(MappedFile&& other) noexcept
    : addr_(other.addr_), size_(other.size_), fd_(other.fd_) {
  other.addr_ = nullptr;
  other.size_ = 0;
  other.fd_ = -1;
}

MappedFile& MappedFile::operator=(MappedFile&& other) noexcept {
  if (this != &other) {
    if (addr_ != nullptr) ::munmap(addr_, size_);
    if (fd_ >= 0) ::close(fd_);
    addr_ = std::exchange(other.addr_, nullptr);
    size_ = std::exchange(other.size_, 0);
    fd_ = std::exchange(other.fd_, -1);
  }
  return *this;
}

void MappedFile::advise_sequential() const {
  if (addr_ != nullptr) {
    // 告诉内核我们会顺序读完，它会更积极地预读。纯建议，失败也无所谓。
    (void)::madvise(addr_, size_, MADV_SEQUENTIAL | MADV_WILLNEED);
  }
}

void MappedFile::prefault() const {
  if (addr_ == nullptr) return;
  // 每隔一个页面大小读一个字节，把所有页都调进内存。
  //
  // 为什么要这么做？mmap 的「加载时间为 0」是有水分的 —— 缺页中断的
  // 成本被推迟到了第一次访问。要衡量稳态性能就得先把这笔账付掉，
  // 不然第一次推理会显著偏慢，benchmark 数字不可信。
  const auto page = static_cast<std::size_t>(::sysconf(_SC_PAGESIZE));
  const auto* p = static_cast<const volatile char*>(addr_);
  volatile char sink = 0;
  for (std::size_t off = 0; off < size_; off += page) sink = p[off];
  (void)sink;
}

// ---------------------------------------------------------------------------
// MappedModel
// ---------------------------------------------------------------------------

MappedModel MappedModel::open(const std::string& path) {
  MappedModel m;
  m.map_ = MappedFile::open(path);

  // 解析头用的是和 ModelFile 完全一样的函数 —— 格式解析只有一份实现。
  detail::Header h = detail::parse_infer_header(m.map_.bytes(), path);
  m.data_start_ = h.data_start;
  m.infos_ = std::move(h.infos);
  for (std::size_t i = 0; i < m.infos_.size(); ++i) {
    m.index_.emplace(m.infos_[i].name, i);
  }
  return m;
}

const TensorInfo& MappedModel::must_find(const std::string& name) const {
  auto it = index_.find(name);
  if (it == index_.end()) {
    std::string available;
    for (const auto& info : infos_) available += "\n    " + info.name;
    throw std::runtime_error("[infer::MappedModel] 模型里没有名为 '" + name +
                             "' 的张量。文件里有这些：" + available);
  }
  return infos_[it->second];
}

const std::byte* MappedModel::data_ptr(const TensorInfo& info) const {
  return map_.bytes().data() + data_start_ + info.offset;
}

bool MappedModel::has(const std::string& name) const { return index_.contains(name); }

Shape MappedModel::shape_of(const std::string& name) const {
  return must_find(name).shape;
}

std::span<const float> MappedModel::get_view(const std::string& name) const {
  const TensorInfo& info = must_find(name);
  if (info.dtype != DType::F32) {
    throw std::runtime_error(
        std::format("[infer::MappedModel] 张量 '{}' 是 {}，不是 f32", name,
                    dtype_name(info.dtype)));
  }
  // reinterpret_cast 在这里是安全的，但依赖一个前提：
  // 数据区的起点和每个张量的偏移都是 4 字节对齐的。
  // .infer 的写入端保证了这点（所有张量都是 4 字节元素紧密排列）。
  return {reinterpret_cast<const float*>(data_ptr(info)),
          static_cast<std::size_t>(numel_of(info.shape))};
}

QView MappedModel::get_qview(const std::string& name) const {
  const TensorInfo& qi = must_find(name + ".q");
  const TensorInfo& si = must_find(name + ".s");
  if (qi.dtype != DType::I8) {
    throw std::runtime_error(std::format(
        "[infer::MappedModel] '{}.q' 应该是 i8，实际是 {}", name, dtype_name(qi.dtype)));
  }
  if (qi.shape.size() != 2 || si.shape.size() != 2) {
    throw std::runtime_error("[infer::MappedModel] 量化权重必须是二维");
  }

  QView v;
  v.q = reinterpret_cast<const std::int8_t*>(data_ptr(qi));
  v.scales = reinterpret_cast<const float*>(data_ptr(si));
  v.rows = qi.shape[0];
  v.cols = qi.shape[1];
  // 组大小是从形状反推的：每行有 cols 个值、si.shape[1] 个 scale
  const i64 gpr = si.shape[1];
  if (gpr <= 0 || si.shape[0] != v.rows) {
    throw std::runtime_error(std::format(
        "[infer::MappedModel] '{}' 的 scale 形状 ({}, {}) 和数据形状 ({}, {}) 对不上",
        name, si.shape[0], si.shape[1], v.rows, v.cols));
  }
  v.group = (v.cols + gpr - 1) / gpr;
  if (v.groups_per_row() != gpr) {
    throw std::runtime_error(std::format(
        "[infer::MappedModel] '{}' 反推出的组大小 {} 和 scale 个数 {} 不自洽",
        name, v.group, gpr));
  }
  return v;
}

Tensor MappedModel::get(const std::string& name) const {
  const TensorInfo& info = must_find(name);
  Tensor t = Tensor::zeros(info.shape, info.dtype);
  std::memcpy(t.data().data(), data_ptr(info), info.nbytes);
  return t;
}

std::string MappedModel::summary() const {
  std::string s = std::format("MappedModel({} 个张量, 映射 {:.1f} MB)\n", infos_.size(),
                              static_cast<double>(map_.size()) / 1e6);
  std::uint64_t total = 0;
  for (const auto& info : infos_) total += info.nbytes;
  s += std::format("  数据区 {:.1f} MB\n", static_cast<double>(total) / 1e6);
  return s;
}

}  // namespace infer

#pragma once

#include <cstddef>
#include <memory>
#include <span>
#include <vector>

#include "infer/tensor.hpp"

namespace infer {

// ---------------------------------------------------------------------------
// Arena（内存池 / 竞技场分配器）
//
// 阶段 6 的 decode 路径每生成一个词要分配几十个临时张量：
// LayerNorm 的输出、QKV、注意力结果、MLP 的中间层……
// 每个都走一次 new/delete。
//
// 一次 malloc 大约 50~100 ns。每个词 12 层 × 8 次 ≈ 100 次分配，
// 每秒 30 个词 = 3000 次分配，约 0.3 ms/s。听起来不多，
// 但还有两笔更隐蔽的账：
//
//   1. **缺页**。新分配的大块内存第一次写会触发缺页中断，
//      比 malloc 本身贵得多
//   2. **cache 不友好**。每次拿到的地址都不一样，
//      上一个词预热好的 cache 行全白费
//
// Arena 的做法简单到近乎粗暴：**预先要一大块，之后只挪一个指针**。
//
//     bump 指针
//         │
//   ┌─────▼──────────────────────────────────┐
//   │■■■■■│                                  │  一块连续内存
//   └──────────────────────────────────────── ┘
//    已分配   未分配
//
//   分配 = 指针往右挪（几纳秒）
//   释放 = **不支持**，只能整体 reset（把指针挪回开头）
//
// 「不支持单个释放」听起来是缺陷，但正好契合推理的特点：
// 一次前向传播里产生的所有临时张量，在这次传播结束后**全部**都不要了。
// 那就不用逐个释放，直接 reset 一次。
//
// 这和阶段 4 计算图里的「内存复用」是互补的：
// 那里靠引用计数决定什么时候能复用一块 buffer（省峰值内存），
// 这里省的是分配本身的开销。
// ---------------------------------------------------------------------------
class Arena {
 public:
  explicit Arena(std::size_t capacity_bytes);

  // 分配 n 个 float，返回的内存**未初始化**。
  // 对齐到 64 字节，既满足 AVX2 的对齐加载，也避免不同张量共享 cache line。
  [[nodiscard]] std::span<float> alloc_floats(std::size_t n);

  // 分配一个张量，数据落在 arena 上。
  //
  // 注意：返回的 Tensor **不拥有**内存，它的生命周期绑在 Arena 上。
  // reset() 之后继续用它就是访问已回收的内存。这是用 arena 换性能的代价，
  // 所以它只该用在「一次前向传播」这种生命周期非常清楚的场合。
  [[nodiscard]] Tensor tensor(const Shape& shape);

  // 把 bump 指针挪回开头。不释放底层内存，下次前向还用这一块。
  void reset() noexcept { used_ = 0; }

  [[nodiscard]] std::size_t used() const noexcept { return used_; }
  [[nodiscard]] std::size_t capacity() const noexcept { return capacity_; }
  // 历史最高水位。用来反推「这个模型到底需要多大的 arena」
  [[nodiscard]] std::size_t peak() const noexcept { return peak_; }
  // 分配次数，用来验证「推理期零 malloc」
  [[nodiscard]] std::size_t alloc_count() const noexcept { return allocs_; }

 private:
  std::unique_ptr<std::byte[]> buf_;
  std::size_t capacity_ = 0;
  std::size_t used_ = 0;
  std::size_t peak_ = 0;
  std::size_t allocs_ = 0;
};

