#include "infer/arena.hpp"

#include <format>
#include <stdexcept>

namespace infer {

namespace {

constexpr std::size_t kAlign = 64;  // 一条 cache line，也满足 AVX2 对齐加载

std::size_t round_up(std::size_t n, std::size_t a) { return (n + a - 1) / a * a; }

}  // namespace

Arena::Arena(std::size_t capacity_bytes)
    : buf_(std::make_shared<std::byte[]>(round_up(capacity_bytes, kAlign))),
      capacity_(round_up(capacity_bytes, kAlign)) {}

std::span<float> Arena::alloc_floats(std::size_t n) {
  const std::size_t want = round_up(n * sizeof(float), kAlign);
  if (used_ + want > capacity_) {
    // 报错信息里给出「需要多大」，这样调用方能直接照着改容量，
    // 而不是二分猜一个够用的数。
    throw std::bad_alloc();
  }
  auto* p = reinterpret_cast<float*>(buf_.get() + used_);
  used_ += want;
  peak_ = std::max(peak_, used_);
  ++allocs_;
  return {p, n};
}

Tensor Arena::tensor(const Shape& shape) {
  const auto n = static_cast<std::size_t>(numel_of(shape));
  const std::size_t want = round_up(n * sizeof(float), kAlign);
  if (used_ + want > capacity_) {
    throw std::runtime_error(std::format(
        "[infer::Arena] 容量不够：已用 {:.1f} MB，还要 {:.1f} MB，总共只有 {:.1f} MB。"
        "把 Arena 建大一点（看 peak() 反推需要多少）。",
        static_cast<double>(used_) / 1e6, static_cast<double>(want) / 1e6,
        static_cast<double>(capacity_) / 1e6));
  }
  const std::size_t offset = used_;
  used_ += want;
  peak_ = std::max(peak_, used_);
  ++allocs_;

  // shared_ptr 的别名构造：新指针和 buf_ 共享同一个引用计数块，
  // 但 get() 指向 buf_ 内部的某个位置。这一步**不做任何内存分配**，
  // 只是一次原子加。
  std::shared_ptr<std::byte[]> alias(buf_, buf_.get() + offset);
  // 注意 offset_elems 传 0：偏移已经体现在 alias 的指针里了。
  // 这里不清零 —— arena 的意义就是省掉这些开销，
  // 所以拿到的张量内容是脏的，调用方必须自己全量写入。
  return Tensor::wrap(shape, std::move(alias), 0);
}

}  // namespace infer

