void dequantize_row_q8(const QView& w, i64 row, std::span<float> out) {
  if (!w.valid()) fail("dequantize_row_q8: 视图是空的");
  if (row < 0 || row >= w.rows) {
    fail(std::format("dequantize_row_q8: 行号 {} 越界（共 {} 行）", row, w.rows));
  }
  const i64 gpr = w.groups_per_row();
  const std::int8_t* q = w.q + row * w.cols;
  const float* s = w.scales + row * gpr;
  for (i64 g = 0; g < gpr; ++g) {
    const i64 base = g * w.group;
    const i64 len = std::min(w.group, w.cols - base);
    for (i64 i = 0; i < len; ++i) {
      out[static_cast<std::size_t>(base + i)] = static_cast<float>(q[base + i]) * s[g];
    }
  }
}

