i64 LinearWeight::in_features() const noexcept {
  return q_.valid() ? q_.cols : (f32_.ndim() == 2 ? f32_.dim(0) : 0);
}
i64 LinearWeight::out_features() const noexcept {
  return q_.valid() ? q_.rows : (f32_.ndim() == 2 ? f32_.dim(1) : 0);
}
std::size_t LinearWeight::bytes() const noexcept {
  if (q_.valid()) return static_cast<std::size_t>(q_.bytes());
  return static_cast<std::size_t>(f32_.numel()) * sizeof(float);
}

Tensor LinearWeight::forward(const Tensor& x, const Tensor& bias) const {
  if (!q_.valid()) {
    // f32 路径：权重是 (in, out)，走 affine
    return bias.empty() ? ops::matmul(x, f32_) : ops::affine(x, f32_, bias);
  }

  // 量化路径：权重是 (out, in)，走 NT 布局的量化矩阵乘
  const i64 M = x.dim(0), K = x.dim(1), N = q_.rows;
  if (K != q_.cols) {
    fail(std::format("LinearWeight: 输入特征数 {} 和权重的 {} 对不上", K, q_.cols));
  }
  const Tensor cx = x.contiguous();
  Tensor out = Tensor::zeros({M, N});
  kernel::matmul_nt_q8_f32(cx.data(), q_, out.data(), M);

  if (!bias.empty()) {
    std::span<const float> bv = bias.data();
    std::span<float> ov = out.data();
    for (i64 r = 0; r < M; ++r) {
      for (i64 j = 0; j < N; ++j) {
        ov[static_cast<std::size_t>(r * N + j)] += bv[static_cast<std::size_t>(j)];
      }
    }
  }
  return out;
}

