std::size_t GPT2::weight_bytes() const noexcept {
  std::size_t total = 0;
  total += is_quantized() ? static_cast<std::size_t>(wte_q_.bytes())
                          : static_cast<std::size_t>(wte_.numel()) * sizeof(float);
  total += static_cast<std::size_t>(wpe_.numel() + lnf_w_.numel() + lnf_b_.numel()) *
           sizeof(float);
  for (const Layer& L : layers_) {
    total += L.attn_w.bytes() + L.attn_proj_w.bytes() + L.fc_w.bytes() + L.proj_w.bytes();
    total += static_cast<std::size_t>(L.ln1_w.numel() + L.ln1_b.numel() +
                                      L.ln2_w.numel() + L.ln2_b.numel() +
                                      L.attn_b.numel() + L.attn_proj_b.numel() +
                                      L.fc_b.numel() + L.proj_b.numel()) *
             sizeof(float);
  }
  return total;
}

namespace {

// 超参数是单独一个小文件，两种加载方式共用
GPT2Config read_config(const std::string& model_dir) {
  const ModelFile f = ModelFile::load(model_dir + "/gpt2_config.infer");
  auto get = [&](const char* name) {
    return static_cast<int>(std::lround(f.get(name).data()[0]));
  };
  return GPT2Config{.n_layer = get("n_layer"),
                    .n_head = get("n_head"),
                    .n_embd = get("n_embd"),
                    .n_vocab = get("n_vocab"),
                    .n_ctx = get("n_ctx")};
}

}  // namespace

GPT2 GPT2::load(const std::string& model_dir) {
  GPT2 m;
  m.cfg_ = read_config(model_dir);

  // ModelFile 内部持有整个文件的字节。get() 会把张量拷出来，
  // 所以这里用个作用域，让 ModelFile 在取完权重后立刻释放 —— 否则 500 MB 白占。
  {
    const ModelFile w = ModelFile::load(model_dir + "/gpt2.infer");
    m.wte_ = w.get("wte.weight");
    m.wpe_ = w.get("wpe.weight");
    m.lnf_w_ = w.get("ln_f.weight");
    m.lnf_b_ = w.get("ln_f.bias");

    m.layers_.reserve(static_cast<std::size_t>(m.cfg_.n_layer));
    for (int i = 0; i < m.cfg_.n_layer; ++i) {
      const std::string p = std::format("h.{}.", i);
      Layer L;
      L.ln1_w = w.get(p + "ln_1.weight");
      L.ln1_b = w.get(p + "ln_1.bias");
      L.ln2_w = w.get(p + "ln_2.weight");
      L.ln2_b = w.get(p + "ln_2.bias");
      L.attn_w = LinearWeight::from_f32_conv1d(w.get(p + "attn.c_attn.weight"));
      L.attn_proj_w = LinearWeight::from_f32_conv1d(w.get(p + "attn.c_proj.weight"));
      L.fc_w = LinearWeight::from_f32_conv1d(w.get(p + "mlp.c_fc.weight"));
      L.proj_w = LinearWeight::from_f32_conv1d(w.get(p + "mlp.c_proj.weight"));
      L.attn_b = w.get(p + "attn.c_attn.bias");
      L.attn_proj_b = w.get(p + "attn.c_proj.bias");
      L.fc_b = w.get(p + "mlp.c_fc.bias");
      L.proj_b = w.get(p + "mlp.c_proj.bias");
      m.layers_.push_back(std::move(L));
    }
  }

  // 形状自检。权重文件对不上时，与其让后面某个算子抛个看不懂的错，
  // 不如在这里说清楚哪里不对。
  const int C = m.cfg_.n_embd;
  if (m.wte_.dim(1) != C || m.wte_.dim(0) != m.cfg_.n_vocab) {
    fail(std::format("wte 形状应为 ({}, {})，实际 ({}, {})",
                     m.cfg_.n_vocab, C, m.wte_.dim(0), m.wte_.dim(1)));
  }
  const LinearWeight& a = m.layers_[0].attn_w;
  if (a.in_features() != C || a.out_features() != 3 * C) {
    fail(std::format("c_attn 形状应为 ({}, {})，实际 ({}, {})。"
                     "注意 HuggingFace 的 Conv1D 是 (in, out) 布局，别转置。",
                     C, 3 * C, a.in_features(), a.out_features()));
  }
  return m;
}

GPT2 GPT2::load_quantized(const std::string& model_dir) {
  GPT2 m;
  m.cfg_ = read_config(model_dir);

  // 注意这里**没有**读文件，只是建立映射。这一步基本不花时间，
  // 500 MB 和 5 KB 的耗时一样。
  m.map_ = std::make_unique<MappedModel>(
      MappedModel::open(model_dir + "/gpt2_q8.infer"));
  const MappedModel& w = *m.map_;

  // 量化的大矩阵：拿 QView，零拷贝，指向映射区
  m.wte_q_ = w.get_qview("wte.weight");

  // 没量化的小张量：拷出来。加起来才 3 MB，不值得为它们搞零拷贝，
  // 而且 f32 路径的算子要求可写内存。
  m.wpe_ = w.get("wpe.weight");
  m.lnf_w_ = w.get("ln_f.weight");
  m.lnf_b_ = w.get("ln_f.bias");

  m.layers_.reserve(static_cast<std::size_t>(m.cfg_.n_layer));
  for (int i = 0; i < m.cfg_.n_layer; ++i) {
    const std::string p = std::format("h.{}.", i);
    Layer L;
    L.ln1_w = w.get(p + "ln_1.weight");
    L.ln1_b = w.get(p + "ln_1.bias");
    L.ln2_w = w.get(p + "ln_2.weight");
    L.ln2_b = w.get(p + "ln_2.bias");
    L.attn_w = LinearWeight::from_quantized(w.get_qview(p + "attn.c_attn.weight"));
    L.attn_proj_w = LinearWeight::from_quantized(w.get_qview(p + "attn.c_proj.weight"));
    L.fc_w = LinearWeight::from_quantized(w.get_qview(p + "mlp.c_fc.weight"));
    L.proj_w = LinearWeight::from_quantized(w.get_qview(p + "mlp.c_proj.weight"));
    L.attn_b = w.get(p + "attn.c_attn.bias");
    L.attn_proj_b = w.get(p + "attn.c_proj.bias");
    L.fc_b = w.get(p + "mlp.c_fc.bias");
    L.proj_b = w.get(p + "mlp.c_proj.bias");
    m.layers_.push_back(std::move(L));
  }

  const int C = m.cfg_.n_embd;
  if (m.wte_q_.cols != C || m.wte_q_.rows != m.cfg_.n_vocab) {
    fail(std::format("量化 wte 形状应为 ({}, {})，实际 ({}, {})",
                     m.cfg_.n_vocab, C, m.wte_q_.rows, m.wte_q_.cols));
  }
  // 量化导出时已经转置成 (out, in)，所以这里 in/out 的检查和 f32 版一致
  const LinearWeight& a = m.layers_[0].attn_w;
  if (a.in_features() != C || a.out_features() != 3 * C) {
    fail(std::format("量化 c_attn 应为 in={} out={}，实际 in={} out={}。"
                     "量化脚本会把 Conv1D 的 (in,out) 转置成 (out,in)。",
                     C, 3 * C, a.in_features(), a.out_features()));
  }
  return m;
}

// ---------------------------------------------------------------------------
// 词嵌入与输出层：两种权重表示的差异只体现在这两个函数里
// ---------------------------------------------------------------------------

Tensor GPT2::embed_tokens(std::span<const int> tokens) const {
  if (!is_quantized()) return ops::embedding(wte_, tokens);

  // 量化之后不能直接 memcpy 一行了，得逐行反量化。
  // 一行 768 个数，几乎不花时间。
  const i64 C = cfg_.n_embd;
  Tensor out = Tensor::zeros({static_cast<i64>(tokens.size()), C});
  std::span<float> ov = out.data();
  for (std::size_t i = 0; i < tokens.size(); ++i) {
    if (tokens[i] < 0 || tokens[i] >= cfg_.n_vocab) {
      fail(std::format("token id {} 越界，词表只有 {} 项", tokens[i], cfg_.n_vocab));
    }
    kernel::dequantize_row_q8(
        wte_q_, tokens[i],
        ov.subspan(i * static_cast<std::size_t>(C), static_cast<std::size_t>(C)));
  }
  return out;
}

Tensor GPT2::project_to_vocab(const Tensor& x) const {
  // 输出层复用词嵌入矩阵（weight tying）：logits = x @ wteᵀ
  if (!is_quantized()) return ops::linear(x, wte_);

  const Tensor cx = x.contiguous();
  Tensor out = Tensor::zeros({x.dim(0), cfg_.n_vocab});
  kernel::matmul_nt_q8_f32(cx.data(), wte_q_, out.data(), x.dim(0));
  return out;
}

