// 第 7 阶段：量化、mmap 与内存池。
//
//   ./build/examples/07_quant
//   ./build/examples/07_quant "Once upon a time" 40

#include <algorithm>
#include <chrono>
#include <format>
#include <iostream>
#include <string>
#include <vector>

#include "infer/arena.hpp"
#include "infer/gpt2.hpp"
#include "infer/kernel.hpp"
#include "infer/mmap_file.hpp"
#include "infer/model_file.hpp"
#include "infer/ops.hpp"
#include "infer/quant.hpp"
#include "infer/tokenizer.hpp"

using infer::Arena;
using infer::GPT2;
using infer::MappedModel;
using infer::QTensor;
using infer::Sampler;
using infer::SamplerConfig;
using infer::Tensor;
using infer::Tokenizer;
namespace ops = infer::ops;
namespace kernel = infer::kernel;

template <class... Args>
void println(std::format_string<Args...> fmt, Args&&... args) {
  std::cout << std::format(fmt, std::forward<Args>(args)...) << '\n';
}

void section(const char* title) {
  std::cout << std::format("\n\033[36m===== {} =====\033[0m\n", title);
}

using Clock = std::chrono::steady_clock;
double ms_since(Clock::time_point t0) {
  return std::chrono::duration<double, std::milli>(Clock::now() - t0).count();
}

int main(int argc, char** argv) {
  const std::string dir = INFER_MODEL_DIR;
  const std::string prompt = argc > 1 ? argv[1] : "The capital of France is";
  const int max_new = argc > 2 ? std::stoi(argv[2]) : 30;

  try {
    // ---------------------------------------------------------------------
    section("1. 量化在做什么");
    // ---------------------------------------------------------------------
    {
      // 用一小段真实权重看看
      const infer::ModelFile f = infer::ModelFile::load(dir + "/gpt2.infer");
      const Tensor w = f.get("h.0.mlp.c_proj.weight");
      const QTensor q = QTensor::from(w);
      const Tensor back = q.dequantize();

      println("拿 h.0.mlp.c_proj.weight 试一下，形状 ({}, {})", w.dim(0), w.dim(1));
      println("\n前 8 个数（第 0 行）:");
      std::span<const float> ov = w.data();
      std::span<const float> bv = back.data();
      std::string s1 = "  原值  ", s2 = "  还原  ", s3 = "  误差  ";
      for (int i = 0; i < 8; ++i) {
        s1 += std::format("{:>10.5f}", ov[static_cast<std::size_t>(i)]);
        s2 += std::format("{:>10.5f}", bv[static_cast<std::size_t>(i)]);
        s3 += std::format("{:>10.5f}",
                          bv[static_cast<std::size_t>(i)] - ov[static_cast<std::size_t>(i)]);
      }
      println("{}\n{}\n{}", s1, s2, s3);

      // 相对误差才有可比性：绝对误差 0.001 对 0.5 是小事，对 0.002 是灾难
      double se = 0, sq = 0;
      for (std::size_t i = 0; i < ov.size(); ++i) {
        const double d = bv[i] - ov[i];
        se += d * d;
        sq += static_cast<double>(ov[i]) * ov[i];
      }
      println("\n整个矩阵的相对误差（RMS）: {:.4f}%", std::sqrt(se / sq) * 100.0);
      println("存储: {:.1f} MB → {:.1f} MB  压缩 {:.2f}×",
              static_cast<double>(w.numel() * 4) / 1e6,
              static_cast<double>(q.view().bytes()) / 1e6,
              static_cast<double>(w.numel() * 4) / static_cast<double>(q.view().bytes()));
      println("\n压缩比是 3.56× 而不是 4×，因为每 32 个 int8 要带一个 4 字节的 scale：");
      println("  32×1 + 4 = 36 字节   vs   32×4 = 128 字节");
    }

    // ---------------------------------------------------------------------
    section("2. 分组量化 vs 整个张量一个 scale");
    // ---------------------------------------------------------------------
    {
      println("为什么要每 32 个数一组，而不是整个矩阵共享一个 scale？");
      println("因为只要有一个离群的大值，就会把 scale 撑大，");
      println("让其余所有数挤到 int8 的低位上。\n");

      const infer::ModelFile f = infer::ModelFile::load(dir + "/gpt2.infer");
      const Tensor w = f.get("h.0.attn.c_attn.weight");

      println("{:>12}{:>16}{:>14}", "组大小", "相对误差", "存储开销");
      for (infer::i64 g : {infer::i64{16}, 32, 64, 128, 768}) {
        const QTensor q = QTensor::from(w, g);
        const Tensor back = q.dequantize();
        double se = 0, sq = 0;
        std::span<const float> ov = w.data();
        std::span<const float> bv = back.data();
        for (std::size_t i = 0; i < ov.size(); ++i) {
          const double d = bv[i] - ov[i];
          se += d * d;
          sq += static_cast<double>(ov[i]) * ov[i];
        }
        const double ratio =
            static_cast<double>(w.numel() * 4) / static_cast<double>(q.view().bytes());
        println("{:>12}{:>15.4f}%{:>13.2f}×", g == 768 ? 768 : g,
                std::sqrt(se / sq) * 100.0, ratio);
      }
      println("\n组越小精度越好，但 scale 越占地方。32 是个常见的平衡点");
      println("（llama.cpp 的 Q8_0 用的就是 32）。");
    }

    // ---------------------------------------------------------------------
    section("3. 加载：read() vs mmap()");
    // ---------------------------------------------------------------------
    {
      auto t0 = Clock::now();
      const infer::ModelFile eager = infer::ModelFile::load(dir + "/gpt2.infer");
      const double read_ms = ms_since(t0);

      t0 = Clock::now();
      const MappedModel lazy = MappedModel::open(dir + "/gpt2_q8.infer");
      const double mmap_ms = ms_since(t0);

      println("{:<28}{:>12}{:>14}", "方式", "耗时 ms", "文件大小 MB");
      println("{:<28}{:>12.1f}{:>14.1f}", "read() 整个读进内存 (f32)", read_ms, 497.8);
      println("{:<28}{:>12.1f}{:>14.1f}", "mmap() 建立映射 (int8)", mmap_ms,
              static_cast<double>(lazy.mapped_bytes()) / 1e6);
      println("\nmmap 快得几乎不像真的，因为它**没有读任何数据** ——");
      println("只是在页表里记了一笔「这段地址对应这个文件」。");
      println("真正的读取推迟到第一次访问那一页的时候（缺页中断）。\n");

      t0 = Clock::now();
      lazy.prefault();
      println("把所有页都调进内存（prefault）: {:.0f} ms", ms_since(t0));
      println("所以「加载时间」不是消失了，是被摊到了第一次推理里。");
      println("但 mmap 还有两个 read() 给不了的好处：");
      println("  1. 用不到的权重永远不会被读进来");
      println("  2. 多个进程映射同一个文件，共享同一份物理内存");
      println("     —— 一台机器跑 8 个推理服务，权重只占一份");
    }

    // ---------------------------------------------------------------------
    section("4. 量化模型的加载与精度");
    // ---------------------------------------------------------------------
    Tokenizer tok = Tokenizer::load(dir + "/gpt2_vocab.bin", dir + "/gpt2_merges.bin");
    const std::vector<int> ids = tok.encode(prompt);

    auto t0 = Clock::now();
    GPT2 f32_model = GPT2::load(dir);
    const double f32_load = ms_since(t0);

    t0 = Clock::now();
    GPT2 q8_model = GPT2::load_quantized(dir);
    const double q8_load = ms_since(t0);

    println("{:<16}{:>12}{:>16}", "模型", "加载 ms", "权重内存 MB");
    println("{:<16}{:>12.0f}{:>16.1f}", "f32", f32_load,
            static_cast<double>(f32_model.weight_bytes()) / 1e6);
    println("{:<16}{:>12.0f}{:>16.1f}", "int8 + mmap", q8_load,
            static_cast<double>(q8_model.weight_bytes()) / 1e6);

    {
      // 量化误差会不会改变模型的判断？
      const Tensor lf = f32_model.forward(ids);
      const Tensor lq = q8_model.forward(ids);
      const Tensor last_f = lf.slice(0, lf.dim(0) - 1, lf.dim(0)).contiguous();
      const Tensor last_q = lq.slice(0, lq.dim(0) - 1, lq.dim(0)).contiguous();

      println("\nlogits 最大绝对偏差: {:.3f}", ops::max_abs_diff(lf, lq));
      println("top-1 预测: f32 = '{}', int8 = '{}'",
              tok.decode_one(static_cast<int>(ops::argmax(last_f))),
              tok.decode_one(static_cast<int>(ops::argmax(last_q))));

      // 比 logits 差多少更有意义的是：排序变了没有
      const Tensor pf = ops::softmax(last_f);
      const Tensor pq = ops::softmax(last_q);
      std::span<const float> a = pf.data();
      std::span<const float> b = pq.data();
      std::vector<int> ra(a.size()), rb(b.size());
      for (std::size_t i = 0; i < a.size(); ++i) { ra[i] = static_cast<int>(i); rb[i] = ra[i]; }
      std::partial_sort(ra.begin(), ra.begin() + 10, ra.end(),
                        [&](int x, int y) { return a[x] > a[y]; });
      std::partial_sort(rb.begin(), rb.begin() + 10, rb.end(),
                        [&](int x, int y) { return b[x] > b[y]; });

      println("\n{:>4}  {:<14}{:>9}   {:<14}{:>9}", "", "f32 top-10", "概率",
              "int8 top-10", "概率");
      int same = 0;
      for (int i = 0; i < 10; ++i) {
        if (ra[static_cast<std::size_t>(i)] == rb[static_cast<std::size_t>(i)]) ++same;
        println("{:>4}. {:<14}{:>8.2f}%   {:<14}{:>8.2f}%", i + 1,
                std::format("'{}'", tok.decode_one(ra[static_cast<std::size_t>(i)])),
                a[static_cast<std::size_t>(ra[static_cast<std::size_t>(i)])] * 100.0F,
                std::format("'{}'", tok.decode_one(rb[static_cast<std::size_t>(i)])),
                b[static_cast<std::size_t>(rb[static_cast<std::size_t>(i)])] * 100.0F);
      }
      println("\ntop-10 里有 {}/10 的位置完全一致。", same);
      println("权重误差 0.6%，但模型的**判断**基本没变 —— 这就是量化能用的原因：");
      println("神经网络对权重的小扰动有相当强的容忍度。");
    }

    // ---------------------------------------------------------------------
    section("5. 速度：量化到底快了多少");
    // ---------------------------------------------------------------------
    {
      println("decode 阶段卡在内存带宽上，权重小了 3.5 倍，理论上就该快 3.5 倍。");
      println("实际呢？\n");
      println("{:<16}{:>14}{:>14}{:>12}", "模型", "prefill ms", "decode ms/词", "token/s");

      struct Row { const char* name; GPT2* m; };
      const Row rows[] = {{"f32", &f32_model}, {"int8", &q8_model}};
      double q8_tps = 0, f32_tps = 0;
      for (const auto& r : rows) {
        double best = 1e30, prefill = 1e30;
        for (int rep = 0; rep < 3; ++rep) {
          Sampler g{SamplerConfig{.temperature = 0.0F}};
          GPT2::GenStats st;
          r.m->generate(ids, 8, g, &st);
          best = std::min(best, st.decode_ms / std::max(st.generated - 1, 1));
          prefill = std::min(prefill, st.prefill_ms);
        }
        const double tps = 1000.0 / best;
        if (std::string(r.name) == "int8") q8_tps = tps; else f32_tps = tps;
        println("{:<16}{:>14.0f}{:>14.1f}{:>12.1f}", r.name, prefill, best, tps);
      }
      println("\n加速 {:.2f}×", q8_tps / f32_tps);
      println("\n达不到 3.5× 的原因：");
      println("  1. 只有大矩阵量化了，LayerNorm / bias / KV-Cache 还是 f32");
      println("  2. int8 读进来要转成 float 才能算，转换本身有开销");
      println("  3. 权重变小后，瓶颈开始从带宽往算力那边移");
      println("     —— 优化到一定程度，瓶颈就换人了，这很正常");
    }

