// 算 y[row] = Σ_g scale[row][g] · (x · q[row][g组])
//
// 关键在于**组内先用整数值累加，出组才乘一次 scale**。
// 如果每个元素都乘 scale，乘法次数翻倍，而且精度还更差
// （小数反复相乘累积舍入误差）。
float dot_row_q8(const float* x, const std::int8_t* q, const float* scales,
                 i64 cols, i64 group) {
  float total = 0.0F;
  i64 gi = 0;
  for (i64 base = 0; base < cols; base += group, ++gi) {
    const i64 len = std::min(group, cols - base);
    const float s = scales[gi];
    if (s == 0.0F) continue;  // 整组都是 0，跳过

#if INFER_HAS_AVX2
    // group 是 32，正好 4 个 AVX2 向量。4 个独立累加器把 FMA 流水线填满。
    if (len == 32) {
      __m256 a0 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 0), load8_i8_as_f32(q + base + 0));
      __m256 a1 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 8), load8_i8_as_f32(q + base + 8));
      __m256 a2 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 16), load8_i8_as_f32(q + base + 16));
      __m256 a3 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 24), load8_i8_as_f32(q + base + 24));
      total += s * hsum(_mm256_add_ps(_mm256_add_ps(a0, a1), _mm256_add_ps(a2, a3)));
      continue;
    }
#endif
    float acc = 0.0F;
    for (i64 i = 0; i < len; ++i) {
      acc += x[base + i] * static_cast<float>(q[base + i]);
    }
    total += s * acc;
  }
  return total;
}

input.new_string:
// 算 y[row] = Σ_g scale[row][g] · (x · q[row][g组])
//
// 两个关键点。
//
// 【一】组内先累加，出组才乘 scale。
// 如果每个元素都乘 scale，乘法次数翻倍，精度还更差
// （小数反复相乘会累积舍入误差）。
//
// 【二】水平求和（hsum）只在最后做一次。
// 第一版我在每组结束时就 hsum 一次，K=768 时那是 24 次。
// hsum 要好几条 shuffle 指令、还有延迟，这一项直接让 int8 路径
// 从「带宽瓶颈」变成了「算力瓶颈」—— 比 f32 版还慢。
//
// 能省掉是因为 hsum 是线性的：
//     Σ_g s_g · hsum(v_g)  ==  hsum( Σ_g s_g · v_g )
// 所以把 scale 广播成向量，跨组在向量里累加，最后才 hsum 一次。
float dot_row_q8(const float* x, const std::int8_t* q, const float* scales,
                 i64 cols, i64 group) {
#if INFER_HAS_AVX2
  if (group == 32 && cols % 32 == 0) {
    // 两个跨组累加器，让 FMA 流水线不被单条依赖链卡住
    __m256 t0 = _mm256_setzero_ps();
    __m256 t1 = _mm256_setzero_ps();
    i64 gi = 0;
    for (i64 base = 0; base < cols; base += 32, ++gi) {
      const __m256 s = _mm256_set1_ps(scales[gi]);

      __m256 p0 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 0),
                                load8_i8_as_f32(q + base + 0));
      p0 = _mm256_fmadd_ps(_mm256_loadu_ps(x + base + 8),
                           load8_i8_as_f32(q + base + 8), p0);
      __m256 p1 = _mm256_mul_ps(_mm256_loadu_ps(x + base + 16),
                                load8_i8_as_f32(q + base + 16));
      p1 = _mm256_fmadd_ps(_mm256_loadu_ps(x + base + 24),
                           load8_i8_as_f32(q + base + 24), p1);

      t0 = _mm256_fmadd_ps(p0, s, t0);
      t1 = _mm256_fmadd_ps(p1, s, t1);
    }
    return hsum(_mm256_add_ps(t0, t1));
  }
#endif
  // 通用回退路径：组大小不是 32、或 cols 不是 32 的整数倍
  float total = 0.0F;
  i64 gi = 0;
  for (i64 base = 0; base < cols; base += group, ++gi) {
    const i64 len = std::min(group, cols - base);
    const float s = scales[gi];
    if (s == 0.0F) continue;
    float acc = 0.0F;
    for (i64 i = 0; i < len; ++i) {
      acc += x[base + i] * static_cast<float>(q[base + i]);
    }
    total += s * acc;
  }
  return total;
}

// ---------------------------------------------------------------------------
// 形状：shape = {2, 3} 表示 2 行 3 列。标量的 shape 是空的 {}。
//
// 这里本来是 `using Shape = std::vector<i64>`，阶段 7 换成了内联存储。
// 起因是给 Arena 做 benchmark 时发现一个尴尬的事实：
//
//   Arena 消掉了「张量数据」的堆分配，但每创建一个 Tensor 仍然有
//   **两次** vector 分配 —— shape_ 一次，strides_ 一次。
//   于是 arena.tensor() 只比 Tensor::zeros() 快 1.2 倍，白忙一场。
//
// 维度数几乎总是 1~4（GPT-2 全是 2 维），为这么点数据上堆完全不值。
// 直接把它们存在对象里面，分配次数归零。
//
// 上限定成 4 维、超了就抛异常，是跟 ggml 学的。
// PyTorch 的 SmallVector 会在超出内联容量时回退到堆上，更通用，
// 但要多管一个指针；推理引擎里 4 维够用，就选了简单的那条路。
// ---------------------------------------------------------------------------
class Shape {
 public:
  static constexpr std::size_t kMaxDims = 4;
  using value_type = i64;
  using iterator = i64*;
  using const_iterator = const i64*;

  Shape() = default;
  Shape(std::initializer_list<i64> dims);  // 允许隐式：zeros({2, 3})
  explicit Shape(std::size_t n) { resize(n); }

  [[nodiscard]] std::size_t size() const noexcept { return n_; }
  [[nodiscard]] bool empty() const noexcept { return n_ == 0; }
  void resize(std::size_t n);

  [[nodiscard]] i64& operator[](std::size_t i) noexcept { return dims_[i]; }
  [[nodiscard]] const i64& operator[](std::size_t i) const noexcept { return dims_[i]; }
  [[nodiscard]] i64& at(std::size_t i);
  [[nodiscard]] const i64& at(std::size_t i) const;
  [[nodiscard]] i64& back() noexcept { return dims_[n_ - 1]; }
  [[nodiscard]] const i64& back() const noexcept { return dims_[n_ - 1]; }

  [[nodiscard]] i64* data() noexcept { return dims_.data(); }
  [[nodiscard]] const i64* data() const noexcept { return dims_.data(); }
  [[nodiscard]] iterator begin() noexcept { return dims_.data(); }
  [[nodiscard]] iterator end() noexcept { return dims_.data() + n_; }
  [[nodiscard]] const_iterator begin() const noexcept { return dims_.data(); }
  [[nodiscard]] const_iterator end() const noexcept { return dims_.data() + n_; }

  [[nodiscard]] bool operator==(const Shape& other) const noexcept {
    return n_ == other.n_ && std::equal(begin(), end(), other.begin());
  }

 private:
  std::array<i64, kMaxDims> dims_{};
  std::uint32_t n_ = 0;
};

