Shape::Shape(std::initializer_list<i64> dims) {
  if (dims.size() > kMaxDims) {
    fail(std::format("最多支持 {} 维，给了 {} 维。"
                     "要更多维的话，把 Shape 的 kMaxDims 改大，"
                     "或者改成超出内联容量时回退到堆上。",
                     kMaxDims, dims.size()));
  }
  n_ = static_cast<std::uint32_t>(dims.size());
  std::copy(dims.begin(), dims.end(), dims_.begin());
}

void Shape::resize(std::size_t n) {
  if (n > kMaxDims) {
    fail(std::format("最多支持 {} 维，想要 {} 维", kMaxDims, n));
  }
  // 缩小时把尾部清零，避免残留的旧值在某个地方被误读
  for (std::size_t i = n; i < n_; ++i) dims_[i] = 0;
  n_ = static_cast<std::uint32_t>(n);
}

i64& Shape::at(std::size_t i) {
  if (i >= n_) fail(std::format("维度下标 {} 越界（共 {} 维）", i, n_));
  return dims_[i];
}

const i64& Shape::at(std::size_t i) const {
  if (i >= n_) fail(std::format("维度下标 {} 越界（共 {} 维）", i, n_));
  return dims_[i];
}

