// 阶段 7 的测试：INT8 量化、mmap 零拷贝加载、Arena 内存池、内联 Shape。
//
// 需要量化模型的用例会在文件缺失时自动跳过：
//   .venv/bin/python tools/quantize_gpt2.py

#include <atomic>
#include <cmath>
#include <filesystem>
#include <numeric>
#include <random>
#include <set>

#include "infer/arena.hpp"
#include "infer/gpt2.hpp"
#include "infer/kernel.hpp"
#include "infer/mmap_file.hpp"
#include "infer/model_file.hpp"
#include "infer/ops.hpp"
#include "infer/quant.hpp"
#include "infer/tokenizer.hpp"
#include "minitest.hpp"

using infer::Arena;
using infer::GPT2;
using infer::i64;
using infer::MappedFile;
using infer::MappedModel;
using infer::QTensor;
using infer::QView;
using infer::Sampler;
using infer::SamplerConfig;
using infer::Shape;
using infer::Tensor;
using infer::Tokenizer;
namespace ops = infer::ops;
namespace kernel = infer::kernel;

namespace {

std::string model_dir() { return INFER_MODEL_DIR; }

bool has_q8_model() {
  return std::filesystem::exists(model_dir() + "/gpt2_q8.infer") &&
         std::filesystem::exists(model_dir() + "/gpt2_vocab.bin");
}
bool has_f32_model() {
  return std::filesystem::exists(model_dir() + "/gpt2.infer");
}

Tensor random_tensor(std::initializer_list<i64> shape, unsigned seed,
                     float scale = 1.0F) {
  Tensor t = Tensor::zeros(shape);
  std::mt19937 rng(seed);
  std::normal_distribution<float> d(0.0F, scale);
  for (float& v : t.data()) v = d(rng);
  return t;
}

// 相对误差（RMS）。绝对误差没有可比性：0.001 对 0.5 是小事，对 0.002 是灾难。
double rel_error(const Tensor& a, const Tensor& b) {
  double se = 0, sq = 0;
  std::span<const float> x = a.data();
  std::span<const float> y = b.data();
  for (std::size_t i = 0; i < x.size(); ++i) {
    const double d = static_cast<double>(y[i]) - x[i];
    se += d * d;
    sq += static_cast<double>(x[i]) * x[i];
  }
  return std::sqrt(se / sq);
}

}  // namespace

