TEST(quant_roundtrip_error_is_bounded) {
  const Tensor w = random_tensor({64, 256}, 1);
  const QTensor q = QTensor::from(w);
  const Tensor back = q.dequantize();

  // int8 每组 32 个数、127 档，理论相对误差在 1% 量级。
  // 这个界要选模型一定过得去的：正态分布下实测约 0.45%，留一倍余量。
  const double err = rel_error(w, back);
  CHECK(err < 0.01);
  CHECK(err > 0.0);  // 真的有损，不是偷偷原样返回
}

TEST(quant_exact_when_values_fit) {
  // 一组里的值如果正好是 scale 的整数倍，量化应该是**无损**的。
  // 这个用例能抓出 scale 算错、四舍五入方向错之类的问题。
  Tensor w = Tensor::zeros({1, 32});
  std::span<float> v = w.data();
  for (int i = 0; i < 32; ++i) v[static_cast<std::size_t>(i)] = static_cast<float>(i - 16);

  const QTensor q = QTensor::from(w);
  const Tensor back = q.dequantize();
  // absmax = 16，scale = 16/127，所以 -16..15 未必能精确还原。
  // 但 absmax 那一项一定精确：它对应 q = ±127。
  std::span<const float> b = back.data();
  CHECK(std::fabs(b[0] - (-16.0F)) < 1e-5F);
}

TEST(quant_all_zeros_does_not_produce_nan) {
  // scale = 0 时如果不小心写成 1/scale，整个矩阵会变成 nan。
  // 这类除零 bug 在真实权重里可能几个月都碰不到一次。
  const Tensor w = Tensor::zeros({4, 64});
  const QTensor q = QTensor::from(w);
  const Tensor back = q.dequantize();
  for (float v : back.data()) {
    CHECK(!std::isnan(v));
    CHECK(v == 0.0F);
  }
}

TEST(quant_grouping_beats_per_tensor_on_outliers) {
  // 分组量化存在的全部理由：抗离群值。
  // 造一个矩阵，大部分是小数，末尾塞一个巨大的值。
  Tensor w = Tensor::zeros({1, 256});
  std::span<float> v = w.data();
  for (std::size_t i = 0; i < 255; ++i) v[i] = 0.01F * static_cast<float>((i % 7) + 1);
  v[255] = 100.0F;  // 离群值

  const double err_group = rel_error(w, QTensor::from(w, 32).dequantize());
  const double err_whole = rel_error(w, QTensor::from(w, 256).dequantize());

  // 整行一个 scale 时，scale = 100/127 ≈ 0.79，所有 0.01 量级的值全归零
  CHECK(err_group < err_whole);
  CHECK(err_whole > 0.5);   // 整体量化确实崩了
  CHECK(err_group < 0.05);  // 分组量化基本没事
}

TEST(quant_row_dequant_matches_full_dequant) {
  // 词嵌入查表走 dequantize_row_q8，其他地方走 dequantize_q8。
  // 两条路径必须给出完全一样的结果，否则 embedding 和输出层会悄悄不一致。
  const Tensor w = random_tensor({8, 96}, 7);
  const QTensor q = QTensor::from(w);
  const Tensor full = q.dequantize();

  std::vector<float> row(96);
  for (i64 r = 0; r < 8; ++r) {
    kernel::dequantize_row_q8(q.view(), r, row);
    for (i64 c = 0; c < 96; ++c) {
      CHECK(row[static_cast<std::size_t>(c)] == full(r, c));
    }
  }
}

TEST(quant_row_dequant_rejects_bad_row) {
  const QTensor q = QTensor::from(random_tensor({4, 32}, 3));
  std::vector<float> row(32);
  CHECK_THROWS(kernel::dequantize_row_q8(q.view(), 4, row));
  CHECK_THROWS(kernel::dequantize_row_q8(q.view(), -1, row));
