TEST(qview_reports_correct_byte_count) {
  const QTensor q = QTensor::from(random_tensor({10, 64}, 5));
  const QView v = q.view();
  CHECK(v.groups_per_row() == 2);            // 64 / 32
  CHECK(v.bytes() == 10 * 64 + 10 * 2 * 4);  // 数据 + scale
  // 压缩比应该是 3.56×，不是 4×
  const double ratio = static_cast<double>(10 * 64 * 4) / static_cast<double>(v.bytes());
  CHECK(std::fabs(ratio - 3.5555) < 0.01);
}

