TEST(q8_matmul_matches_dequantized_reference) {
  // 判据要选对：量化 matmul 不该去对比「f32 权重的结果」（那里面混了量化误差），
  // 而该对比「反量化后的权重做 f32 matmul」—— 这两者应该几乎完全相等，
  // 差别只来自浮点累加顺序。这样才能把 kernel 的 bug 和量化的固有误差分开。
  const Tensor w = random_tensor({48, 96}, 11);  // (out, in)
  const QTensor q = QTensor::from(w);
  const Tensor deq = q.dequantize();

  for (i64 M : {i64{1}, 2, 5}) {
    const Tensor x = random_tensor({M, 96}, static_cast<unsigned>(M) + 20);
    Tensor got = Tensor::zeros({M, 48});
    kernel::matmul_nt_q8_f32(x.data(), q.view(), got.data(), M);

    const Tensor want = ops::linear(x, deq);  // (out, in) 布局
    CHECK(ops::max_abs_diff(got, want) < 1e-3F);
  }
}

TEST(q8_matmul_handles_non_multiple_of_group) {
  // K 不是 32 的整数倍时会走标量回退路径，这条路径同样必须对。
  for (i64 K : {i64{1}, 17, 31, 33, 100}) {
    const Tensor w = random_tensor({7, 1}, 1);  // 占位，下面重建
    (void)w;
    Tensor ww = Tensor::zeros({7, K});
    std::mt19937 rng(static_cast<unsigned>(K));
    std::normal_distribution<float> d(0.0F, 1.0F);
    for (float& v : ww.data()) v = d(rng);

    const QTensor q = QTensor::from(ww);
    const Tensor deq = q.dequantize();
    Tensor x = Tensor::zeros({1, K});
    for (float& v : x.data()) v = d(rng);

    Tensor got = Tensor::zeros({1, 7});
    kernel::matmul_nt_q8_f32(x.data(), q.view(), got.data(), 1);
    const Tensor want = ops::linear(x, deq);
    CHECK(ops::max_abs_diff(got, want) < 1e-3F);
  }
}

TEST(q8_matmul_is_deterministic_across_thread_counts) {
  // 并行是按输出列切的，每列独立算，所以结果必须**逐位相同**。
  // 一旦出现跨线程的累加，这个用例会立刻失败。
  const Tensor w = random_tensor({512, 256}, 13);
  const QTensor q = QTensor::from(w);
  const Tensor x = random_tensor({1, 256}, 14);

  const int saved = kernel::get_num_threads();
  Tensor ref = Tensor::zeros({1, 512});
  kernel::set_num_threads(1);
  kernel::matmul_nt_q8_f32(x.data(), q.view(), ref.data(), 1);

  for (int nt : {2, 4, 8}) {
    kernel::set_num_threads(nt);
    Tensor got = Tensor::zeros({1, 512});
    kernel::matmul_nt_q8_f32(x.data(), q.view(), got.data(), 1);
    for (i64 j = 0; j < 512; ++j) {
      CHECK(got(0, j) == ref(0, j));  // 逐位，不是近似
    }
  }
  kernel::set_num_threads(saved);
}

TEST(q8_matmul_rejects_shape_mismatch) {
  const QTensor q = QTensor::from(random_tensor({8, 32}, 1));
  const Tensor x = random_tensor({1, 64}, 2);  // K 对不上
  Tensor out = Tensor::zeros({1, 8});
  // 空视图也必须拦住，否则是空指针解引用
  CHECK_THROWS(kernel::matmul_nt_q8_f32(x.data(), QView{}, out.data(), 1));
}

