TEST(arena_allocations_are_aligned_and_distinct) {
  Arena a(1 << 16);
  std::span<float> x = a.alloc_floats(10);
  std::span<float> y = a.alloc_floats(10);

  CHECK(x.size() == 10);
  // 64 字节对齐：既满足 AVX2 对齐加载，也保证两个分配不共享 cache line
  CHECK(reinterpret_cast<std::uintptr_t>(x.data()) % 64 == 0);
  CHECK(reinterpret_cast<std::uintptr_t>(y.data()) % 64 == 0);
  CHECK(y.data() != x.data());
  // 写 x 不能影响 y —— 区间不重叠
  x[9] = 1.0F;
  y[0] = 2.0F;
  CHECK(x[9] == 1.0F);
}

TEST(arena_reset_reuses_the_same_memory) {
  Arena a(1 << 16);
  const float* first = a.alloc_floats(16).data();
  a.reset();
  const float* again = a.alloc_floats(16).data();
  // reset 只是把指针挪回开头，所以地址必须一样。
  // 这正是 arena 对 cache 友好的原因：每次前向都碰同一片内存。
  CHECK(first == again);
  CHECK(a.used() > 0);
}

TEST(arena_tracks_peak_across_resets) {
  Arena a(1 << 16);
  a.alloc_floats(100);
  const std::size_t p1 = a.peak();
  a.reset();
  CHECK(a.used() == 0);
  CHECK(a.peak() == p1);  // reset 不该清掉历史水位，那是用来定容量的
  a.alloc_floats(10);
  CHECK(a.peak() == p1);  // 没超过就不涨
}

TEST(arena_reports_capacity_overflow_clearly) {
  Arena a(1024);
  bool threw = false;
  try {
    a.alloc_floats(10000);
  } catch (const std::exception& e) {
    threw = true;
    // 报错信息里必须带上数字，否则只能靠二分猜容量
    const std::string msg = e.what();
    CHECK(msg.find("MB") != std::string::npos);
  }
  CHECK(threw);
}

TEST(arena_tensor_data_lives_in_the_pool) {
  Arena a(1 << 16);
  const Tensor t = a.tensor({4, 8});
  CHECK(t.numel() == 32);
  CHECK(t.is_contiguous());
  // 张量的数据必须真的落在池子里，而不是偷偷又 malloc 了一块
  const auto* p = reinterpret_cast<const std::byte*>(t.data().data());
  std::span<float> probe = a.alloc_floats(1);
  const auto* q = reinterpret_cast<const std::byte*>(probe.data());
  CHECK(p < q);
  CHECK(static_cast<std::size_t>(q - p) < a.capacity());
}

TEST(arena_tensor_survives_while_arena_lives) {
  // shared_ptr 的别名构造让张量持有对整个池的引用计数，
  // 所以池还在的时候张量一定是有效的。
  Arena a(1 << 16);
  Tensor t = a.tensor({2, 2});
  t.data()[0] = 42.0F;
  {
    const Tensor copy = t;  // 拷贝只增加引用计数
    CHECK(copy.data()[0] == 42.0F);
  }
  CHECK(t.data()[0] == 42.0F);
}

TEST(arena_rejects_oversized_tensor) {
  Arena a(256);
  CHECK_THROWS(a.tensor({1000, 1000}));
}

