TEST(q8_model_agrees_with_f32_on_top1) {
  if (!has_q8_model() || !has_f32_model()) SKIP("需要 f32 和 int8 两个模型");

  const GPT2 f32m = GPT2::load(model_dir());
  const GPT2 q8m = GPT2::load_quantized(model_dir());
  CHECK(!f32m.is_quantized());
  CHECK(q8m.is_quantized());

  // 量化后权重小了 3.5 倍
  CHECK(q8m.weight_bytes() * 3 < f32m.weight_bytes());

  // 判据的选择很讲究。这里**不能**要求 logits 接近 ——
  // 量化误差会让 logits 差到 1.0 以上，那是量化的固有性质，不是 bug。
  // 该要求的是「模型的判断没变」，而判断体现在 top-1 和 top-k 集合上。
  const std::vector<int> ids{464, 3139, 286, 4881, 318};  // "The capital of France is"
  const Tensor lf = f32m.forward(ids);
  const Tensor lq = q8m.forward(ids);
  CHECK(lf.dim(0) == lq.dim(0));

  // 每个位置的 top-1 都该一致
  for (i64 t = 0; t < lf.dim(0); ++t) {
    const Tensor rf = lf.slice(0, t, t + 1).contiguous();
    const Tensor rq = lq.slice(0, t, t + 1).contiguous();
    CHECK(ops::argmax(rf) == ops::argmax(rq));
  }
}

TEST(q8_model_top10_set_mostly_overlaps_f32) {
  if (!has_q8_model() || !has_f32_model()) SKIP("需要 f32 和 int8 两个模型");
  const GPT2 f32m = GPT2::load(model_dir());
  const GPT2 q8m = GPT2::load_quantized(model_dir());

  const std::vector<int> ids{464, 3139, 286, 4881, 318};
  auto top10 = [](const GPT2& m, const std::vector<int>& in) {
    const Tensor l = m.forward(in);
    const Tensor last = l.slice(0, l.dim(0) - 1, l.dim(0)).contiguous();
    std::span<const float> v = last.data();
    std::vector<int> idx(v.size());
    std::iota(idx.begin(), idx.end(), 0);
    std::partial_sort(idx.begin(), idx.begin() + 10, idx.end(),
                      [&](int a, int b) { return v[static_cast<std::size_t>(a)] >
                                                 v[static_cast<std::size_t>(b)]; });
    return std::set<int>(idx.begin(), idx.begin() + 10);
  };

  const std::set<int> sf = top10(f32m, ids);
  const std::set<int> sq = top10(q8m, ids);
  std::vector<int> both;
  std::set_intersection(sf.begin(), sf.end(), sq.begin(), sq.end(),
                        std::back_inserter(both));
  // 看集合重叠而不是位置一致：相邻两名概率只差 0.2% 时，
  // 谁在前谁在后对生成结果没有影响，用位置做判据会得到一个又脆又没意义的测试。
  CHECK(both.size() >= 8);
}

