TEST(q8_model_kv_cache_matches_full_recompute) {
  if (!has_q8_model()) SKIP("需要 models/gpt2_q8.infer");
  // 量化路径也得和 KV-Cache 配合正确。缓存里存的仍是 f32，
  // 但喂给它的 K/V 来自量化的 c_attn，两条路径必须一致。
  const GPT2 m = GPT2::load_quantized(model_dir());
  const std::vector<int> ids{464, 3139, 286, 4881, 318};

  const Tensor full = m.forward(ids);
  const Tensor full_last = full.slice(0, full.dim(0) - 1, full.dim(0)).contiguous();

  infer::KVCache cache(m.config(), 16);
  Tensor step;
  for (std::size_t i = 0; i < ids.size(); ++i) {
    step = m.forward_with_cache(std::span<const int>{&ids[i], 1}, cache);
  }
  CHECK(ops::max_abs_diff(full_last, step) < 1e-3F);
  CHECK(ops::argmax(full_last) == ops::argmax(step));
}

TEST(q8_model_generation_is_reproducible) {
