Arena::Arena(std::size_t capacity_bytes)
    : buf_(std::make_shared<std::byte[]>(round_up(capacity_bytes, kAlign))),
      capacity_(round_up(capacity_bytes, kAlign)) {}

std::span<float> Arena::alloc_floats(std::size_t n) {
  const std::size_t want = round_up(n * sizeof(float), kAlign);
  if (used_ + want > capacity_) fail_capacity(used_, want, capacity_);
  auto* p = reinterpret_cast<float*>(buf_.get() + used_);
  used_ += want;
  peak_ = std::max(peak_, used_);
  ++allocs_;
  return {p, n};
}

