TEST(quant_grouping_beats_per_tensor_on_outliers) {
  // 分组量化存在的全部理由：抗离群值。
  // 造一个矩阵，大部分是小数，末尾塞一个巨大的值。
  Tensor w = Tensor::zeros({1, 256});
  std::span<float> v = w.data();
  for (std::size_t i = 0; i < 255; ++i) v[i] = 0.01F * static_cast<float>((i % 7) + 1);
  v[255] = 100.0F;  // 离群值

  const Tensor deq_group = QTensor::from(w, 32).dequantize();
  const Tensor deq_whole = QTensor::from(w, 256).dequantize();

  // 判据的选择在这里非常关键，我第一版就选错了。
  //
  // 一开始我用全局相对误差（RMS），断言整体量化的误差 > 50%。测试红了，
  // 实测只有 0.63%。原因是**分母被那个离群值主导**了：
  //     Σw² ≈ 100² + 255×0.04² ≈ 10000.4
  //   而 100 本身被精确还原（它对应 q = ±127），
  //     Σ(误差)² ≈ 255×0.04² ≈ 0.4
  //   于是 RMS 相对误差 = sqrt(0.4/10000) ≈ 0.6%，看起来毫无问题。
  //
  // 但小值其实**全都变成 0 了**，这是彻底的信息丢失。
  // 教训：有离群值时，全局 RMS 误差会被大值主导，把小值的灾难完全掩盖掉。
  // 该直接去数「有多少个值被压成了 0」。
  int zeroed_whole = 0, zeroed_group = 0;
  std::span<const float> gw = deq_whole.data();
  std::span<const float> gg = deq_group.data();
  for (std::size_t i = 0; i < 255; ++i) {
    if (gw[i] == 0.0F) ++zeroed_whole;
    if (gg[i] == 0.0F) ++zeroed_group;
  }

  // 整行一个 scale：scale = 100/127 ≈ 0.787，
  // 所有 0.01~0.07 的值除以它都不到 0.1，四舍五入全归零
  CHECK(zeroed_whole == 255);
  // 分组之后，离群值被关在自己那一组里，其余 7 组各有自己的小 scale
  CHECK(zeroed_group == 0);

  // 离群值本身两种方式都能精确还原 —— 它就是那个定 scale 的人
  CHECK(std::fabs(gw[255] - 100.0F) < 0.5F);
  CHECK(std::fabs(gg[255] - 100.0F) < 0.5F);
}

