void matmul_nt_q8_f32(std::span<const float> x, const QView& w, std::span<float> y,
                      i64 M) {

input.new_string:
#if INFER_HAS_AVX2
// M 方向的微内核：4 个样本共用一次权重解包。
//
// 这是阶段 8 和 llama.cpp 对标之后加的。上面 dot_row_q8 的注释里我已经
// 写了「真正的开销在把 1 字节变成 4 字节」，却漏掉了一个推论：
// 既然贵的是解包权重，那 M 个样本就该**共用**这一次解包。
//
// 单样本版处理 32 个权重值要：
//     解包 12 条指令（4 × load + cvtepi8_epi32 + cvtepi32_ps）
//   + 乘加  4 条 FMA
//   = 16 条，其中 75% 花在解包上
//
// prefill 时 M=512，同一个权重行被解包了 512 次。四个样本共用一次：
//     解包 12 条 + 乘加 16 条 + scale 4 条 = 32 条，服务 4 个点积
// 对比单样本版的 4 × 16 = 64 条，指令数减半。
//
// 寄存器预算：4 个 w + 4 个累加器 + 1 个临时 + 1 个 scale = 10 个 YMM，
// 16 个够用。想扩到 8 个样本就会溢出，所以停在 4。
void dot_row_q8_x4(const float* x, i64 x_stride, const std::int8_t* q, const float* scales,
                   i64 cols, float* out) {
  __m256 acc0 = _mm256_setzero_ps();
  __m256 acc1 = _mm256_setzero_ps();
  __m256 acc2 = _mm256_setzero_ps();
  __m256 acc3 = _mm256_setzero_ps();

  i64 gi = 0;
  for (i64 base = 0; base < cols; base += 32, ++gi) {
    // 解包一次，下面四个样本都用它
    const __m256 w0 = load8_i8_as_f32(q + base + 0);
    const __m256 w1 = load8_i8_as_f32(q + base + 8);
    const __m256 w2 = load8_i8_as_f32(q + base + 16);
    const __m256 w3 = load8_i8_as_f32(q + base + 24);
    const __m256 s = _mm256_set1_ps(scales[gi]);

    auto group_dot = [&](const float* xm) {
      __m256 p = _mm256_mul_ps(_mm256_loadu_ps(xm + 0), w0);
      p = _mm256_fmadd_ps(_mm256_loadu_ps(xm + 8), w1, p);
      p = _mm256_fmadd_ps(_mm256_loadu_ps(xm + 16), w2, p);
      p = _mm256_fmadd_ps(_mm256_loadu_ps(xm + 24), w3, p);
      return p;
    };

    // scale 在出组时才乘，理由和单样本版一样（见 dot_row_q8 的注释【一】）
    acc0 = _mm256_fmadd_ps(group_dot(x + 0 * x_stride + base), s, acc0);
    acc1 = _mm256_fmadd_ps(group_dot(x + 1 * x_stride + base), s, acc1);
    acc2 = _mm256_fmadd_ps(group_dot(x + 2 * x_stride + base), s, acc2);
    acc3 = _mm256_fmadd_ps(group_dot(x + 3 * x_stride + base), s, acc3);
  }

  // hsum 同样只在最后做（注释【二】）
  out[0] = hsum(acc0);
  out[1] = hsum(acc1);
  out[2] = hsum(acc2);
  out[3] = hsum(acc3);
}
#endif

}  // namespace

